)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les afirmacions següents sobre l''aplicació temporal de les lleis penals NO és correcta, segons l''article 2 del Codi penal?', 'L''article 2.2 CP dona efecte retroactiu a les lleis penals favorables al reu encara que, en entrar en vigor, hagi recaigut sentència ferma i el subjecte estigui complint condemna. Les altres tres afirmacions reprodueixen els apartats 1 i 2 del mateix article.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 2 CP', 'No obstante, tendrán efecto retroactivo aquellas leyes penales que favorezcan al reo, aunque al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena.', null, '64f90d24f91323a4c65ce0bd7d0b2391bc6181a6f3a54561e039d1efb3c22e30', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '64f90d24f91323a4c65ce0bd7d0b2391bc6181a6f3a54561e039d1efb3c22e30')
  returning id
