  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les lleis penals favorables al reu no tenen efecte retroactiu si ja ha recaigut sentència ferma.', true), ('B', 'Les lleis que estableixen mesures de seguretat no tenen efecte retroactiu.', false), ('C', 'En cas de dubte sobre la determinació de la llei més favorable, s''ha d''escoltar el reu.', false), ('D', 'Els fets comesos sota la vigència d''una llei temporal es jutgen conforme a aquesta, llevat que es disposi expressament el contrari.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
