with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 6.1 del Codi penal, les mesures de seguretat es fonamenten en:', 'Les mesures de seguretat tenen com a fonament la perillositat criminal, que s''ha d''haver exterioritzat en la comissió d''un fet previst com a delicte; no hi ha mesures predelictuals.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 6.1 CP', '1. Las medidas de seguridad se fundamentan en la peligrosidad criminal del sujeto al que se impongan, exteriorizada en la comisión de un hecho previsto como delito.', null, 'abdfa09359e2b8aaba6e46c07837aa4402ec1c0ef508118f3a889045ba0c3e74', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'abdfa09359e2b8aaba6e46c07837aa4402ec1c0ef508118f3a889045ba0c3e74')
