)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les afirmacions següents sobre les mesures de seguretat NO és correcta, segons el títol preliminar del Codi penal?', 'L''article 6.2 CP prohibeix que les mesures de seguretat siguin més gravoses o de més durada que la pena abstractament aplicable, i que excedeixin el que és necessari per prevenir la perillositat. L''article 1.2 exigeix pressupòsits establerts prèviament per la llei.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Arts. 1.2 i 6.2 CP', '2. Las medidas de seguridad no pueden resultar ni más gravosas ni de mayor duración que la pena abstractamente aplicable al hecho cometido, ni exceder el límite de lo necesario para prevenir la peligrosidad del autor.', null, 'eb648cd1b30d1cea0a8b57f7d30149b1759dfd9559b2a67c656b08de8afabeae', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'eb648cd1b30d1cea0a8b57f7d30149b1759dfd9559b2a67c656b08de8afabeae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només es poden aplicar quan concorrin els pressupòsits establerts prèviament per la llei.', false), ('B', 'No poden ser més gravoses que la pena abstractament aplicable al fet comès.', false), ('C', 'No poden excedir el límit del que és necessari per prevenir la perillositat de l''autor.', false), ('D', 'Poden tenir una durada superior a la de la pena abstractament aplicable si la perillositat de l''autor ho exigeix.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 8 del Codi penal, quan un fet es pot qualificar d''acord amb dos o més preceptes i no és aplicable cap dels altres criteris de resolució del concurs de normes, s''aplica la regla segons la qual:', 'La regla 4a de l''article 8 CP (criteri d''alternativitat) opera en defecte de les altres: el precepte més greu exclou els que castiguen el fet amb pena menor.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 8.4 CP', '4.ª En defecto de los criterios anteriores, el precepto penal más grave excluirá los que castiguen el hecho con pena menor.', null, 'f72cc53ebdfae950bcd14b70da52bb4cd7290976eae0b4971588ac43011db68d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f72cc53ebdfae950bcd14b70da52bb4cd7290976eae0b4971588ac43011db68d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''aplica el precepte més favorable al reu.', false), ('B', 'El precepte especial s''aplica amb preferència al general.', false), ('C', 'El precepte penal més greu exclou els que castiguen el fet amb pena menor.', true), ('D', 'S''aplica el precepte que hagi entrat en vigor més recentment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
