with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 9 del Codi penal, respecte dels delictes penats per lleis especials:', 'L''article 9 CP estén les garanties del títol preliminar a les lleis penals especials i declara supletòries la resta de disposicions del Codi en el que aquelles no prevegin expressament.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 9 CP', 'Las disposiciones de este Título se aplicarán a los delitos que se hallen penados por leyes especiales. Las restantes disposiciones de este Código se aplicarán como supletorias en lo no previsto expresamente por aquéllas.', null, '7d3d10a4eef959eba0c55e6bb42a200a6d1613c293a0564e9681e4af6a1039ae', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7d3d10a4eef959eba0c55e6bb42a200a6d1613c293a0564e9681e4af6a1039ae')
  returning id
), o as (
