insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Pel que fa a l''estructura del Codi penal, quin és el contingut del llibre II?', 'El Codi s''estructura en un títol preliminar (garanties penals i aplicació de la llei penal), el llibre I (disposicions generals), el llibre II (delictes i les seves penes) i el llibre III (faltes), derogat per la LO 1/2015. La responsabilitat civil és el títol V del llibre I.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Estructura del CP (llibre II)', 'LIBRO II. Delitos y sus penas', null, '8764ef26d683f952dcdb05c36c9470ed9d655806ab139e91ec8f7267a9801a10', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8764ef26d683f952dcdb05c36c9470ed9d655806ab139e91ec8f7267a9801a10')
