insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''exposició de motius del Codi penal afirma que s''ha afrontat l''antinòmia existent entre el principi d''intervenció mínima i:', 'Segons l''exposició de motius, el Codi dona «prudent acollida» a noves formes de delinqüència i alhora elimina figures delictives que han perdut la raó de ser, per conciliar la intervenció mínima amb les necessitats de tutela.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Exposició de motius CP', 'se ha afrontado la antinomia existente entre el principio de intervención mínima y las crecientes necesidades de tutela en una sociedad cada vez más compleja', null, '245caae043d704339426c47ce7d1c66c5b3995d420134a0b72981c7f895a75b2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '245caae043d704339426c47ce7d1c66c5b3995d420134a0b72981c7f895a75b2')
