  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quan, de l''aplicació rigorosa de la llei, resulta una pena notablement excessiva segons el jutge o tribunal, l''article 4.3 del Codi penal disposa que aquest:', 'L''article 4.3 CP no permet al jutge apartar-se de la llei: ha d''executar la sentència i, alhora, pot adreçar-se al Govern proposant la derogació o modificació del precepte o l''indult.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 4.3 CP', '3. Del mismo modo acudirá al Gobierno exponiendo lo conveniente sobre la derogación o modificación del precepto o la concesión de indulto, sin perjuicio de ejecutar desde luego la sentencia', null, '4b672e93598fbbbaad59ee900b60a95071b94ec639aed826217fdaf9799b6613', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4b672e93598fbbbaad59ee900b60a95071b94ec639aed826217fdaf9799b6613')
