  select 'Segons l''article 10 del Codi penal, són delictes:', 'L''article 10 CP defineix el delicte com l''acció o omissió, dolosa o imprudent, penada per la llei.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 10 CP', 'Son delitos las acciones y omisiones dolosas o imprudentes penadas por la ley.', null, '83da3e8bbce484ccfe0f928b21db0ece61c3628c7542071337e6729089137bcd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '83da3e8bbce484ccfe0f928b21db0ece61c3628c7542071337e6729089137bcd')
