)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En els delictes que consisteixen en la producció d''un resultat, en quin dels casos següents NO s''equipara l''omissió a l''acció segons l''article 11 del Codi penal?', 'L''article 11 CP només equipara l''omissió a l''acció quan existeix una obligació legal o contractual específica d''actuar o quan l''omitent ha creat prèviament una ocasió de risc (ingerència). Un deure moral genèric no n''hi ha prou.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 11 CP', 'a) Cuando exista una específica obligación legal o contractual de actuar. b) Cuando el omitente haya creado una ocasión de riesgo para el bien jurídicamente protegido mediante una acción u omisión precedente.', null, '3e440d034a96c189085afc34408f9367cebaa3fb4d194d39a8b96759d7b11d4a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3e440d034a96c189085afc34408f9367cebaa3fb4d194d39a8b96759d7b11d4a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan l''omitent només tenia un deure moral genèric de solidaritat amb la víctima.', true), ('B', 'Quan existeix una obligació legal específica d''actuar.', false), ('C', 'Quan existeix una obligació contractual específica d''actuar.', false), ('D', 'Quan l''omitent ha creat una ocasió de risc per al bé jurídic mitjançant una acció o omissió precedent.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
