with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 13.4 del Codi penal, quan la pena, per la seva extensió, es pot considerar alhora lleu i menys greu, el delicte es considera:', 'L''article 13.4 CP resol els casos frontera: si la pena pot ser alhora greu i menys greu, el delicte és greu; si pot ser lleu i menys greu, el delicte és lleu.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 13.4 CP', 'Cuando la pena, por su extensión, pueda considerarse como leve y como menos grave, el delito se considerará, en todo caso, como leve.', null, '0f1b31dc9cc48846d2efae22a7f5403ead0d0276f9789c76bae2edb4575b6dfd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0f1b31dc9cc48846d2efae22a7f5403ead0d0276f9789c76bae2edb4575b6dfd')
  returning id
), o as (
