with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 19 del Codi penal, els menors de quina edat no són responsables criminalment d''acord amb el Codi?', 'Els menors de divuit anys no responen d''acord amb el Codi penal; si cometen un fet delictiu, poden ser responsables d''acord amb la llei que regula la responsabilitat penal del menor.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 19 CP', 'Los menores de dieciocho años no serán responsables criminalmente con arreglo a este Código.', null, '1dabd5473e2ec2cb4f95eaa7171d24d13da7d0fba93b0d54635d651cc5a53fa0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1dabd5473e2ec2cb4f95eaa7171d24d13da7d0fba93b0d54635d651cc5a53fa0')
  returning id
