  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 20.7 del Codi penal, està exempt de responsabilitat criminal qui actua:', 'L''article 20.7 CP recull l''eximent de compliment d''un deure o exercici legítim d''un dret, ofici o càrrec. L''arravatament o l''obcecació per estímuls poderosos és una circumstància atenuant (art. 21.3).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 20.7 CP', '7.º El que obre en cumplimiento de un deber o en el ejercicio legítimo de un derecho, oficio o cargo.', null, 'd34e416aa25cbbb87e0c6ad49bfb8f5f3522e904388586ca3680d2d93a8dc8db', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd34e416aa25cbbb87e0c6ad49bfb8f5f3522e904388586ca3680d2d93a8dc8db')
  returning id
), o as (
