  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per obediència deguda a un superior jeràrquic, en tot cas.', false), ('B', 'En compliment d''un deure o en l''exercici legítim d''un dret, ofici o càrrec.', true), ('C', 'En estat d''arravatament o obcecació.', false), ('D', 'Per causes o estímuls poderosos.', false)) as v(label, body, ok)
)
