with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Respecte de l''agreujant de reincidència de l''article 22.8 del Codi penal, assenyaleu la resposta correcta:', 'Hi ha reincidència si el culpable ha estat condemnat executòriament per un delicte del mateix títol i de la mateixa naturalesa; no es computen els antecedents cancel·lats o cancel·lables ni els de delictes lleus (llevat de la multireincidència en delictes lleus), i les condemnes d''altres estats de la UE hi compten.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 22.8 CP', 'Las condenas firmes de jueces o tribunales impuestas en otros Estados de la Unión Europea producirán los efectos de reincidencia salvo que el antecedente penal haya sido cancelado o pudiera serlo con arreglo al Derecho español.', null, 'f64f76d87fe3acbceda91c0753e10016fdfdbc77652b0489d1a17cb359bca129', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f64f76d87fe3acbceda91c0753e10016fdfdbc77652b0489d1a17cb359bca129')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es computen els antecedents penals cancel·lats quan corresponen a delictes greus.', false), ('B', 'Cal que el culpable hagi estat condemnat executòriament per un delicte del mateix capítol del Codi, encara que sigui de naturalesa diferent.', false), ('C', 'Es computen sempre els antecedents corresponents a delictes lleus.', false), ('D', 'Les condemnes fermes imposades per jutges o tribunals d''altres estats de la Unió Europea produeixen efectes de reincidència, llevat que l''antecedent s''hagi cancel·lat o es pugui cancel·lar d''acord amb el dret espanyol.', true)) as v(label, body, ok)
)
