with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 27 del Codi penal, són responsables criminalment dels delictes:', 'Des de la reforma de la LO 1/2015, l''article 27 CP considera responsables criminalment dels delictes els autors i els còmplices.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 27 CP', 'Son responsables criminalmente de los delitos los autores y los cómplices.', null, '6620e624816f77ff89ebdc896f8343053a3ca40c7d118966c640b35636e8d41d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6620e624816f77ff89ebdc896f8343053a3ca40c7d118966c640b35636e8d41d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els autors, els còmplices i els encobridors.', false), ('B', 'Només els autors.', false), ('C', 'Els autors i els còmplices.', true), ('D', 'Els autors, els inductors i els encobridors.', false)) as v(label, body, ok)
)
