with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 28 del Codi penal, a més dels qui fan el fet per si sols, conjuntament o per mitjà d''un altre del qual se serveixen com a instrument, també es consideren autors:', 'L''article 28 CP equipara als autors l''inductor i el cooperador necessari. Qui coopera amb actes anteriors o simultanis no necessaris és còmplice (art. 29).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 28 CP', 'También serán considerados autores: a) Los que inducen directamente a otro u otros a ejecutarlo. b) Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado.', null, 'd1e87ec021cee37a5253b94efa92dbfcc6f2055cabf3abcc9b2b6168656334dd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd1e87ec021cee37a5253b94efa92dbfcc6f2055cabf3abcc9b2b6168656334dd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els qui indueixen directament un altre o altres a executar-lo i els qui cooperen a l''execució amb un acte sense el qual no s''hauria efectuat.', true), ('B', 'Els qui cooperen a l''execució del fet amb actes anteriors o simultanis.', false), ('C', 'Els qui, després de cometre''s el delicte, ajuden els responsables a eludir la investigació.', false), ('D', 'Els qui inciten a delinquir per qualsevol mitjà de difusió, encara que el delicte no s''arribi a cometre.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, als còmplices d''un delicte consumat o intentat se''ls imposa:', 'Són còmplices els qui cooperen a l''execució amb actes anteriors o simultanis sense ser autors (art. 29), i se''ls imposa la pena inferior en grau a la dels autors (art. 63). La pena inferior en un o dos graus és la de la temptativa (art. 62).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Arts. 29 i 63 CP', 'A los cómplices de un delito consumado o intentado se les impondrá la pena inferior en grado a la fijada por la Ley para los autores del mismo delito.', null, 'e32790d8ce6e5eb5998f20250af362abd3aac5696b6bfd669360c31b477d4ed8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e32790d8ce6e5eb5998f20250af362abd3aac5696b6bfd669360c31b477d4ed8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La mateixa pena que als autors, en la meitat inferior.', false), ('B', 'La pena inferior en grau a la fixada per la llei per als autors del mateix delicte.', true), ('C', 'La pena inferior en dos graus a la fixada per als autors.', false), ('D', 'La pena inferior en un o dos graus, segons el perill inherent a l''intent.', false)) as v(label, body, ok)
)
