with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 32 del Codi penal, les penes que es poden imposar, amb caràcter principal o com a accessòries, són:', 'L''article 32 CP classifica les penes per la seva naturalesa en privatives de llibertat, privatives d''altres drets i multa. Els treballs en benefici de la comunitat són una pena privativa de drets (art. 39.i).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 32 CP', 'Las penas que pueden imponerse con arreglo a este Código, bien con carácter principal bien como accesorias, son privativas de libertad, privativas de otros derechos y multa.', null, 'ff22658b445a2b5422d94ea126eed3cfd6733a1ddc4038fe5c9a39e15f5e7376', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ff22658b445a2b5422d94ea126eed3cfd6733a1ddc4038fe5c9a39e15f5e7376')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Privatives de llibertat, privatives d''altres drets i multa.', true), ('B', 'Privatives de llibertat, multa i mesures de seguretat.', false), ('C', 'Privatives de llibertat, privatives d''altres drets i treballs en benefici de la comunitat.', false), ('D', 'Corporals, privatives de llibertat i pecuniàries.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 35 del Codi penal, quina de les penes següents NO és una pena privativa de llibertat?', 'Són penes privatives de llibertat la presó permanent revisable, la presó, la localització permanent i la responsabilitat personal subsidiària per impagament de multa. Els treballs en benefici de la comunitat són una pena privativa de drets (art. 39).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 35 CP', 'Son penas privativas de libertad la prisión permanente revisable, la prisión, la localización permanente y la responsabilidad personal subsidiaria por impago de multa.', null, '81be9032716fd8588778f3bb199cf4147c979a7714bc596a79f9d4a7dbf6bc0d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '81be9032716fd8588778f3bb199cf4147c979a7714bc596a79f9d4a7dbf6bc0d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La localització permanent.', false), ('B', 'La responsabilitat personal subsidiària per impagament de multa.', false), ('C', 'La presó permanent revisable.', false), ('D', 'Els treballs en benefici de la comunitat.', true)) as v(label, body, ok)
)
