with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Llevat del que disposin excepcionalment altres preceptes del Codi penal, quina durada té la pena de presó segons l''article 36.2?', 'L''article 36.2 CP fixa la durada de la presó entre tres mesos i vint anys, llevat de les excepcions previstes en altres preceptes.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 36.2 CP', '2. La pena de prisión tendrá una duración mínima de tres meses y máxima de veinte años, salvo lo que excepcionalmente dispongan otros preceptos del presente Código.', null, 'fa022d390eb7196719fef6c0804923e64dd536bc2db046854fda255ca39d5287', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fa022d390eb7196719fef6c0804923e64dd536bc2db046854fda255ca39d5287')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Mínima de sis mesos i màxima de vint anys.', false), ('B', 'Mínima de tres mesos i màxima de trenta anys.', false), ('C', 'Mínima de tres mesos i màxima de vint anys.', true), ('D', 'Mínima d''un mes i màxima de vint-i-cinc anys.', false)) as v(label, body, ok)
)
