  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Hagi complert vint anys de la seva condemna i estigui classificat en segon grau.', false), ('B', 'Hagi complert les tres quartes parts de la condemna i hagi observat bona conducta.', false), ('C', 'Hagi complert trenta anys de la seva condemna, amb independència del grau de classificació.', false), ('D', 'Hagi complert vint-i-cinc anys de la seva condemna i estigui classificat en tercer grau.', true)) as v(label, body, ok)
)
