  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 37.1 del Codi penal, la pena de localització permanent té una durada:', 'La localització permanent dura fins a sis mesos i obliga el penat a romandre al seu domicili o al lloc que fixi el jutge. Aquest límit no regeix quan s''aplica com a responsabilitat personal subsidiària per impagament de multa en delictes lleus (art. 53.1).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 37.1 CP', '1. La localización permanente tendrá una duración de hasta seis meses.', null, '5982c596b863c41c002d06aaa91476407e501bbe250f1248da7cb3bfce9e5eb0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5982c596b863c41c002d06aaa91476407e501bbe250f1248da7cb3bfce9e5eb0')
  returning id
), o as (
