with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les afirmacions següents sobre la pena de treballs en benefici de la comunitat NO és correcta, segons l''article 49 del Codi penal?', 'L''article 49 CP estableix que la durada diària dels treballs en benefici de la comunitat no pot excedir de vuit hores. Les altres tres afirmacions són condicions literals del mateix article.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 49 CP', 'Su duración diaria no podrá exceder de ocho horas', null, '99aa3dedc454635cbcafea73073b11c80e3d7cc3bd4fbfaf9b16854b9fab1baa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '99aa3dedc454635cbcafea73073b11c80e3d7cc3bd4fbfaf9b16854b9fab1baa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No es pot imposar sense el consentiment de la persona condemnada.', false), ('B', 'La seva durada diària pot arribar a deu hores si la persona condemnada hi dona el consentiment.', true), ('C', 'La seva execució es desenvolupa sota el control del jutge de vigilància penitenciària.', false), ('D', 'No s''ha de supeditar a l''assoliment d''interessos econòmics.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 49 del Codi penal, els serveis socials penitenciaris han de comunicar al jutge de vigilància penitenciària, entre altres incidències, que el penat s''absenta del treball durant almenys:', 'L''article 49.6a.a) CP obliga a comunicar l''absència d''almenys dues jornades laborals que suposi un rebuig voluntari. Segons la condició 7a, la falta per causa justificada no s''entén com a abandonament, però el treball perdut no es computa.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 49.6a CP', 'a) Se ausenta del trabajo durante al menos dos jornadas laborales, siempre que ello suponga un rechazo voluntario por su parte al cumplimiento de la pena.', null, 'e6a2329904a0646214a90ce253b50b436f5cc51074f0742b722f8e345d55377e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e6a2329904a0646214a90ce253b50b436f5cc51074f0742b722f8e345d55377e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres jornades laborals consecutives, encara que l''absència sigui justificada.', false), ('B', 'Una jornada laboral, en tot cas.', false), ('C', 'Dues jornades laborals, sempre que això suposi un rebuig voluntari al compliment de la pena.', true), ('D', 'Cinc jornades laborals en un mateix mes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
