with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 133 del Codi penal, les penes menys greus imposades per sentència ferma prescriuen:', 'Les penes lleus prescriuen a l''any, les menys greus als cinc anys i les restants penes greus als deu anys, amb terminis més llargs per a la presó i la inhabilitació de més durada (art. 133.1).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 133.1 CP', 'A los cinco, las penas menos graves.', null, '640461fbe6849618f2b06333242395cbf1aebd8dac5dd87c6cf59ffe76ba4a9e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '640461fbe6849618f2b06333242395cbf1aebd8dac5dd87c6cf59ffe76ba4a9e')
