insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e04-principals-delictes', 'Tema 4. Els principals delictes') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e04-principals-delictes' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Qui, per qualsevol mitjà, colpeja o maltracta d''obra sense causar lesió la dona que és o ha estat la seva esposa o parella, encara que sense convivència, comet el delicte de l''article 153.1 del Codi penal, castigat amb:', 'L''article 153.1 CP castiga el maltractament d''obra a la dona parella o exparella (o a una persona especialment vulnerable que hi convisqui) amb presó de sis mesos a un any o TBC de 31 a 80 dies, més la privació del dret a les armes. Si la víctima és una altra persona de l''article 173.2, la presó és de tres mesos a un any (art. 153.2).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 153.1 CP', 'será castigado con la pena de prisión de seis meses a un año o de trabajos en beneficios de la comunidad de treinta y uno a ochenta días y, en todo caso, privación del derecho a la tenencia y porte de armas de un año y un día a tres años', null, '246a59a9cda24f380f895f57fcaecf2c6660c5ff21cb80dd36144737ef89f31a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '246a59a9cda24f380f895f57fcaecf2c6660c5ff21cb80dd36144737ef89f31a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de tres mesos a un any o treballs en benefici de la comunitat de trenta-un a vuitanta dies i, en tot cas, privació del dret a la tinença i portada d''armes d''un any i un dia a tres anys.', false), ('B', 'Presó de sis mesos a tres anys i privació del dret a la tinença i portada d''armes de tres a cinc anys.', false), ('C', 'Presó de sis mesos a un any o treballs en benefici de la comunitat de trenta-un a vuitanta dies i, en tot cas, privació del dret a la tinença i portada d''armes d''un any i un dia a tres anys.', true), ('D', 'Multa d''un a tres mesos o localització permanent de cinc a trenta dies.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 153.3 del Codi penal, en quin dels casos següents NO es preveu imposar les penes dels apartats 1 i 2 en la meitat superior?', 'L''article 153.3 CP preveu la meitat superior quan el fet es comet en presència de menors, utilitzant armes, al domicili comú o al de la víctima, o trencant una pena de l''article 48 o una mesura de la mateixa naturalesa. El lloc públic no hi és.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 153.3 CP', '3. Las penas previstas en los apartados 1 y 2 se impondrán en su mitad superior cuando el delito se perpetre en presencia de menores, o utilizando armas, o tenga lugar en el domicilio común o en el domicilio de la víctima, o se realice quebrantando una pena de las contempladas en el artículo 48 de este Código o una medida cautelar o de seguridad de la misma naturaleza.', null, '2963dd684f61ba6ad3db0acd12d41021aff29d3223e4db6b88652483b8e53344', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2963dd684f61ba6ad3db0acd12d41021aff29d3223e4db6b88652483b8e53344')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan el delicte es perpetri en presència de menors.', false), ('B', 'Quan el delicte tingui lloc al domicili comú o al domicili de la víctima.', false), ('C', 'Quan el delicte es faci trencant una pena de les previstes a l''article 48 o una mesura cautelar o de seguretat de la mateixa naturalesa.', false), ('D', 'Quan el delicte es cometi en un lloc públic.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 173.2 del Codi penal, qui exerceix habitualment violència física o psíquica sobre qui sigui o hagi estat el seu cònjuge o sobre altres persones de l''entorn familiar que esmenta el precepte és castigat amb:', 'El maltractament habitual de l''article 173.2 CP es castiga amb presó de sis mesos a tres anys, privació del dret a les armes de tres a cinc anys i, si escau, inhabilitació especial per a la pàtria potestat, sens perjudici de les penes pels actes de violència concrets.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 173.2 CP', 'será castigado con la pena de prisión de seis meses a tres años, privación del derecho a la tenencia y porte de armas de tres a cinco años', null, 'cdfc598fb81159a74b9e18eeca03dee8a6ebc7597415abd278d1d519f3ff06ea', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cdfc598fb81159a74b9e18eeca03dee8a6ebc7597415abd278d1d519f3ff06ea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a tres anys i privació del dret a la tinença i portada d''armes de tres a cinc anys.', true), ('B', 'Presó de sis mesos a un any i privació del dret a la tinença i portada d''armes d''un any i un dia a tres anys.', false), ('C', 'Presó d''un a quatre anys i inhabilitació absoluta.', false), ('D', 'Presó de tres mesos a un any o multa de sis a vint-i-quatre mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per apreciar l''habitualitat del delicte de maltractament habitual, l''article 173.3 del Codi penal ordena atendre el nombre d''actes de violència acreditats i la seva proximitat temporal:', 'L''article 173.3 CP no fixa cap nombre mínim d''actes: atén el nombre d''actes acreditats i la proximitat temporal, encara que afectin víctimes diferents de l''entorn previst i encara que ja s''hagin jutjat.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 173.3 CP', '3. Para apreciar la habitualidad a que se refiere el apartado anterior, se atenderá al número de actos de violencia que resulten acreditados, así como a la proximidad temporal de los mismos, con independencia de que dicha violencia se haya ejercido sobre la misma o diferentes víctimas de las comprendidas en este artículo, y de que los actos violentos hayan sido o no objeto de enjuiciamiento en procesos anteriores.', null, 'bc23efe56a90e6d81935f6d7415150b1181ae7f3eb9ed329af3f17f262e6d2b6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bc23efe56a90e6d81935f6d7415150b1181ae7f3eb9ed329af3f17f262e6d2b6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sempre que s''acreditin almenys tres actes de violència sobre la mateixa víctima en el termini d''un any.', false), ('B', 'Sempre que la violència s''hagi exercit sobre la mateixa víctima.', false), ('C', 'Amb independència que la violència s''hagi exercit sobre la mateixa víctima o sobre víctimes diferents de les previstes a l''article i que els actes hagin estat o no objecte d''enjudiciament en processos anteriors.', true), ('D', 'Comptant només els actes que no hagin estat objecte d''enjudiciament en processos anteriors.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 178.1 del Codi penal, en el delicte d''agressió sexual només s''entén que hi ha consentiment quan:', 'L''article 178.1 CP castiga amb presó d''un a quatre anys qualsevol acte que atempti contra la llibertat sexual sense consentiment, i defineix el consentiment com la manifestació lliure, per actes, que expressi de manera clara la voluntat de la persona.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 178.1 CP', 'Sólo se entenderá que hay consentimiento cuando se haya manifestado libremente mediante actos que, en atención a las circunstancias del caso, expresen de manera clara la voluntad de la persona.', null, '55ebe2947d77894ea2d03745dff314e4b8f195e68655aac0e990b87244e1422a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '55ebe2947d77894ea2d03745dff314e4b8f195e68655aac0e990b87244e1422a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La víctima no s''ha oposat de manera expressa a l''acte.', false), ('B', 'S''ha manifestat lliurement mitjançant actes que, ateses les circumstàncies del cas, expressin de manera clara la voluntat de la persona.', true), ('C', 'La víctima no ha manifestat cap resistència física.', false), ('D', 'La víctima ho ha manifestat per escrit o davant de testimonis.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En les agressions sexuals del capítol I del títol VIII del Codi penal, quan el culpable s''ha prevalgut de la seva condició d''autoritat, agent d''aquesta o funcionari públic, l''article 180.3 disposa que s''imposa, a més:', 'L''article 180.3 CP afegeix, en tots els casos del capítol, la inhabilitació absoluta de sis a dotze anys. La de vuit a dotze anys correspon a la tortura (art. 174.1).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 180.3 CP', '3. En todos los casos previstos en este capítulo, cuando el culpable se hubiera prevalido de su condición de autoridad, agente de ésta o funcionario público, se impondrá, además, la pena de inhabilitación absoluta de seis a doce años.', null, '00ccfdd331c9081623ef55d43749a2e84008c3850ddb42195faea701fd6351be', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '00ccfdd331c9081623ef55d43749a2e84008c3850ddb42195faea701fd6351be')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La pena d''inhabilitació absoluta de vuit a dotze anys.', false), ('B', 'La pena d''inhabilitació especial per a ocupació o càrrec públic de dos a quatre anys.', false), ('C', 'La pena de suspensió d''ocupació o càrrec públic de tres mesos a sis anys.', false), ('D', 'La pena d''inhabilitació absoluta de sis a dotze anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 138.1 del Codi penal, qui mata una altra persona és castigat, com a reu d''homicidi, amb la pena de presó de:', 'L''homicidi dolós es castiga amb presó de deu a quinze anys (art. 138.1). L''assassinat, amb presó de quinze a vint-i-cinc anys (art. 139) i l''homicidi per imprudència greu, amb presó d''un a quatre anys (art. 142.1).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 138.1 CP', '1. El que matare a otro será castigado, como reo de homicidio, con la pena de prisión de diez a quince años.', null, 'c503e11ff41c5ea1302509be380ed51666600317e6e2a06a8cdda98eb77af6d3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c503e11ff41c5ea1302509be380ed51666600317e6e2a06a8cdda98eb77af6d3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quinze a vint-i-cinc anys.', false), ('B', 'Deu a quinze anys.', true), ('C', 'Un a quatre anys.', false), ('D', 'Vuit a dotze anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les circumstàncies següents NO converteix la mort d''una altra persona en assassinat segons l''article 139.1 del Codi penal?', 'Les circumstàncies de l''assassinat són alevosia, preu, recompensa o promesa, acarnissament i matar per facilitar la comissió d''un altre delicte o per evitar que es descobreixi. Si l''homicidi constitueix també atemptat de l''article 550, s''imposa la pena superior en grau de l''homicidi (art. 138.2.b), però no és assassinat.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 139.1 CP', '1.ª Con alevosía. 2.ª Por precio, recompensa o promesa. 3.ª Con ensañamiento, aumentando deliberada e inhumanamente el dolor del ofendido. 4.ª Para facilitar la comisión de otro delito o para evitar que se descubra.', null, 'de9b9fc97657deecf7c45a9dc890b5708b2bbf83717055572e4542e5639c5c00', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'de9b9fc97657deecf7c45a9dc890b5708b2bbf83717055572e4542e5639c5c00')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que es mati amb alevosia.', false), ('B', 'Que es mati per preu, recompensa o promesa.', false), ('C', 'Que la víctima sigui una autoritat o un agent seu en l''exercici de les seves funcions.', true), ('D', 'Que es mati amb acarnissament, augmentant deliberadament i inhumanament el dolor de l''ofès.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 142.1 del Codi penal, qui per imprudència greu causa la mort d''una altra persona és castigat, com a reu d''homicidi imprudent, amb:', 'L''homicidi per imprudència greu es castiga amb presó d''un a quatre anys; el comès per imprudència menys greu, amb multa de tres a divuit mesos (art. 142.2).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 142.1 CP', '1. El que por imprudencia grave causare la muerte de otro, será castigado, como reo de homicidio imprudente, con la pena de prisión de uno a cuatro años.', null, '19a5a6a48b0b21ff9e5358e3ab1a24264660f1624c1fd34dba7feb980cceda2c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '19a5a6a48b0b21ff9e5358e3ab1a24264660f1624c1fd34dba7feb980cceda2c')
  returning id
), o as (
