with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les circumstàncies següents NO és una de les que caracteritzen el robatori amb força en les coses segons l''article 238 del Codi penal?', 'L''article 238 CP enumera escalament, rompiment de paret, sostre o terra o fractura de porta o finestra, fractura de mobles o objectes tancats, ús de claus falses i inutilització de sistemes d''alarma o guarda. La violència o intimidació en les persones caracteritza l''altra modalitat de robatori (arts. 237 i 242).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 238 CP', '1.º Escalamiento. 2.º Rompimiento de pared, techo o suelo, o fractura de puerta o ventana. 3.º Fractura de armarios, arcas u otra clase de muebles u objetos cerrados o sellados, o forzamiento de sus cerraduras o descubrimiento de sus claves para sustraer su contenido, sea en el lugar del robo o fuera del mismo. 4.º Uso de llaves falsas. 5.º Inutilización de sistemas específicos de alarma o guarda.', null, '289c7f57cc89b9f0ce16c5b1c45538b481adbf0b1ab4cc1b8946c6bd28f3f5c9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '289c7f57cc89b9f0ce16c5b1c45538b481adbf0b1ab4cc1b8946c6bd28f3f5c9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La intimidació en les persones.', true), ('B', 'L''escalament.', false), ('C', 'L''ús de claus falses.', false), ('D', 'La inutilització de sistemes específics d''alarma o guarda.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 242.1 del Codi penal, el culpable de robatori amb violència o intimidació en les persones és castigat amb la pena de presó de:', 'El robatori amb violència o intimidació es castiga amb presó de dos a cinc anys (art. 242.1); si es comet en casa habitada o local obert al públic, de tres anys i sis mesos a cinc anys (art. 242.2). El robatori amb força en les coses es castiga amb presó d''un a tres anys (art. 240.1).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 242.1 CP', '1. El culpable de robo con violencia o intimidación en las personas será castigado con la pena de prisión de dos a cinco años, sin perjuicio de la que pudiera corresponder a los actos de violencia física que realizase.', null, 'e2c98b3c62e4140945350e5bf69224f4f5a8df6ea2eac2afc9c47ac5ac0f6696', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e2c98b3c62e4140945350e5bf69224f4f5a8df6ea2eac2afc9c47ac5ac0f6696')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un a tres anys.', false), ('B', 'Tres anys i sis mesos a cinc anys.', false), ('C', 'Dos a sis anys.', false), ('D', 'Dos a cinc anys, sens perjudici de la que pugui correspondre als actes de violència física que dugui a terme.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 368 del Codi penal, el tràfic de drogues tòxiques, estupefaents o substàncies psicotròpiques que causen greu dany a la salut és castigat amb:', 'L''article 368 CP distingeix entre substàncies que causen greu dany a la salut (presó de tres a sis anys i multa del tant al triple) i la resta (presó d''un a tres anys i multa del tant al doble).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 368 CP', 'serán castigados con las penas de prisión de tres a seis años y multa del tanto al triplo del valor de la droga objeto del delito si se tratare de sustancias o productos que causen grave daño a la salud', null, '217e0c322fc25454114b4f208d048733e99ae82f073d36714b21d919e0bab2f4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '217e0c322fc25454114b4f208d048733e99ae82f073d36714b21d919e0bab2f4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a tres anys i multa del tant al doble del valor de la droga.', false), ('B', 'Presó de sis a nou anys i multa del tant al quàdruple del valor de la droga.', false), ('C', 'Presó de tres a sis anys i multa del tant al triple del valor de la droga objecte del delicte.', true), ('D', 'Presó de quatre anys i sis mesos a deu anys i multa del tant al triple del valor de la droga.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 369.1 del Codi penal, quan les conductes de tràfic de drogues de l''article 368 tenen lloc en un establiment penitenciari o en les seves proximitats:', 'L''article 369.1.7a CP agreuja el tràfic de drogues comès en centres docents, militars, establiments penitenciaris o centres de deshabituació, o en les seves proximitats, amb la pena superior en grau i multa del tant al quàdruple.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 369.1.7a CP', '1. Se impondrán las penas superiores en grado a las señaladas en el artículo anterior y multa del tanto al cuádruplo cuando concurran alguna de las siguientes circunstancias: […] 7.ª Las conductas descritas en el artículo anterior tengan lugar en centros docentes, en centros, establecimientos o unidades militares, en establecimientos penitenciarios o en centros de deshabituación o rehabilitación, o en sus proximidades.', null, 'a85c5b4dea218f36d19930fab469ca1bdc00e7e72905596e233f9080b1058f49', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a85c5b4dea218f36d19930fab469ca1bdc00e7e72905596e233f9080b1058f49')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''imposen les penes de l''article 368 en la meitat superior.', false), ('B', 'S''imposen les penes superiors en grau a les de l''article 368 i multa del tant al quàdruple.', true), ('C', 'S''imposa la pena superior en dos graus a la de l''article 368.', false), ('D', 'No hi ha cap agreujament específic per aquest motiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 174 del Codi penal, a més de la pena de presó, al culpable de tortura (inclosa la comesa per una autoritat o funcionari d''institucions penitenciàries respecte d''interns o presos) se li imposa en tot cas:', 'La tortura es castiga amb presó de dos a sis anys si l''atemptat és greu i d''un a tres anys si no ho és, i en tot cas amb inhabilitació absoluta de vuit a dotze anys (art. 174.1). L''apartat 2 estén aquestes penes a l''autoritat o funcionari d''institucions penitenciàries. La inhabilitació especial de dos a quatre anys és la de l''article 175.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 174 CP', 'Además de las penas señaladas se impondrá, en todo caso, la pena de inhabilitación absoluta de ocho a 12 años. 2. En las mismas penas incurrirán, respectivamente, la autoridad o funcionario de instituciones penitenciarias o de centros de protección o corrección de menores que cometiere, respecto de detenidos, internos o presos, los actos a que se refiere el apartado anterior.', null, 'ec1f8642cea9263c6a55a3d041fad8d066b6a14eb7899e4979bec2ec687d6732', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ec1f8642cea9263c6a55a3d041fad8d066b6a14eb7899e4979bec2ec687d6732')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La pena d''inhabilitació especial per a ocupació o càrrec públic de dos a quatre anys.', false), ('B', 'La pena d''inhabilitació absoluta de sis a dotze anys.', false), ('C', 'La pena d''inhabilitació absoluta de vuit a dotze anys.', true), ('D', 'La pena de suspensió d''ocupació o càrrec públic de sis mesos a dos anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''autoritat o el funcionari que, faltant als deures del seu càrrec, permet que altres persones executin actes de tortura o contra la integritat moral de les persones, segons l''article 176 del Codi penal:', 'L''article 176 CP castiga amb les mateixes penes dels articles 174 i 175 l''autoritat o funcionari que, faltant als deures del seu càrrec, permet que altres executin aquests fets.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 176 CP', 'Se impondrán las penas respectivamente establecidas en los artículos precedentes a la autoridad o funcionario que, faltando a los deberes de su cargo, permitiere que otras personas ejecuten los hechos previstos en ellos.', null, '0a8601951752814887e0d25447f994e4f339b99d3fb1569c5a088aa3cb5f66f5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0a8601951752814887e0d25447f994e4f339b99d3fb1569c5a088aa3cb5f66f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Incorre en les penes establertes respectivament en els articles precedents per a aquests fets.', true), ('B', 'Incorre en la pena inferior en grau a la prevista per als autors materials.', false), ('C', 'Només pot ser sancionat disciplinàriament.', false), ('D', 'Incorre únicament en la pena d''inhabilitació especial per a ocupació o càrrec públic.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 550.2 del Codi penal, l''atemptat contra un funcionari públic que no té la condició d''autoritat es castiga amb la pena de:', 'L''atemptat contra l''autoritat es castiga amb presó d''un a quatre anys i multa de tres a sis mesos, i en els altres casos (agents i funcionaris públics), amb presó de sis mesos a tres anys (art. 550.2). Per a determinades autoritats (art. 550.3), la presó és d''un a sis anys i la multa de sis a dotze mesos. La resistència o desobediència greus de l''article 556 es castiguen amb presó de tres mesos a un any o multa de sis a divuit mesos.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 550.2 CP', '2. Los atentados serán castigados con las penas de prisión de uno a cuatro años y multa de tres a seis meses si el atentado fuera contra autoridad y de prisión de seis meses a tres años en los demás casos.', null, '8890eda7fe1a2f98bf6b04a782d96f53f6389f581504cab8b2d1f0383fac8614', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8890eda7fe1a2f98bf6b04a782d96f53f6389f581504cab8b2d1f0383fac8614')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a quatre anys i multa de tres a sis mesos.', false), ('B', 'Presó de sis mesos a tres anys.', true), ('C', 'Presó d''un a sis anys i multa de sis a dotze mesos.', false), ('D', 'Presó de tres mesos a un any o multa de sis a divuit mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 551 del Codi penal, quina conseqüència té que l''atemptat es cometi amb ocasió d''un motí, plante o incident col·lectiu a l''interior d''un centre penitenciari?', 'L''article 551 CP preveu les penes superiors en grau quan l''atemptat es comet amb armes o objectes perillosos, amb actes potencialment perillosos per a la vida, amb un vehicle de motor o amb ocasió d''un motí, plante o incident col·lectiu a l''interior d''un centre penitenciari.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 551.4 CP', 'Se impondrán las penas superiores en grado a las respectivamente previstas en el artículo anterior siempre que el atentado se cometa: […] 4.º Cuando los hechos se lleven a cabo con ocasión de un motín, plante o incidente colectivo en el interior de un centro penitenciario.', null, 'ea97ca3c7074b0c18bebdaf62efb920c7cf3b4af76f0a1ebd2972e8b6500558c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ea97ca3c7074b0c18bebdaf62efb920c7cf3b4af76f0a1ebd2972e8b6500558c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''imposen les penes de l''article 550 en la meitat superior.', false), ('B', 'S''imposen les penes inferiors en grau, perquè es tracta d''un fet col·lectiu.', false), ('C', 'No té conseqüències específiques; s''aplica l''agreujant genèrica d''abús de superioritat.', false), ('D', 'S''imposen les penes superiors en grau a les previstes a l''article 550.', true)) as v(label, body, ok)
)
