  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Inhabilitació especial per a ocupació o càrrec públic de quatre a vuit anys.', false), ('B', 'Suspensió d''ocupació o càrrec públic de sis mesos a dos anys.', false), ('C', 'Inhabilitació especial per a ocupació o càrrec públic de dos a sis anys.', true), ('D', 'Presó de sis mesos a dos anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
