with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 101 de la Llei d''enjudiciament criminal, l''acció penal:', 'L''art. 101 LECrim proclama el caràcter públic de l''acció penal, que poden exercir tots els ciutadans espanyols (acció popular), d''acord amb la llei.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 101 LECrim', 'La acción penal es pública. Todos los ciudadanos españoles podrán ejercitarla con arreglo a las prescripciones de la Ley.', null, 'd2490eeb000cccd794d22fc1fa5a6e6effd2ad381e3a056d8a38ff083c9faea0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd2490eeb000cccd794d22fc1fa5a6e6effd2ad381e3a056d8a38ff083c9faea0')
  returning id
), o as (
