)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 102 de la Llei d''enjudiciament criminal, quina de les persones següents no pot exercir, amb caràcter general, l''acció penal?', 'L''art. 102 LECrim exclou de l''exercici de l''acció penal qui no gaudeixi de la plenitud dels drets civils, qui hagi estat condemnat dues vegades per denúncia o querella calumnioses i el jutge o magistrat (llevat dels delictes contra ells o els seus familiars).', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 102 LECrim', 'no podrán ejercitar la acción penal: 1.º El que no goce de la plenitud de los derechos civiles. 2.º El que hubiera sido condenado dos veces por sentencia firme como reo del delito de denuncia o querella calumniosas. 3.º El Juez o Magistrado.', null, '001490b40c3472de4ca1bfd4b7dc5b1a2e8a89d72ab2a80f4b6e7293a7dd01ab', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '001490b40c3472de4ca1bfd4b7dc5b1a2e8a89d72ab2a80f4b6e7293a7dd01ab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge o magistrat.', true), ('B', 'El ciutadà espanyol que no ha estat ofès pel delicte.', false), ('C', 'Qui ha estat condemnat una sola vegada per sentència ferma com a reu del delicte de denúncia falsa.', false), ('D', 'El funcionari públic.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 270 de la Llei d''enjudiciament criminal, els estrangers es poden querellar:', 'L''art. 270 LECrim reconeix l''acció popular a tots els ciutadans espanyols, ofesos o no; els estrangers només es poden querellar pels delictes comesos contra les seves persones o béns o els dels seus representats, amb els requisits dels arts. 280 i 281.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 270 LECrim', 'También pueden querellarse los extranjeros por los delitos cometidos contra sus personas o bienes o las personas o bienes de sus representados', null, '8c4755b0df4cd5853f64a5216282241074f005e218d20a54262d78acacb9d8a6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8c4755b0df4cd5853f64a5216282241074f005e218d20a54262d78acacb9d8a6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En tots els casos, exercint l''acció popular en les mateixes condicions que els ciutadans espanyols.', false), ('B', 'Només si tenen la residència legal a Espanya.', false), ('C', 'Pels delictes comesos contra les seves persones o béns o les persones o béns dels seus representats.', true), ('D', 'En cap cas, perquè l''acció penal només correspon als ciutadans espanyols.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 299 de la Llei d''enjudiciament criminal, constitueixen el sumari:', 'L''art. 299 LECrim defineix el sumari (fase d''instrucció) com les actuacions encaminades a preparar el judici i a esbrinar la perpetració del delicte i la culpabilitat, assegurant-ne les persones i les responsabilitats pecuniàries.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 299 LECrim', 'Constituyen el sumario las actuaciones encaminadas a preparar el juicio y practicadas para averiguar y hacer constar la perpetración de los delitos con todas las circunstancias que puedan influir en su calificación y la culpabilidad de los delincuentes', null, '3cfb90ef0e6825ec3374cfd10a03a71b6aa88114594d81cdc5330fc07b025334', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3cfb90ef0e6825ec3374cfd10a03a71b6aa88114594d81cdc5330fc07b025334')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les actuacions que es fan en el judici oral per practicar les proves proposades per les parts.', false), ('B', 'Les diligències policials prèvies a la presentació de la denúncia o querella.', false), ('C', 'El conjunt de recursos que es poden interposar contra la sentència.', false), ('D', 'Les actuacions encaminades a preparar el judici i practicades per esbrinar i fer constar la perpetració dels delictes, amb totes les circumstàncies que puguin influir en la seva qualificació i en la culpabilitat dels delinqüents.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 110 de la Llei d''enjudiciament criminal, les persones perjudicades per un delicte que no hagin renunciat al seu dret poden mostrar-se part en la causa si ho fan:', 'L''art. 110 LECrim permet als perjudicats mostrar-se part abans del tràmit de qualificació del delicte, sense que les actuacions retrocedeixin; si es personen després, només poden adherir-se a l''escrit d''acusació fins a l''inici del judici oral.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 110 LECrim', 'Las personas perjudicadas por un delito que no hubieren renunciado a su derecho podrán mostrarse parte en la causa si lo hicieran antes del trámite de calificación del delito', null, '52937e8a758ab55bf9af6996380066a72afb03ac20b29a8cec34f013b4022152', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '52937e8a758ab55bf9af6996380066a72afb03ac20b29a8cec34f013b4022152')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Abans del tràmit de qualificació del delicte.', true), ('B', 'Abans de la incoació del sumari.', false), ('C', 'En qualsevol moment fins que la sentència sigui ferma.', false), ('D', 'Dins dels deu dies següents a la presentació de la denúncia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei d''enjudiciament criminal, quan només s''exerceix l''acció penal:', 'L''art. 112 LECrim estableix que, exercida només l''acció penal, s''entén utilitzada també la civil, tret de renúncia o reserva expressa del perjudicat.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 112 LECrim', 'Ejercitada sólo la acción penal, se entenderá utilizada también la civil, a no ser que el dañado o perjudicado la renunciase o la reservase expresamente para ejercitarla después de terminado el juicio criminal', null, 'd33f45992afd377ed3f894deb55b3d0ebdaa6ca1d9911516fcec301de86cd213', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd33f45992afd377ed3f894deb55b3d0ebdaa6ca1d9911516fcec301de86cd213')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''entén renunciada l''acció civil, que s''haurà d''exercir davant la jurisdicció civil.', false), ('B', 'S''entén utilitzada també la civil, llevat que el perjudicat la renunciï o la reservi expressament per exercir-la després del judici criminal.', true), ('C', 'L''acció civil s''extingeix si no s''exerceix en el termini de deu dies.', false), ('D', 'L''acció civil només la pot exercir el Ministeri Fiscal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 118.1 de la Llei d''enjudiciament criminal, tota persona a qui s''atribueixi un fet punible pot exercir el dret de defensa, intervenint en les actuacions:', 'L''art. 118.1 LECrim permet exercir el dret de defensa des de la comunicació del procediment, la detenció o altra mesura cautelar o el processament, i obliga a instruir l''investigat dels seus drets sense demora injustificada.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 118.1 LECrim', 'Toda persona a quien se atribuya un hecho punible podrá ejercitar el derecho de defensa, interviniendo en las actuaciones, desde que se le comunique su existencia, haya sido objeto de detención o de cualquier otra medida cautelar o se haya acordado su procesamiento', null, '248cdccd1f0b837cc460fd2336e95894f24d33541e0dcd22a12a670716a291c1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '248cdccd1f0b837cc460fd2336e95894f24d33541e0dcd22a12a670716a291c1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només des que s''hagi dictat la interlocutòria d''obertura del judici oral.', false), ('B', 'Només des que hagi prestat declaració davant el jutge.', false), ('C', 'Des que se li comuniqui la seva existència, hagi estat objecte de detenció o de qualsevol altra mesura cautelar o s''hagi acordat el seu processament.', true), ('D', 'Només des que s''hagi formulat escrit d''acusació contra ella.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 118.2 de la Llei d''enjudiciament criminal, el dret de defensa s''exerceix sense més limitacions que les previstes expressament en la llei:', 'L''art. 118.2 LECrim estén el dret de defensa des de l''atribució del fet punible investigat fins a l''extinció de la pena; inclou l''assistència d''un advocat de lliure designació o d''ofici.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 118.2 LECrim', 'El derecho de defensa se ejercerá sin más limitaciones que las expresamente previstas en la ley desde la atribución del hecho punible investigado hasta la extinción de la pena.', null, '1cc29efdee8be0f82a55059fad4b8977bceacffc8b80b4a0633ab128f24acea4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1cc29efdee8be0f82a55059fad4b8977bceacffc8b80b4a0633ab128f24acea4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Des de la detenció fins a la sentència ferma.', false), ('B', 'Des del processament fins a l''obertura del judici oral.', false), ('C', 'Des de l''atribució del fet punible fins a la sentència de primera instància.', false), ('D', 'Des de l''atribució del fet punible investigat fins a l''extinció de la pena.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels drets següents NO figura entre els que, segons l''article 118.1 de la Llei d''enjudiciament criminal, s''han d''instruir a la persona a qui s''atribueix un fet punible?', 'L''art. 118.1 LECrim enumera, entre d''altres, el dret a ser informat dels fets, a examinar les actuacions, a designar advocat, a la traducció i interpretació gratuïtes, a guardar silenci i a no declarar contra si mateix. No hi ha cap dret a no ser citat fins al final de la instrucció.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 118.1 LECrim', 'b) Derecho a examinar las actuaciones con la debida antelación para salvaguardar el derecho de defensa y en todo caso, con anterioridad a que se le tome declaración. […] f) Derecho a la traducción e interpretación gratuitas de conformidad con lo dispuesto en los artículos 123 y 127. g) Derecho a guardar silencio y a no prestar declaración si no desea hacerlo', null, 'ca38303495139b3eff210f3d987c578c8b381cf9ed483ac724a34221bd5f2891', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ca38303495139b3eff210f3d987c578c8b381cf9ed483ac724a34221bd5f2891')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El dret a examinar les actuacions amb l''antelació deguda i, en tot cas, abans que se li prengui declaració.', false), ('B', 'El dret a no ser citat a declarar fins que hagi acabat la instrucció.', true), ('C', 'El dret a la traducció i la interpretació gratuïtes.', false), ('D', 'El dret a guardar silenci i a no prestar declaració si no ho vol.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
-- Lote pcat-e08-mesures-cautelars-lecrim-v1 (14 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto de 14 de septiembre de 1882, Ley de Enjuiciamiento Criminal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e08-mesures-cautelars', 'Tema 8. Mesures cautelars, detenció, habeas corpus, presó i llibertat provisional') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e08-mesures-cautelars' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 520.1 de la Llei d''enjudiciament criminal, dins dels terminis establerts en la llei i, en tot cas, en quin termini màxim el detingut ha de ser posat en llibertat o a disposició de l''autoritat judicial?', 'La detenció preventiva no pot durar més del temps estrictament necessari per a les averiguacions i, en tot cas, el detingut ha de ser posat en llibertat o a disposició judicial en un màxim de setanta-dues hores (art. 520.1 LECrim, que reprodueix l''art. 17.2 CE).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520.1 LECrim', 'Dentro de los plazos establecidos en la presente Ley, y, en todo caso, en el plazo máximo de setenta y dos horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial.', null, 'f13f42dcfc59773f2e099a95209a324399d7da1f74625988e478dfe83fc8a860', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f13f42dcfc59773f2e099a95209a324399d7da1f74625988e478dfe83fc8a860')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Vint-i-quatre hores.', false), ('B', 'Setanta-dues hores.', true), ('C', 'Quaranta-vuit hores.', false), ('D', 'Cinc dies.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei d''enjudiciament criminal, el particular, l''autoritat o l''agent de policia judicial que detingui una persona ha de posar-la en llibertat o lliurar-la al jutge més pròxim al lloc de la detenció:', 'L''art. 496 LECrim obliga qui ha practicat la detenció a posar el detingut en llibertat o lliurar-lo al jutge més pròxim dins de les vint-i-quatre hores següents; si la dilació excedeix aquest termini, incorre en responsabilitat penal.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 496 LECrim', 'deberá ponerla en libertad o entregarla al Juez más próximo al lugar en que hubiere hecho la detención dentro de las veinticuatro horas siguientes al acto de la misma.', null, '07ab5acc151248ba5d8e68930eba113f3ac417c632cde3ff03df5223cc05d8df', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '07ab5acc151248ba5d8e68930eba113f3ac417c632cde3ff03df5223cc05d8df')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins de les vint-i-quatre hores següents a la detenció.', true), ('B', 'Dins de les setanta-dues hores següents a la detenció.', false), ('C', 'Dins de les quaranta-vuit hores següents a la detenció.', false), ('D', 'Immediatament, sense que pugui passar més d''una hora.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 490 de la Llei d''enjudiciament criminal, qualsevol persona pot detenir, entre d''altres, les persones següents, EXCEPTE:', 'L''art. 490 LECrim enumera els casos en què qualsevol persona pot detenir. La detenció del processat per delicte amb pena superior a la de presó correccional és una obligació de l''autoritat o agent de policia judicial (art. 492.2), no una facultat de qualsevol persona.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Arts. 490 i 492 LECrim', 'Cualquier persona puede detener: 1.º Al que intentare cometer un delito en el momento de ir a cometerlo. 2.º Al delincuente in fraganti. 3.º Al que se fugare del establecimiento penal en que se halle extinguiendo condena.', null, '690d2714f2203cfd53e58d3784793458cd410492977a31125c96787f348beeed', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '690d2714f2203cfd53e58d3784793458cd410492977a31125c96787f348beeed')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qui intenti cometre un delicte en el moment d''anar a cometre''l.', false), ('B', 'El delinqüent in fraganti.', false), ('C', 'Qui estigui processat per un delicte que tingui assenyalada una pena superior a la de presó correccional.', true), ('D', 'Qui s''escapi de l''establiment penal on està extingint condemna.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 497 de la Llei d''enjudiciament criminal, el jutge o tribunal de la causa a qui es lliuri un detingut ha d''elevar la detenció a presó, o deixar-la sense efecte, en el termini de:', 'L''art. 497 LECrim fixa setanta-dues hores, comptades des del lliurament del detingut al jutge o tribunal, per elevar la detenció a presó o deixar-la sense efecte.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 497 LECrim', 'elevará la detención a prisión, o la dejará sin efecto, en el término de setenta y dos horas, a contar desde que el detenido le hubiese sido entregado.', null, '959e828d34de7087d59aec970a7ba4819608ac2af3adb6bbf401046114704f46', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '959e828d34de7087d59aec970a7ba4819608ac2af3adb6bbf401046114704f46')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Vint-i-quatre hores des que el detingut li hagi estat lliurat.', false), ('B', 'Setanta-dues hores des del moment de la detenció.', false), ('C', 'Deu dies des que el detingut li hagi estat lliurat.', false), ('D', 'Setanta-dues hores des que el detingut li hagi estat lliurat.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels drets següents NO figura entre els que, segons l''article 520.2 de la Llei d''enjudiciament criminal, s''han de comunicar a tota persona detinguda o presa?', 'L''art. 520.2 LECrim enumera, entre d''altres, el dret a guardar silenci, a no declarar contra si mateix, a designar advocat, a comunicar la privació de llibertat a un familiar, a intèrpret i a reconeixement pel metge forense. No inclou cap dret a triar el lloc de custòdia.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520.2 LECrim', 'a) Derecho a guardar silencio no declarando si no quiere, a no contestar alguna o algunas de las preguntas que le formulen, o a manifestar que sólo declarará ante el juez. […] c) Derecho a designar abogado, sin perjuicio de lo dispuesto en el apartado 1.a) del artículo 527 y a ser asistido por él sin demora injustificada. […] i) Derecho a ser reconocido por el médico forense o su sustituto legal', null, 'c16d6292d8ba921ea8db7d5f812bdd11951299693b742921943eebeb8f653f9d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c16d6292d8ba921ea8db7d5f812bdd11951299693b742921943eebeb8f653f9d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El dret a guardar silenci o a manifestar que només declararà davant el jutge.', false), ('B', 'El dret a escollir el centre o dependència on ha de quedar sota custòdia.', true), ('C', 'El dret a designar advocat i a ser assistit per ell sense demora injustificada.', false), ('D', 'El dret a ser reconegut pel metge forense o el seu substitut legal.', false)) as v(label, body, ok)
)
