with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 520.5 de la Llei d''enjudiciament criminal, l''advocat designat per assistir un detingut ha d''acudir al centre de detenció amb la màxima promptitud i sempre dins del termini màxim de:', 'L''art. 520.5 LECrim fixa un màxim de tres hores des de la recepció de l''encàrrec; si l''advocat no compareix, el Col·legi d''Advocats en designa un altre del torn d''ofici.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520.5 LECrim', 'El abogado designado acudirá al centro de detención con la máxima premura, siempre dentro del plazo máximo de tres horas desde la recepción del encargo.', null, '01526d39c488acb2412e0c9b648d1ce44a80edde60f57034c7c83cc083b82599', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '01526d39c488acb2412e0c9b648d1ce44a80edde60f57034c7c83cc083b82599')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una hora des de la recepció de l''encàrrec.', false), ('B', 'Vuit hores des de la detenció.', false), ('C', 'Tres hores des de la recepció de l''encàrrec.', true), ('D', 'Vint-i-quatre hores des de la detenció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 503 de la Llei d''enjudiciament criminal, amb caràcter general, la presó provisional només es pot decretar si consten en la causa fets que presentin caràcters de delicte sancionat amb una pena el màxim de la qual sigui igual o superior a:', 'El primer requisit de l''art. 503.1 LECrim és un delicte castigat amb pena màxima igual o superior a dos anys de presó, o inferior si l''investigat té antecedents penals no cancel·lats per delicte dolós.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 503.1 LECrim', 'Que conste en la causa la existencia de uno o varios hechos que presenten caracteres de delito sancionado con pena cuyo máximo sea igual o superior a dos años de prisión', null, '26ad28fcd0f2373f099bf20cf93f72840715ea6dc06bfd2913948454f187c35e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '26ad28fcd0f2373f099bf20cf93f72840715ea6dc06bfd2913948454f187c35e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un any de presó.', false), ('B', 'Tres anys de presó.', false), ('C', 'Dos anys de presó.', true), ('D', 'Cinc anys de presó.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 506 de la Llei d''enjudiciament criminal, la interlocutòria que acordi la presó provisional o en disposi la prolongació ha d''expressar:', 'Les resolucions sobre la situació personal de l''investigat adopten la forma d''interlocutòria, i la que acorda la presó provisional o la prolonga ha d''expressar els motius de necessitat i proporcionalitat respecte dels fins de la mesura (art. 506.1 LECrim).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 506.1 LECrim', 'El auto que acuerde la prisión provisional o disponga su prolongación expresará los motivos por los que la medida se considera necesaria y proporcionada respecto de los fines que justifican su adopción.', null, '14bb03f9f16ba2f0ad3ff2cb2ee93a5bd2266a726209d7f4889325479e6c94c9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '14bb03f9f16ba2f0ad3ff2cb2ee93a5bd2266a726209d7f4889325479e6c94c9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els motius pels quals la mesura es considera necessària i proporcionada respecte dels fins que en justifiquen l''adopció.', true), ('B', 'Només el delicte imputat i la pena que s''hi podria imposar.', false), ('C', 'La data prevista per a la celebració del judici oral.', false), ('D', 'El centre penitenciari on s''ha de complir i el grau de tractament inicial.', false)) as v(label, body, ok)
)
