select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 506.2 de la Llei d''enjudiciament criminal, si la causa s''ha declarat secreta, en la notificació de la interlocutòria de presó provisional no es pot ometre en cap cas:', 'L''art. 506.2 LECrim permet ometre de la còpia notificada els particulars que afectin el secret, però mai la descripció succinta del fet imputat ni els fins de l''art. 503; quan s''aixeca el secret, s''ha de notificar la interlocutòria íntegra.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 506.2 LECrim', 'En ningún caso se omitirá en la notificación una sucinta descripción del hecho imputado y de cuál o cuáles de los fines previstos en el artículo 503 se pretende conseguir con la prisión.', null, '71d0059edc5b2c5a669ac015ed71905f0eb4d1f931dda75f1a5958b8a64bd9ef', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '71d0059edc5b2c5a669ac015ed71905f0eb4d1f931dda75f1a5958b8a64bd9ef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La identitat dels testimonis que han declarat contra l''investigat.', false), ('B', 'La totalitat dels fonaments de la interlocutòria, encara que afectin el secret.', false), ('C', 'La durada màxima prevista de la presó provisional.', false), ('D', 'Una descripció succinta del fet imputat i del fi o fins de l''article 503 que es pretenen aconseguir amb la presó.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 504.2 de la Llei d''enjudiciament criminal, la presó provisional acordada per evitar el risc de fuga, si el delicte té assenyalada una pena privativa de llibertat superior a tres anys, no pot excedir, amb caràcter general, de:', 'L''art. 504.2 LECrim limita la presó provisional a un any si la pena és igual o inferior a tres anys i a dos anys si és superior, amb una única pròrroga possible; per evitar l''ocultació de proves, el màxim és de sis mesos (art. 504.3).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 504.2 LECrim', 'su duración no podrá exceder de un año si el delito tuviere señalada pena privativa de libertad igual o inferior a tres años, o de dos años si la pena privativa de libertad señalada para el delito fuera superior a tres años.', null, 'a3e72bacb5bb7dab932866e9de9648d347150b7ba15b388c70a200a150890e85', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a3e72bacb5bb7dab932866e9de9648d347150b7ba15b388c70a200a150890e85')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un any.', false), ('B', 'Dos anys.', true), ('C', 'Sis mesos.', false), ('D', 'Quatre anys.', false)) as v(label, body, ok)
)
