with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 530 de la Llei d''enjudiciament criminal, l''investigat o encausat que hagi d''estar en llibertat provisional, amb fiança o sense:', 'L''art. 530 LECrim imposa l''obligació apud acta de comparèixer els dies assenyalats i sempre que sigui cridat; per garantir-la, el jutge pot acordar motivadament la retenció del passaport (no és obligatòria en tot cas).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 530 LECrim', 'El investigado o encausado que hubiere de estar en libertad provisional, con o sin fianza, constituirá apud acta obligación de comparecer en los días que le fueren señalados en el auto respectivo, y además cuantas veces fuere llamado ante el juez o tribunal que conozca de la causa.', null, '5f23246cdaac749cea123562c9c8c67e595e0e2bb7a8f383a50de381cc31e51b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5f23246cdaac749cea123562c9c8c67e595e0e2bb7a8f383a50de381cc31e51b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Haurà de dur en tot cas un dispositiu telemàtic de control.', false), ('B', 'Haurà de lliurar obligatòriament el passaport en tots els casos.', false), ('C', 'Constituirà apud acta l''obligació de comparèixer els dies que li assenyali la interlocutòria i sempre que sigui cridat pel jutge o tribunal.', true), ('D', 'Haurà de residir en el partit judicial del jutjat que coneix de la causa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 544 bis de la Llei d''enjudiciament criminal, quan s''investiga un delicte dels esmentats a l''article 57 del Codi penal, el jutge o tribunal pot imposar cautelarment a l''inculpat, entre altres mesures:', 'L''art. 544 bis LECrim permet imposar cautelarment, de manera motivada, la prohibició de residir en determinats llocs i la d''acudir-hi o d''aproximar-se o comunicar-se amb determinades persones.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 544 bis LECrim', 'imponer cautelarmente al inculpado la prohibición de residir en un determinado lugar, barrio, municipio, provincia u otra entidad local, o comunidad autónoma.', null, 'dc081e51da06ef3353607deea8c5038ea824985060da0fec670e93d0af84e4aa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dc081e51da06ef3353607deea8c5038ea824985060da0fec670e93d0af84e4aa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La pena de localització permanent.', false), ('B', 'La prohibició de residir en un lloc, barri, municipi, província o altra entitat local, o comunitat autònoma determinats.', true), ('C', 'La inhabilitació absoluta mentre duri la instrucció.', false), ('D', 'La privació definitiva del dret a conduir vehicles de motor.', false)) as v(label, body, ok)
)
