with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 25.2 de la Constitució espanyola, cap a on han d''estar orientades les penes privatives de llibertat i les mesures de seguretat?', 'L''art. 25.2 CE estableix que les penes privatives de llibertat i les mesures de seguretat estaran orientades cap a la reeducació i la reinserció social i que no podran consistir en treballs forçats.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 25.2 CE', 'Las penas privativas de libertad y las medidas de seguridad estarán orientadas hacia la reeducación y reinserción social y no podrán consistir en trabajos forzados.', null, '00f4a2e366ecc4e31f9bce48986d5b5a492a2ff6eee8fda68860ab75ea5ddb02', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '00f4a2e366ecc4e31f9bce48986d5b5a492a2ff6eee8fda68860ab75ea5ddb02')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cap a la retenció i la custòdia dels condemnats.', false), ('B', 'Cap a la prevenció general i la retribució del delicte.', false), ('C', 'Cap a la reeducació i la reinserció social.', true), ('D', 'Cap a la reparació del dany causat a la víctima.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 25.2 de la Constitució espanyola, el condemnat a pena de presó que l''estigui complint gaudirà dels drets fonamentals del capítol II, a excepció dels que es vegin expressament limitats per:', 'Segons l''art. 25.2 CE, els drets fonamentals del condemnat només es poden limitar pel contingut de la decisió condemnatòria (fallo condenatorio), el sentit de la pena i la llei penitenciària.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 25.2 CE', 'El condenado a pena de prisión que estuviere cumpliendo la misma gozará de los derechos fundamentales de este Capítulo, a excepción de los que se vean expresamente limitados por el contenido del fallo condenatorio, el sentido de la pena y la ley penitenciaria.', null, '4b5ebf7a2a43abc6eb1097b8f0f05234ddc34d76869d3c4606a30adab0cc51ad', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4b5ebf7a2a43abc6eb1097b8f0f05234ddc34d76869d3c4606a30adab0cc51ad')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El contingut de la decisió condemnatòria, el sentit de la pena i la llei penitenciària.', true), ('B', 'El contingut de la decisió condemnatòria, el Reglament penitenciari i les normes de règim interior.', false), ('C', 'El sentit de la pena, les ordres del director o directora del centre i la llei penitenciària.', false), ('D', 'Les resolucions del jutge de vigilància penitenciària i les circulars del centre directiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 25.2 de la Constitució espanyola, a què tindrà dret en tot cas el condemnat a pena de presó que l''estigui complint?', 'L''últim incís de l''art. 25.2 CE reconeix «en tot cas» el dret a un treball remunerat, als beneficis de la Seguretat Social, a l''accés a la cultura i al desenvolupament integral de la personalitat.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 25.2 CE', 'En todo caso, tendrá derecho a un trabajo remunerado y a los beneficios correspondientes de la Seguridad Social, así como al acceso a la cultura y al desarrollo integral de su personalidad.', null, '043e8894d1c6f9235a15ebdc2c6e0eb9ddfe464070d0e87bc8d2fd0829a8b68c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '043e8894d1c6f9235a15ebdc2c6e0eb9ddfe464070d0e87bc8d2fd0829a8b68c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A un treball remunerat, sempre que ho permetin les disponibilitats pressupostàries de l''Administració penitenciària.', false), ('B', 'A la reducció de la condemna pel treball fet i a l''accés a la cultura.', false), ('C', 'A un permís ordinari de sortida anual i als beneficis de la Seguretat Social.', false), ('D', 'A un treball remunerat i als beneficis corresponents de la Seguretat Social, així com a l''accés a la cultura i al desenvolupament integral de la seva personalitat.', true)) as v(label, body, ok)
)
