with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 1 de la Llei orgànica 1/1979, general penitenciària (LOGP), quina és la finalitat primordial de les institucions penitenciàries?', 'L''art. 1 LOGP fixa com a fi primordial la reeducació i la reinserció social dels sentenciats, així com la retenció i custòdia de detinguts, presos i penats.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 1 LOGP', 'Las instituciones penitenciarias reguladas en la presente Ley tienen como fin primordial la reeducación y la reinserción social de los sentenciados a penas y medidas penales privativas de libertad, así como la retención y custodia de detenidos, presos y penados.', null, '29e45e99612406fa1df51efdb1fa68a981b8b00d5f50eb90b8df1612aa1c779d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '29e45e99612406fa1df51efdb1fa68a981b8b00d5f50eb90b8df1612aa1c779d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La retenció i custòdia de detinguts, presos i penats, i, de manera subsidiària, la seva reeducació.', false), ('B', 'La reeducació i la reinserció social dels sentenciats a penes i mesures penals privatives de llibertat, així com la retenció i custòdia de detinguts, presos i penats.', true), ('C', 'L''execució de les sentències penals i la protecció de la societat davant els delinqüents.', false), ('D', 'L''assistència social als interns, als alliberats i a les seves famílies.', false)) as v(label, body, ok)
)
