with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 2 de la LOGP, l''activitat penitenciària s''ha de desenvolupar amb les garanties i dins dels límits establerts per:', 'L''art. 2 LOGP parla de la Llei, els reglaments i les sentències judicials. La fórmula «la Constitució i la llei» és la de l''art. 3.1 del Reglament penitenciari, no la de la LOGP.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 2 LOGP', 'La actividad penitenciaria se desarrollará con las garantías y dentro de los límites establecidos por la Ley, los reglamentos y las sentencias judiciales.', null, '7c787948b0c687c171cdda79ca6ed027be536a0876fdc90f21d2e27088371148', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7c787948b0c687c171cdda79ca6ed027be536a0876fdc90f21d2e27088371148')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Llei, els reglaments i les sentències judicials.', true), ('B', 'La Constitució i la llei.', false), ('C', 'La Constitució, l''Estatut d''autonomia i les lleis.', false), ('D', 'Les lleis i les instruccions del centre directiu.', false)) as v(label, body, ok)
)
