with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3 de la LOGP, l''activitat penitenciària s''ha d''exercir respectant, en tot cas:', 'L''art. 3 LOGP imposa el respecte a la personalitat humana dels reclosos i als seus drets i interessos jurídics no afectats per la condemna, sense cap diferència per raó de raça, opinions polítiques, creences religioses, condició social o altres circumstàncies anàlogues.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 3 LOGP', 'La actividad penitenciaria se ejercerá respetando, en todo caso, la personalidad humana de los recluidos y los derechos e intereses jurídicos de los mismos no afectados por la condena', null, 'b8bb4dba30bf7139b60001da00c26e4b8d46ab637ffdc41eaf880db38b5a867a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b8bb4dba30bf7139b60001da00c26e4b8d46ab637ffdc41eaf880db38b5a867a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els drets dels reclosos, llevat que el director o directora del centre els limiti per raons de seguretat.', false), ('B', 'Només els drets fonamentals dels reclosos penats, però no els dels preventius.', false), ('C', 'Els drets dels reclosos que siguin compatibles amb les normes de règim interior.', false), ('D', 'La personalitat humana dels reclosos i els seus drets i interessos jurídics no afectats per la condemna.', true)) as v(label, body, ok)
)
