with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3.5 del Reglament penitenciari, mitjançant quins instruments poden dirigir els òrgans directius de l''Administració penitenciària les activitats dels seus òrgans jeràrquicament dependents?', 'L''art. 3.5 RP preveu que els òrgans directius dirigeixin els òrgans dependents mitjançant circulars, instruccions i ordres de servei.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 3.5 RP', 'Los órganos directivos de la Administración penitenciaria podrán dirigir las actividades de sus órganos jerárquicamente dependientes mediante circulares, instrucciones y órdenes de servicio.', null, '4615c51f493a2a50dc19811abe617dd6878a2401d65c5f3c43480bdc766c5bcc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4615c51f493a2a50dc19811abe617dd6878a2401d65c5f3c43480bdc766c5bcc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Decrets, ordres i resolucions.', false), ('B', 'Reglaments de règim interior i acords del consell de direcció.', false), ('C', 'Circulars, instruccions i ordres de servei.', true), ('D', 'Instruccions i propostes de la junta de tractament.', false)) as v(label, body, ok)
)
