with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1.2 del Reglament penitenciari, en les comunitats autònomes que exerceixen competències d''execució de la legislació penitenciària estatal, quins preceptes del Reglament s''apliquen de manera supletòria?', 'L''art. 1.2 RP, en virtut de la potestat d''autoorganització de les comunitats autònomes, només fa supletoris els preceptes organitzatius o de règim economicoadministratiu (títols XI i XII i disposicions anàlogues d''altres títols).', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 1.2 RP', 'No obstante, en aquellas Comunidades Autónomas que ejerzan competencias de ejecución de la legislación penitenciaria estatal, en virtud de su potestad de autoorganización, será de aplicación supletoria lo dispuesto en aquellos preceptos de los Títulos XI y XII que regulen cuestiones organizativas o relativas al régimen económico-administrativo de los establecimientos penitenciarios, así como aquellas disposiciones contenidas en otros Títulos que regulen aspectos de la misma naturaleza.', null, 'b2447bb319d9e52e5c128a6ba9143f04c0f3d1a0a5c7df4113062a3e879907fb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b2447bb319d9e52e5c128a6ba9143f04c0f3d1a0a5c7df4113062a3e879907fb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tots els preceptes del Reglament, sense excepció.', false), ('B', 'Només els preceptes relatius al règim disciplinari dels interns.', false), ('C', 'Els dels títols I i II relatius als drets dels interns i a l''ingrés en els establiments.', false), ('D', 'Els dels títols XI i XII que regulin qüestions organitzatives o relatives al règim economicoadministratiu dels establiments, i les disposicions d''altres títols de la mateixa naturalesa.', true)) as v(label, body, ok)
)
