with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, pel qual s''aprova el Reglament d''organització i funcionament dels serveis d''execució penal a Catalunya, de quins tipus poden ser els establiments o centres penitenciaris?', 'L''art. 3.1 del Decret 329/2006 distingeix dos tipus d''establiments: ordinaris i especials. Amb caràcter general funcionen com a centres polivalents.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 3.1 Decret 329/2006', 'De conformitat amb el que disposa la legislació penitenciària, els establiments o centres penitenciaris poden ser de dos tipus: ordinaris i especials.', null, '455870c9c07e07512df3fc37b66780363ab1d9c2d39f0a774f8edbaf52a43d29', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '455870c9c07e07512df3fc37b66780363ab1d9c2d39f0a774f8edbaf52a43d29')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ordinaris, especials i de compliment.', false), ('B', 'Preventius, de compliment i especials.', false), ('C', 'Ordinaris i especials.', true), ('D', 'Oberts, ordinaris i tancats.', false)) as v(label, body, ok)
)
