with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, qui és la màxima autoritat de l''establiment penitenciari i té la representació del centre directiu?', 'L''art. 12.1 diu que el director o directora és la màxima autoritat de l''establiment i té la representació del centre directiu i dels òrgans col·legiats del centre.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 12.1 Decret 329/2006', 'El/La director/a del centre penitenciari serà la màxima autoritat de l''establiment i tindrà la representació del centre directiu del departament competent en matèria d''execució penal i dels òrgans col·legiats del centre penitenciari', null, '49cde8a2717c7b25f144bc3239cb6ece163415c5434afc5b1b692c6507434b70', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '49cde8a2717c7b25f144bc3239cb6ece163415c5434afc5b1b692c6507434b70')
  returning id
), o as (
