  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director o directora del centre penitenciari.', true), ('B', 'El o la gerent.', false), ('C', 'El subdirector o subdirectora d''Interior.', false), ('D', 'El cap de serveis.', false)) as v(label, body, ok)
)
