  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Imposar les sancions per les infraccions lleus comeses pels interns, amb la instrucció prèvia d''un procediment abreujat.', false), ('B', 'Suspendre i extingir la relació laboral especial dels interns treballadors per raons de disciplina i seguretat penitenciària.', false), ('C', 'Concedir els permisos penitenciaris de sortida, amb l''informe previ de l''equip multidisciplinari.', true), ('D', 'Adoptar les mesures regimentals urgents necessàries per prevenir i resoldre qualsevol alteració de l''ordre, i donar-ne compte immediat al centre directiu.', false)) as v(label, body, ok)
)
