with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, quin òrgan unipersonal, amb rang de subdirector, és el responsable de la gestió dels recursos humans, econòmics, materials i patrimonials assignats al centre penitenciari?', 'L''art. 13.1 configura el o la gerent, amb rang de subdirector i dependent del director, com a responsable de la gestió dels recursos humans, econòmics, materials i patrimonials i de l''oficina de gestió unificada dels expedients dels interns.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 13.1 Decret 329/2006', 'El/La gerent, amb rang de subdirector/a, dependrà del/de la director/a i serà la persona responsable de la gestió dels recursos humans, econòmics, materials i patrimonials assignats al centre penitenciari', null, 'ff7c8f6d2e52878f06d891fbbc5144ff2531eee30b8cac9649b8adfd7f8a619f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ff7c8f6d2e52878f06d891fbbc5144ff2531eee30b8cac9649b8adfd7f8a619f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El o la gerent.', true), ('B', 'El secretari o secretària tècnic jurídic.', false), ('C', 'El subdirector o subdirectora de Tractament.', false), ('D', 'El cap de la unitat de recursos humans.', false)) as v(label, body, ok)
)
