with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, quin òrgan és el responsable superior dels registres i dels arxius del centre penitenciari i formula i edita la memòria anual d''activitats?', 'L''art. 16.1 atribueix al secretari o secretària tècnic jurídic, amb rang de subdirector, l''assessorament jurídic i regimental, la secretaria dels òrgans col·legiats, la responsabilitat superior dels registres i arxius i la memòria anual.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 16.1 Decret 329/2006', 'També serà la persona responsable superior dels registres, dels arxius i formularà i editarà la memòria anual d''activitats del centre penitenciari.', null, '28bdeefe56d3deafab72ba35846d82d2196efc3141b9ef4d76368f1cf054aaa9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '28bdeefe56d3deafab72ba35846d82d2196efc3141b9ef4d76368f1cf054aaa9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El o la gerent.', false), ('B', 'El secretari o secretària tècnic jurídic.', true), ('C', 'El director o directora.', false), ('D', 'El cap de la unitat de gestió penitenciària.', false)) as v(label, body, ok)
)
