with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 20 del Decret 329/2006, quins són els òrgans col·legiats dels centres penitenciaris de Catalunya?', 'L''art. 20 enumera tres òrgans col·legiats: Consell de Direcció, Junta de Tractament i Comissió Disciplinària. Els equips multidisciplinaris són unitats d''estudi, proposta i execució de la Junta de Tractament (art. 36).', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 20 Decret 329/2006', 'Els òrgans col·legiats dels centres penitenciaris de Catalunya seran els següents: a) Consell de Direcció. b) Junta de Tractament. c) Comissió Disciplinària.', null, 'deb9075dea04789bea527b997ad7206ff57f471478cfea4e64f69d009625ff1d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'deb9075dea04789bea527b997ad7206ff57f471478cfea4e64f69d009625ff1d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Consell de Direcció, la Junta de Tractament i l''equip multidisciplinari.', false), ('B', 'La Junta de Règim i Administració, la Junta de Tractament i la Comissió Disciplinària.', false), ('C', 'El Consell de Direcció, la Junta de Tractament i la Comissió Disciplinària.', true), ('D', 'La Junta de Tractament, la Comissió Disciplinària i el Consell Social Penitenciari.', false)) as v(label, body, ok)
)
