with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, amb quina periodicitat s''ha de reunir en sessió ordinària la Comissió Disciplinària?', 'L''art. 24 fixa les sessions ordinàries: Consell de Direcció, dues vegades al mes; Junta de Tractament, una vegada per setmana; Comissió Disciplinària, tres vegades al mes.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 24 Decret 329/2006', 'La Comissió Disciplinària es reunirà en sessió ordinària tres vegades al mes i en sessió extraordinària totes les vegades que ho consideri necessari el/la seu/seva president/a.', null, '07ef950165acea166401e8fa6e9b7705799b40e385d9a520bc46002b6165fb16', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '07ef950165acea166401e8fa6e9b7705799b40e385d9a520bc46002b6165fb16')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dues vegades al mes.', false), ('B', 'Una vegada per setmana.', false), ('C', 'Una vegada al mes.', false), ('D', 'Tres vegades al mes.', true)) as v(label, body, ok)
)
