with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, quin és el quòrum de constitució del Consell de Direcció?', 'L''art. 28 (i, de manera idèntica, els arts. 31 i 34 per a la Junta de Tractament i la Comissió Disciplinària) exigeix dos terços en primera convocatòria i la meitat dels components en segona, una hora després.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 28 Decret 329/2006', 'La convocatòria de sessió del Consell de Direcció haurà de preveure una primera convocatòria, el quòrum de constitució de la qual serà el dels dos terços dels seus components. Per al cas que no s''assoleixi el quòrum exigit, s''haurà de preveure una segona convocatòria per a una hora després en la qual el quòrum s''assoleixi amb l''assistència de la meitat dels seus components.', null, 'b029ebd3cf3890bc2b34bc0eff5cf1750c25bd8e092134cdd77f04d5dc4981ca', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b029ebd3cf3890bc2b34bc0eff5cf1750c25bd8e092134cdd77f04d5dc4981ca')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La majoria absoluta en primera convocatòria i un terç en segona convocatòria, mitja hora després.', false), ('B', 'Dos terços dels components en primera convocatòria i un terç en segona convocatòria, vint-i-quatre hores després.', false), ('C', 'Dos terços dels components en primera convocatòria i la meitat en segona convocatòria, una hora després.', true), ('D', 'La meitat més un en primera convocatòria i la meitat en segona convocatòria, una hora després.', false)) as v(label, body, ok)
)
