with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 33 del Decret 329/2006, quin dels càrrecs següents NO forma part de la Comissió Disciplinària?', 'La Comissió Disciplinària la presideix el director o directora i la componen el subdirector d''Interior, el subdirector de Tractament, el secretari tècnic jurídic, un cap de serveis i un funcionari de la plantilla. El o la gerent no en forma part.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 33.1 Decret 329/2006', '1. La Comissió Disciplinària estarà presidida pel/per la director/a i composta pels membres següents: a) El/La subdirector/a d''Interior. b) El/La subdirector/a de Tractament. c) El/La secretari/ària tècnic/a jurídic/a. d) Un/a cap de serveis. e) Un/a funcionari/ària de la plantilla del centre penitenciari.', null, '73a03056b04d776da605bb47fd84cfb53534c9f6c3963a42abdeef61becd0eb5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '73a03056b04d776da605bb47fd84cfb53534c9f6c3963a42abdeef61becd0eb5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El subdirector o subdirectora d''Interior.', false), ('B', 'El o la gerent.', true), ('C', 'Un o una cap de serveis.', false), ('D', 'Un funcionari o funcionària de la plantilla del centre penitenciari.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, com es designen el cap de serveis i el funcionari o funcionària de plantilla que formen part de la Comissió Disciplinària?', 'L''art. 33.4 preveu que els designi el director o directora a proposta dels empleats públics de l''establiment, que els elegeixen anualment. En canvi, el psicòleg i el jurista de la Junta de Tractament els designa anualment el Consell de Direcció (art. 30.5).', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 33.4 Decret 329/2006', 'Els membres citats als paràgrafs d) i e) seran designats pel/per la director/a del centre penitenciari a proposta dels empleats públics de l''establiment que els elegiran anualment', null, 'bd26e842e5c8a7ad4bb1a99d9d47650913bd7a4c277d671fc93f0f5fb4bfd839', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bd26e842e5c8a7ad4bb1a99d9d47650913bd7a4c277d671fc93f0f5fb4bfd839')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els designa el director o directora, a proposta dels empleats públics de l''establiment, que els elegeixen anualment.', true), ('B', 'Els designa el Consell de Direcció anualment entre els professionals del centre.', false), ('C', 'Els designa el centre directiu cada dos anys, a proposta del director o directora.', false), ('D', 'Són elegits per sorteig cada any entre els funcionaris de l''àmbit de règim interior.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, quin òrgan exerceix la potestat disciplinària en els centres oberts o centres d''inserció social?', 'L''art. 35.3 atribueix a la Junta de Tractament la potestat disciplinària i la concessió de recompenses en els centres oberts, unitats de règim obert, centres especials, departaments d''atenció especialitzada i altres formes especials d''execució.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 35.3 Decret 329/2006', 'En els centres oberts o centres d''inserció social, en les unitats i seccions de règim obert, en els centres especials, en els departaments d''atenció especialitzada i en aquells altres on es duguin a terme formes especials d''execució, correspon a la Junta de Tractament l''exercici de la potestat disciplinària', null, 'aa0d9ae365554c71187d60aaf7a6c939fba272d983ba4586e63a9dccbd999e26', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'aa0d9ae365554c71187d60aaf7a6c939fba272d983ba4586e63a9dccbd999e26')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Junta de Tractament.', true), ('B', 'La Comissió Disciplinària del centre penitenciari del qual depenen.', false), ('C', 'El director o directora del centre, en tots els casos.', false), ('D', 'El jutge o jutgessa de vigilància penitenciària.', false)) as v(label, body, ok)
)
