with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 168.1 de l''Estatut d''autonomia de Catalunya, quina competència correspon a la Generalitat en matèria penitenciària?', 'L''art. 168.1 EAC atribueix a la Generalitat la competència executiva de la legislació de l''Estat en matèria penitenciària, que inclou en tot cas les facultats de les lletres a) a e).', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 168.1 EAC', 'Corresponde a la Generalitat la competencia ejecutiva de la legislación del Estado en materia penitenciaria, que incluye en todo caso:', null, 'd49e96ca0799ee4e02b4904431071c97462060a9400e67f27d46850fefc2543e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd49e96ca0799ee4e02b4904431071c97462060a9400e67f27d46850fefc2543e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La competència executiva de la legislació de l''Estat.', true), ('B', 'La competència exclusiva, que inclou la potestat legislativa.', false), ('C', 'La competència compartida, amb potestat per dictar la legislació de desplegament.', false), ('D', 'Només la gestió dels establiments que l''Estat li delegui.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les facultats següents NO està inclosa expressament en la competència penitenciària de la Generalitat segons l''article 168.1 de l''Estatut d''autonomia?', 'L''art. 168.1 EAC inclou dictar disposicions d''adaptació, la gestió de tota l''activitat penitenciària, la planificació i construcció d''establiments, la gestió patrimonial i l''organització del treball remunerat, les mesures alternatives i la reinserció. Es tracta d''una competència executiva, sense potestat legislativa sobre els drets dels interns.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 168.1 EAC', 'a) La capacidad para dictar disposiciones que adapten la normativa penitenciaria a la realidad social de Cataluña. […] c) La planificación, la construcción y la reforma de los establecimientos penitenciarios situados en Cataluña. […] e) La planificación y organización del trabajo remunerado de la población reclusa', null, '19116870e27af1b3f75d19ccb0031742fcb623775af78a9460699485321ed036', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '19116870e27af1b3f75d19ccb0031742fcb623775af78a9460699485321ed036')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La capacitat per dictar disposicions que adaptin la normativa penitenciària a la realitat social de Catalunya.', false), ('B', 'L''aprovació de la llei que regula els drets i deures dels interns a Catalunya.', true), ('C', 'La planificació, la construcció i la reforma dels establiments penitenciaris situats a Catalunya.', false), ('D', 'La planificació i l''organització del treball remunerat de la població reclosa.', false)) as v(label, body, ok)
)
