-- Lote pcat-e11-personal-penitenciari-codietic-v1 (3 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Circular 2/2011, sobre el Codi ètic dels professionals de l''execució penal a Catalunya (Direcció General de Serveis Penitenciaris)', 'https://justicia.gencat.cat/web/.content/home/ambits/reinsercio_i_serveis_peni/instruccions_i_circulars/circular_codi_etic_execucio_penal.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament de Justícia', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e11-personal-penitenciari', 'Tema 11. El personal al servei de l''Administració penitenciària a Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e11-personal-penitenciari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi ètic dels professionals de l''execució penal a Catalunya, què ha de fer l''empleat públic quan l''ordre del superior jeràrquic constitueix una infracció manifesta, clara i terminant de l''ordenament jurídic?', 'La base 16.2 imposa l''obligació ètica i legal d''abstenir-se de complir l''ordre i de comunicar els motius de la discrepància; si el superior hi persisteix, cal comunicar-ho a l''autoritat de qui depèn o a l''autoritat judicial.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/ambits/reinsercio_i_serveis_peni/instruccions_i_circulars/circular_codi_etic_execucio_penal.pdf'), 'Base 16.2 Codi ètic', 'Quan l’ordre del superior jeràrquic constitueixi una infracció manifesta, clara i terminant de l’ordenament jurídic, l’empleada o empleat públic d’execució penal té l’obligació ètica i legal d’abstenir-se de complir-la. Té l’obligació ètica de comunicar al superior que ha emès l’ordre, d’una manera raonada, formal i respectuosa, els motius de la seva discrepància.', null, 'a8c67e583161e89aeb04860a19e2b20c58bdee68c4ad44107391b9826e77d9f6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a8c67e583161e89aeb04860a19e2b20c58bdee68c4ad44107391b9826e77d9f6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Complir-la i, posteriorment, presentar-ne una queixa per escrit.', false), ('B', 'Abstenir-se de complir-la i comunicar al superior, de manera raonada, formal i respectuosa, els motius de la discrepància.', true), ('C', 'Complir-la només si el superior la ratifica per escrit.', false), ('D', 'Sotmetre-la a la consideració de la Comissió de seguiment del Codi ètic abans d''executar-la.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi ètic dels professionals de l''execució penal a Catalunya, què ha de fer l''empleat públic davant d''un regal o favor que pugui condicionar la realització de les seves funcions?', 'La base 18 obliga a abstenir-se de sol·licitar prebendes i a refusar qualsevol regal, favor, benefici, promesa o servei en condicions avantatjoses que pugui condicionar les funcions. Només els obsequis institucionals de major significació s''incorporen al patrimoni de la Generalitat.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/ambits/reinsercio_i_serveis_peni/instruccions_i_circulars/circular_codi_etic_execucio_penal.pdf'), 'Base 18 Codi ètic', 'L’empleada o empleat públic d’execució penal s’ha d’abstenir de sol·licitar prebendes i ha de refusar qualsevol regal, favor, benefici, promesa o servei en condicions avantatjoses que pugui condicionar la realització de les seves funcions', null, '4e91e30526337c9fc4ce34ca22f677199031a156bb35f425b31534e4fb290787', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4e91e30526337c9fc4ce34ca22f677199031a156bb35f425b31534e4fb290787')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Acceptar-lo, si el seu valor és simbòlic, i comunicar-ho al superior.', false), ('B', 'Acceptar-lo i incorporar-lo al patrimoni del centre penitenciari.', false), ('C', 'Acceptar-lo només si prové d''un familiar de l''intern i no d''aquest.', false), ('D', 'Refusar-lo.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
