select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, a quines àrees poden ser assignats els caps d''àrea funcional, segons permetin les relacions de llocs de treball?', 'L''art. 66.3 preveu que els caps d''àrea funcional s''assignin a àrees com ara comunicacions, tallers productius o dependències de formació. Durant el servei assumeixen les funcions pròpies dels caps d''unitat en allò que afecti la seva àrea (art. 66.2).', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 66 Decret 329/2006', 'Els/Les caps de l''àrea funcional seran assignats/ades, segons permetin les relacions de llocs de treball, a àrees com ara les de comunicacions, de tallers productius, de dependències de formació acadèmica o per al treball', null, '9a9e268cf33442fb274be56218a2268b26eb5cef8cfd1e103101c54c9ea4d259', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9a9e268cf33442fb274be56218a2268b26eb5cef8cfd1e103101c54c9ea4d259')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A àrees com ara les de comunicacions, tallers productius o dependències de formació acadèmica o per al treball.', true), ('B', 'Exclusivament als departaments especials de règim tancat.', false), ('C', 'A les unitats de gestió penitenciària, de recursos humans i de gestió econòmica.', false), ('D', 'A les unitats dependents i als centres oberts.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
