with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 9/1986, de cossos de funcionaris de la Generalitat, quines funcions han de desenvolupar els membres del cos tècnic d''especialistes?', 'L''art. 3.2 de la Llei 9/1986 assigna al cos tècnic d''especialistes (grup C) les funcions d''execució, col·laboració i similars. Les d''estudi i proposta corresponen al cos de titulació superior i les derivades de la titulació, al de diplomatura.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-32139'), 'Art. 3 Llei 9/1986', 'Las funciones que han de desarrollar los miembros del Cuerpo Técnico de Especialistas son las de ejecución, colaboración y similares adecuadas a su nivel de titulación y especialización.', null, 'b8e90040eb26e3635ae33eccec7715322815c8cb250f6e9e33cf6735ba102f5c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b8e90040eb26e3635ae33eccec7715322815c8cb250f6e9e33cf6735ba102f5c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les d''execució, col·laboració i similars adequades al seu nivell de titulació i especialització.', true), ('B', 'Les d''estudi, proposta, control, execució i inspecció de les tasques tècniques derivades de la seva titulació.', false), ('C', 'Les derivades de l''exercici professional de la seva titulació acadèmica.', false), ('D', 'Les d''execució i col·laboració adequades al seu nivell d''especialització, sense requisit de titulació.', false)) as v(label, body, ok)
)
