insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 17/2015, de 21 de julio, de igualdad efectiva de mujeres y hombres (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e11-personal-penitenciari', 'Tema 11. El personal al servei de l''Administració penitenciària a Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e11-personal-penitenciari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 17/2015, d''igualtat efectiva de dones i homes, els plans d''igualtat del sector públic han d''incloure mesures específiques per adequar-se a les peculiaritats de determinats col·lectius. Quin d''aquests col·lectius s''hi esmenta expressament?', 'L''art. 15.4 c) obliga a incloure mesures específiques per al personal docent, sanitari, investigador i penitenciari, i per a bombers, agents rurals i cossos i forces de seguretat. Els plans s''han d''avaluar cada quatre anys (art. 15.4 e).', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 15.4.c Llei 17/2015', 'c) Incluir medidas específicas para su adecuación, en cada caso, a las peculiaridades del personal docente, sanitario, investigador y penitenciario, así como de bomberos, agentes rurales y cuerpos y fuerzas de seguridad.', null, 'a2bf5391092d14e1bccba9d5de48dc312d347b02b9324fd5572af329a5bdfbc4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a2bf5391092d14e1bccba9d5de48dc312d347b02b9324fd5572af329a5bdfbc4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El personal de l''Administració de justícia.', false), ('B', 'El personal de les empreses de neteja contractades.', false), ('C', 'El personal penitenciari.', true), ('D', 'El personal eventual dels gabinets.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 54 de la Llei 17/2015, amb quin objectiu ha d''oferir l''Administració de la Generalitat formació específica en gènere, igualtat i drets de les dones als cossos penitenciaris?', 'L''art. 54.4 b) fixa per als cossos penitenciaris l''objectiu d''evitar l''estigmatització de les internes i els micromasclismes. L''objectiu de la segona opció és el que l''art. 54.4 c) assigna als cossos judicials.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 54.4.b Llei 17/2015', 'b) A los cuerpos penitenciarios, con el objetivo de evitar la estigmatización de las internas y el ejercicio de micromachismos contra las mujeres.', null, '5a6fe5b6a367f98b50c33976a0651bfe993333472b5fe30910e01ddbd4bb029a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5a6fe5b6a367f98b50c33976a0651bfe993333472b5fe30910e01ddbd4bb029a')
  returning id
