with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3.2 del Reglament penitenciari, en quin cas es poden restringir els drets dels interns?', 'L''art. 3.2 RP estableix una reserva de llei: els drets dels interns només es poden restringir quan ho disposin les lleis.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 3.2 RP', 'Los derechos de los internos sólo podrán ser restringidos cuando lo dispongan las leyes.', null, '4809e471f7debda898d9b74cb806ae70e30b8bd7122dfbae0e9cc8d343e550b7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4809e471f7debda898d9b74cb806ae70e30b8bd7122dfbae0e9cc8d343e550b7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només quan ho disposin les lleis.', true), ('B', 'Quan ho acordi el director o directora del centre per raons de seguretat.', false), ('C', 'Quan ho disposin les normes de règim interior aprovades pel centre directiu.', false), ('D', 'Quan ho proposi la junta de tractament en el programa individualitzat.', false)) as v(label, body, ok)
)
