  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En quin article del Reglament penitenciari es recullen els drets dels interns?', 'El capítol II del títol I del RP regula els drets (art. 4) i els deures (art. 5) dels interns. L''art. 3 recull els principis i l''art. 6 limita l''ús de la informàtica penitenciària.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 4 RP', 'Artículo 4. Derechos. 1. La actividad penitenciaria se ejercerá respetando la personalidad de los internos', null, 'd6254f4ba3c7cba8d797ab5cfe1ea4795d6ea562a3db59320d73480c9f1a5e0e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd6254f4ba3c7cba8d797ab5cfe1ea4795d6ea562a3db59320d73480c9f1a5e0e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En l''article 3.', false), ('B', 'En l''article 5.', false), ('C', 'En l''article 6.', false), ('D', 'En l''article 4.', true)) as v(label, body, ok)
)
