with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 4.1 del Reglament penitenciari, l''activitat penitenciària s''ha d''exercir sense que pugui prevaler cap discriminació per raó de:', 'L''art. 4.1 RP prohibeix tota discriminació per raó de raça, sexe, religió, opinió, nacionalitat o qualsevol altra condició o circumstància personal o social.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 4.1 RP', 'sin que pueda prevalecer discriminación alguna por razón de raza, sexo, religión, opinión, nacionalidad o cualquier otra condición o circunstancia personal o social.', null, '84ebc1c8c9212be65c2cf4d1e8b1ec75c47cb15b3797a1ac3af3efcc219a188d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '84ebc1c8c9212be65c2cf4d1e8b1ec75c47cb15b3797a1ac3af3efcc219a188d')
