with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels següents NO és un dels drets dels interns enumerats a l''article 4.2 del Reglament penitenciari?', 'L''art. 4.2 RP inclou, entre d''altres, els drets a la informació sobre la situació processal i penitenciària (k), als beneficis penitenciaris (h) i a participar en les activitats del centre (i). No reconeix cap dret a triar el centre de compliment.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 4.2 RP', 'h) Derecho a los beneficios penitenciarios previstos en la legislación. i) Derecho a participar en las actividades del centro. […] k) Derecho a recibir información personal y actualizada de su situación procesal y penitenciaria.', null, 'c2f201417c48da6190a83a07a69999af075bb5c67b62bd5d0b8d854a8e2bda69', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c2f201417c48da6190a83a07a69999af075bb5c67b62bd5d0b8d854a8e2bda69')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dret a rebre informació personal i actualitzada de la seva situació processal i penitenciària.', false), ('B', 'Dret als beneficis penitenciaris previstos a la legislació.', false), ('C', 'Dret a participar en les activitats del centre.', false), ('D', 'Dret a triar el centre penitenciari on complir la condemna.', true)) as v(label, body, ok)
)
