with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 5.1 del Reglament penitenciari, l''intern s''incorpora a una comunitat que el vincula de manera especialment estreta. Què se li pot exigir per aquest motiu?', 'L''art. 5.1 RP fonamenta els deures en la incorporació a una comunitat que vincula estretament l''intern, de qui es pot exigir col·laboració activa i comportament solidari.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 5.1 RP', 'El interno se incorpora a una comunidad que le vincula de forma especialmente estrecha, por lo que se le podrá exigir una colaboración activa y un comportamiento solidario en el cumplimiento de sus obligaciones.', null, '86af5ede42efca98c9d07056b36946ce7e8e2b544380da9dc8bda7ecbe7ce209', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '86af5ede42efca98c9d07056b36946ce7e8e2b544380da9dc8bda7ecbe7ce209')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La participació obligatòria en tots els programes de tractament.', false), ('B', 'Una col·laboració activa i un comportament solidari en el compliment de les seves obligacions.', true), ('C', 'La renúncia als drets que no siguin compatibles amb la vida en comunitat.', false), ('D', 'Una contribució econòmica a les despeses de manteniment de l''establiment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels següents NO és un deure de l''intern segons l''article 5.2 del Reglament penitenciari?', 'L''art. 5.2 RP inclou, entre altres, els deures de les lletres d), e) i f). El tractament no és un deure: la LOGP només preveu que es procuri fomentar la col·laboració de l''intern en el tractament (art. 4.2 LOGP).', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 5.2 RP', 'd) Utilizar adecuadamente los medios materiales que se pongan a su disposición y las instalaciones del establecimiento. e) Observar una adecuada higiene y aseo personal, corrección en el vestir y acatar las medidas higiénicas y sanitarias establecidas a estos efectos. f) Realizar las prestaciones personales obligatorias impuestas por la Administración penitenciaria para el buen orden y limpieza de los establecimientos.', null, 'db73f6259305adce9fbe4a06496a566e731e5ce024a6f2d821d7e199a4fb4589', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'db73f6259305adce9fbe4a06496a566e731e5ce024a6f2d821d7e199a4fb4589')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fer les prestacions personals obligatòries que imposi l''Administració penitenciària per al bon ordre i la neteja dels establiments.', false), ('B', 'Utilitzar adequadament els mitjans materials que es posin a la seva disposició i les instal·lacions de l''establiment.', false), ('C', 'Sotmetre''s obligatòriament al tractament penitenciari que li prescriguin.', true), ('D', 'Observar una higiene i una neteja personal adequades i correcció en el vestir.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 54 del Reglament penitenciari, quan un intern presenta un escrit de queixa o de recurs adreçat al jutge de vigilància penitenciària en una oficina de registre de l''Administració penitenciària, en quin termini màxim s''ha de remetre al jutge?', 'L''art. 54.3 RP obliga a remetre l''escrit sense dilació i, en tot cas, en un termini màxim de tres dies, després de lliurar-ne rebut o còpia segellada a l''intern.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 54.3 RP', 'se remitirá, sin dilación y en todo caso en el plazo máximo de tres días, al Juez de Vigilancia Penitenciaria correspondiente.', null, 'df93c63e89444d203b90a2bf1826af9e8913d7030bef012083fbfc3c08222b72', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'df93c63e89444d203b90a2bf1826af9e8913d7030bef012083fbfc3c08222b72')
  returning id
), o as (
