with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 31 del Reglament penitenciari, quin òrgan té competència exclusiva per decidir la classificació i la destinació dels interns en els diferents establiments penitenciaris?', 'El centre directiu té la competència exclusiva per decidir la classificació i la destinació dels interns, amb caràcter ordinari o extraordinari. Les atribucions dels jutges de vigilància en matèria de classificació hi queden a salvo per via de recurs (art. 31.1 RP).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 31.1 RP', 'el centro directivo tiene competencia exclusiva para decidir, con carácter ordinario o extraordinario, la clasificación y destino de los reclusos en los distintos establecimientos penitenciarios', null, 'f0541cdc240824f719ea316ec09953970128d342fd98d394bcf46f34dbdaf0de', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f0541cdc240824f719ea316ec09953970128d342fd98d394bcf46f34dbdaf0de')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge de vigilància penitenciària.', false), ('B', 'La junta de tractament de l''establiment.', false), ('C', 'El centre directiu.', true), ('D', 'El consell de direcció de l''establiment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, amb quina antelació mínima han de demanar les autoritats judicials o governatives la conducció d''un intern que es troba en un centre penitenciari d''una altra província?', 'Segons l''art. 33.2 RP, l''antelació mínima és de trenta dies. Si l''intern és en una altra província, la conducció es demana al centre directiu; si és a la mateixa província o localitat, al director de l''establiment.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 33.2 RP', 'Las autoridades judiciales o gubernativas recabarán del centro directivo, con una antelación mínima de treinta días, la conducción oportuna del interno, cuando estuviere recluido en el centro penitenciario ubicado en otra provincia', null, '85d988ee76cfc4e4b8240a39938d5ae1c192582d79ed7fe01d95aa090d19fd07', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '85d988ee76cfc4e4b8240a39938d5ae1c192582d79ed7fe01d95aa090d19fd07')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quinze dies, i l''han de demanar al director de l''establiment.', false), ('B', 'Trenta dies, i l''han de demanar al director de l''establiment.', false), ('C', 'Trenta dies, i l''han de demanar al centre directiu.', true), ('D', 'Deu dies, i l''han de demanar al centre directiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 57 del Reglament penitenciari, sobre la participació dels interns en els establiments de preventius i de compliment ordinaris, quins interns NO poden ser elegits membres de les comissions?', 'L''art. 57.7 RP exclou de l''elecció els interns amb sancions per faltes molt greus o greus sense cancel·lar. El requisit del tercer grau només és per a les comissions dels establiments de règim obert (art. 56.5 RP).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 57.7 RP', 'No podrán ser elegidos aquellos internos que tengan sanciones disciplinarias por faltas muy graves o graves sin cancelar.', null, '0a2f9fdbfce93bcf1ffe7fe2ec407a3b9f346cbc99a0dc841529019d1917bfe8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0a2f9fdbfce93bcf1ffe7fe2ec407a3b9f346cbc99a0dc841529019d1917bfe8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els que tinguin sancions per qualsevol falta, fins i tot lleu, sense cancel·lar.', false), ('B', 'Els que no estiguin classificats en tercer grau de tractament.', false), ('C', 'Els que portin menys d''un any a la unitat de classificació.', false), ('D', 'Els que tinguin sancions disciplinàries per faltes molt greus o greus sense cancel·lar.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 42 del Reglament penitenciari, sobre les comunicacions orals, assenyaleu la resposta correcta.', 'El consell de direcció fixa els dies de comunicació, preferentment en caps de setmana, i n''han de ser com a mínim dues a la setmana (norma 1a). L''horari ha de permetre una durada mínima de vint minuts i no hi poden comunicar més de quatre persones alhora amb el mateix intern (norma 2a).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 42 RP', 'de manera que tengan, como mínimo, dos comunicaciones a la semana […] El horario destinado a este servicio será suficiente para permitir una comunicación de veinte minutos de duración como mínimo, no pudiendo comunicar más de cuatro personas simultáneamente con el mismo interno.', null, '1ca0e86ecc751657da89ab05e465335b2ecbb0a54dad7d8eaa665ef7252b66ff', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1ca0e86ecc751657da89ab05e465335b2ecbb0a54dad7d8eaa665ef7252b66ff')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els interns han de tenir, com a mínim, dues comunicacions a la setmana, d''una durada mínima de vint minuts.', true), ('B', 'Els interns han de tenir, com a mínim, una comunicació a la setmana, d''una durada mínima de trenta minuts.', false), ('C', 'Els interns han de tenir, com a mínim, dues comunicacions a la setmana, d''una durada mínima de quaranta minuts.', false), ('D', 'Hi poden comunicar simultàniament fins a sis persones amb el mateix intern.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 44 del Reglament penitenciari, quan el cap de serveis ordena suspendre una comunicació oral perquè els comunicants no observen un comportament correcte, quan s''ha d''informar el jutge de vigilància si el director ratifica la mesura?', 'El cap de serveis pot suspendre la comunicació per iniciativa pròpia o a proposta del funcionari, i n''informa immediatament el director. Si el director la ratifica en resolució motivada, n''ha d''informar el jutge de vigilància el mateix dia o l''endemà (art. 44.2 RP).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 44 RP', 'El Jefe de Servicios dará cuenta inmediata de la suspensión al Director del centro y éste, a su vez, si ratifica la medida en resolución motivada, deberá dar cuenta al Juez de Vigilancia en el mismo día o al día siguiente.', null, 'c3f6cf43b9dd7799923cd2fd7480df8481af062b07485b569736e920fdcbd40e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c3f6cf43b9dd7799923cd2fd7480df8481af062b07485b569736e920fdcbd40e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins de les setanta-dues hores següents, per mitjà del cap de serveis.', false), ('B', 'El mateix dia o l''endemà, mitjançant resolució motivada del director.', true), ('C', 'Dins dels tres dies hàbils següents, per mitjà del director.', false), ('D', 'No cal informar-ne el jutge de vigilància, perquè es tracta d''una mesura de règim interior.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre la restricció, la intervenció o la denegació de les comunicacions orals que regula l''article 43 del Reglament penitenciari, quina de les afirmacions següents NO és correcta?', 'Segons l''art. 43.1 RP, en el cas dels penats s''informa el jutge de vigilància, però en el cas dels detinguts o presos s''informa l''autoritat judicial de la qual depenen. Les altres tres afirmacions es corresponen amb el text.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 43.1 RP', 'el Director del establecimiento, con informe previo de la Junta de Tratamiento si la restricción, intervención o denegación se fundamenta en el tratamiento, lo acordará así en resolución motivada, que se notificará al interno, dando cuenta al Juez de Vigilancia en el caso de penados o a la autoridad judicial de la que dependa si se trata de detenidos o presos.', null, 'fd23b59f0a314b4481e3ea63877dc80bc99ac5fd1bc7bc24742af709632e69b6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fd23b59f0a314b4481e3ea63877dc80bc99ac5fd1bc7bc24742af709632e69b6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Si l''intern és un pres preventiu, se n''ha d''informar el jutge de vigilància penitenciària.', true), ('B', 'Les acorda el director de l''establiment en resolució motivada.', false), ('C', 'La resolució s''ha de notificar a l''intern.', false), ('D', 'Si es fonamenten en el tractament, cal l''informe previ de la junta de tractament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 45 del Reglament penitenciari, amb quina freqüència mínima i amb quina durada s''ha de concedir la comunicació íntima, amb la sol·licitud prèvia de l''intern?', 'Es concedeix una comunicació íntima al mes com a mínim, d''una a tres hores, tret que ho impedeixin raons d''ordre o de seguretat de l''establiment (art. 45.4 RP).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 45.4 RP', 'Previa solicitud del interno, se concederá una comunicación íntima al mes como mínimo, cuya duración no será superior a tres horas ni inferior a una, salvo que razones de orden o de seguridad del establecimiento lo impidan.', null, 'a5977f14f0fe396ac46ec9b1bef01556908052f5632b8ed5385df5bd903f2bc5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a5977f14f0fe396ac46ec9b1bef01556908052f5632b8ed5385df5bd903f2bc5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una a la setmana com a mínim, d''una durada no superior a dues hores.', false), ('B', 'Dues al mes com a mínim, d''una durada no superior a sis hores ni inferior a tres.', false), ('C', 'Una cada dos mesos com a mínim, d''una durada no superior a tres hores ni inferior a una.', false), ('D', 'Una al mes com a mínim, d''una durada no superior a tres hores ni inferior a una.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, les visites de convivència dels interns amb el seu cònjuge o persona lligada per una relació d''afectivitat semblant i amb els fills, quina durada màxima tenen i fins a quina edat dels fills?', 'L''art. 45.6 RP limita les visites de convivència a sis hores i a fills de fins a deu anys. A més, són compatibles amb les comunicacions ordinàries i amb les íntimes i familiars.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 45.6 RP', 'Se concederán, previa solicitud del interesado, visitas de convivencia a los internos con su cónyuge o persona ligada por semejante relación de afectividad e hijos que no superen los diez años de edad. […] su duración máxima será de seis horas.', null, '7b1dd53b5609386e2cbfaa2e960ce8f6614a579eecd54c0e80f91da0f593ed27', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7b1dd53b5609386e2cbfaa2e960ce8f6614a579eecd54c0e80f91da0f593ed27')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres hores com a màxim, amb fills que no superin els dotze anys.', false), ('B', 'Sis hores com a màxim, amb fills que no superin els deu anys.', true), ('C', 'Sis hores com a màxim, amb fills menors d''edat.', false), ('D', 'Quatre hores com a màxim, amb fills que no superin els sis anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, qui pot acordar la suspensió o la intervenció de les comunicacions d''un intern amb el seu advocat defensor?', 'L''art. 48.3 RP disposa que aquestes comunicacions no es poden suspendre ni intervenir en cap cas per decisió administrativa, sinó només amb l''ordre expressa prèvia de l''autoritat judicial.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 48.3 RP', 'no podrán ser suspendidas o intervenidas, en ningún caso, por decisión administrativa. La suspensión o la intervención de estas comunicaciones sólo podrá realizarse previa orden expresa de la autoridad judicial.', null, '3885a1c183f2008064b746edbbd436b9c89e9f870d4e072a8ea3938ee7f9d9ea', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3885a1c183f2008064b746edbbd436b9c89e9f870d4e072a8ea3938ee7f9d9ea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director, en resolució motivada, donant-ne compte al jutge de vigilància.', false), ('B', 'El cap de serveis, per iniciativa pròpia o a proposta del funcionari.', false), ('C', 'Només l''autoritat judicial, per ordre expressa.', true), ('D', 'El consell de direcció, amb l''informe previ de la junta de tractament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 47 del Reglament penitenciari, quina freqüència mínima s''ha de garantir en les comunicacions telefòniques dels interns i quina durada mínima tenen?', 'Des de la reforma del RD 268/2022, l''art. 47.4 RP garanteix un mínim de cinc trucades setmanals. La durada la fixen les normes de règim interior i no pot ser inferior a cinc minuts. Les paga l''intern, llevat de la comunicació de l''ingrés o del trasllat de l''art. 41.3 RP.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 47.4 RP', 'garantizando una frecuencia mínima de cinco llamadas por semana; su duración vendrá determinada en las normas de régimen interior del centro penitenciario, no siendo inferior a cinco minutos.', null, 'c737f096a3f1edf36cc2841f291c4e07ee8626f429b44b87d687946bf4af03f5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c737f096a3f1edf36cc2841f291c4e07ee8626f429b44b87d687946bf4af03f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dues trucades per setmana, d''una durada no inferior a deu minuts.', false), ('B', 'Cinc trucades al mes, d''una durada no inferior a cinc minuts.', false), ('C', 'Cinc trucades per setmana, d''una durada no inferior a cinc minuts.', true), ('D', 'Tres trucades per setmana, d''una durada no inferior a cinc minuts.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 50 del Reglament penitenciari, sobre els paquets que poden rebre els interns, assenyaleu la resposta correcta.', 'L''art. 50.5 RP fixa dos paquets al mes, o un en els establiments o departaments de règim tancat. Cada paquet pot pesar com a màxim 5 kg, i en aquest pes no es computen els llibres, les publicacions ni la roba.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 50.5 RP', 'El número de paquetes que pueden recibir los internos es de dos al mes, salvo en los Establecimientos o departamentos de régimen cerrado, que será de uno al mes. El peso de cada paquete no excederá de cinco kilogramos, no computándose dentro de dicho peso máximo los libros y publicaciones, ni tampoco la ropa.', null, '5b138e012da6fe944b6713d07fc9825639151d0ca19b077a456de684a388cae3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5b138e012da6fe944b6713d07fc9825639151d0ca19b077a456de684a388cae3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Poden rebre''n quatre al mes (dos, en règim tancat), de cinc quilograms com a màxim, incloent-hi els llibres i les publicacions.', false), ('B', 'Poden rebre''n dos al mes (un, en règim tancat), de cinc quilograms com a màxim, sense comptar-hi els llibres, les publicacions ni la roba.', true), ('C', 'Poden rebre''n dos al mes (un, en règim tancat), de deu quilograms com a màxim, sense comptar-hi la roba.', false), ('D', 'Poden rebre''n un a la setmana, sense límit de pes si només contenen llibres i roba.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 54 del Reglament penitenciari, quan un intern presenta una queixa o un recurs adreçat al jutge de vigilància penitenciària en una oficina de registre de l''Administració penitenciària, dins de quin termini màxim s''hi ha de trametre?', 'Després de lliurar a l''intern o al seu representant el rebut o la còpia simple datada i segellada, l''escrit es tramet al jutge de vigilància sense dilació i, en tot cas, en un màxim de tres dies (art. 54.3 RP).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 54.3 RP', 'se remitirá, sin dilación y en todo caso en el plazo máximo de tres días, al Juez de Vigilancia Penitenciaria correspondiente.', null, '6c96f62bc34b9ab589cf4d65828e374a53b40614d39e467964a6be12c0d927a4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6c96f62bc34b9ab589cf4d65828e374a53b40614d39e467964a6be12c0d927a4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sense dilació i, en tot cas, en el termini màxim de deu dies.', false), ('B', 'En el termini màxim de vint-i-quatre hores.', false), ('C', 'En el termini màxim de cinc dies hàbils.', false), ('D', 'Sense dilació i, en tot cas, en el termini màxim de tres dies.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 62 del Reglament penitenciari, sobre les entitats col·laboradores dedicades a l''assistència dels interns, quina de les afirmacions següents NO és correcta?', 'Segons l''art. 62 RP, el centre directiu aprova la sol·licitud i el programa amb l''informe previ de la junta de tractament. Després, l''entitat s''ha d''inscriure en el Registre Especial, i aquesta inscripció té caràcter merament declaratiu.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 62 RP', 'Aprobada la solicitud y el programa de colaboración por el Centro Directivo, previo informe de la Junta de Tratamiento del Centro penitenciario correspondiente, la institución o asociación colaboradora deberá inscribirse, para poder actuar, en el Registro Especial de Entidades Colaboradoras gestionado por el Centro Directivo […] La inscripción en el Registro Especial tendrá carácter meramente declarativo.', null, 'f079a3823d5cee61b7dac3b1076bdfba77a729fca1eb9911c776b47df0b3b9e0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f079a3823d5cee61b7dac3b1076bdfba77a729fca1eb9911c776b47df0b3b9e0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La sol·licitud i el programa els aprova el director del centre penitenciari, sense cap informe previ.', true), ('B', 'La sol·licitud de col·laboració i el programa d''intervenció els aprova el centre directiu.', false), ('C', 'La inscripció en el Registre especial d''entitats col·laboradores té caràcter merament declaratiu.', false), ('D', 'El programa ha d''incloure la relació nominativa del voluntariat que hi participarà.', false)) as v(label, body, ok)
)
