insert into public.sources (title, url, kind, publisher, published_on) values ('Circular 1/2008 sobre escorcolls i aplicació de mitjans de control adequats', 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament de Justícia', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e14-regim-penitenciari-2-seguretat', 'Tema 14. El règim penitenciari II: seguretat, mitjans coercitius i protocols') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e14-regim-penitenciari-2-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008 sobre escorcolls i aplicació de mitjans de control adequats, quina de les dades següents NO s''exigeix que consti en el comunicat que s''ha de fer dels escorcolls?', 'Segons l''apartat 1.3 de la Circular 1/2008, el comunicat el signen els funcionaris que han fet l''escorcoll i s''adreça al cap de serveis. Hi ha de constar el nom de l''intern, el lloc i la data, el cap de serveis present o la persona delegada, la motivació del nu integral i el resultat. No s''hi exigeix la signatura de l''intern.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.3', 'Dels escorcolls que es facin, s''han de fer comunicats, que han de signar els funcionaris que els hagin portat a terme i que s''han d''adreçar al cap de serveis. En aquests comunicats, hi ha de constar el nom de l''intern, el lloc i la data de l''escorcoll, el/la cap de serveis present durant l''escorcoll o persona en qui hagi delegat, la motivació suficient de l''escorcoll amb nu integral i el resultat del mateix', null, '7adb9d7c35119f65f4310d97b661652faa53eedaa45be2f56472b091bfe9434b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7adb9d7c35119f65f4310d97b661652faa53eedaa45be2f56472b091bfe9434b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El nom de l''intern i el lloc i la data de l''escorcoll.', false), ('B', 'El cap de serveis present durant l''escorcoll o la persona en qui hagi delegat.', false), ('C', 'La signatura de conformitat de l''intern escorcollat.', true), ('D', 'La motivació suficient de l''escorcoll amb nu integral i el resultat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, sota la supervisió i presència de qui s''han de fer els escorcolls amb nu integral dels interns?', 'L''apartat 1.2.3 de la Circular 1/2008 exigeix la supervisió i la presència d''un cap de serveis del mateix gènere que l''intern. Si no hi pot ser objectivament, ho delega en el cap d''unitat o en un altre que designi, però continua sent responsable de la supervisió.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.2.3', 'Aquests escorcolls s’hauran de realitzar sota la supervisió i presència d’un cap de serveis del mateix gènere que el del/ de la intern/interna sobre el que s’ha de practicar l’escorcoll. Si un cap de serveis no pogués objectivament estar present ho delegarà en el cap d’unitat del departament corresponent o en un altre que designi', null, '7b831e86634541a415b0db818fcea1d04f982425c92a2ccb3116e9b262cce5b1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7b831e86634541a415b0db818fcea1d04f982425c92a2ccb3116e9b262cce5b1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del director del centre o, en la seva absència, del subdirector d''interior.', false), ('B', 'Del metge de guàrdia del centre penitenciari.', false), ('C', 'D''un cap de serveis del mateix gènere que l''intern o la interna. Si no hi pot ser objectivament, ho delega en el cap d''unitat del departament o en un altre que designi.', true), ('D', 'D''un funcionari de qualsevol gènere designat pel cap d''unitat, sense necessitat de delegació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, què s''entén per escorcoll superficial d''un intern?', 'L''apartat 1.1 de la Circular 1/2008 considera l''escorcoll superficial i el dels efectes personals el supòsit normal o general. L''escorcoll superficial és la palpació de l''esquema corporal de la persona.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.1', 'El supòsit normal o general és l’escorcoll superficial de la persona i el dels seus efectes personals. Per escorcoll superficial s’entén la palpació de l’esquema corporal de la persona.', null, '63a6114b2b51c037b516a15b3e7762d9a793ec38a2848f5b20a0aab6c0eace31', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '63a6114b2b51c037b516a15b3e7762d9a793ec38a2848f5b20a0aab6c0eace31')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El despullament parcial de la persona en una dependència tancada.', false), ('B', 'La palpació de l''esquema corporal de la persona.', true), ('C', 'La inspecció visual del cos de l''intern després de lliurar-li una bata.', false), ('D', 'La realització de proves radiològiques amb el consentiment de l''intern.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, què cal per fer proves radiològiques a un intern quan no les accepta voluntàriament?', 'Segons l''apartat 1.4 de la Circular 1/2008, si l''intern no hi consent, sempre cal que el jutjat de guàrdia autoritzi la proposta motivada de la direcció del centre. La proposta ha d''expressar l''excepcionalitat, la necessitat i la proporcionalitat de la mesura.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.4', 'Pel que fa a les proves radiològiques, excepte en els casos que l’intern ho accepti voluntàriament, sempre és necessari que el jutjat de guàrdia autoritzi la proposta formulada prèviament per la direcció del centre', null, 'ec8526e7067974dad7db0fd4e165d9a0cbe0c547489bb584d9f4e6b15ad64703', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ec8526e7067974dad7db0fd4e165d9a0cbe0c547489bb584d9f4e6b15ad64703')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el jutjat de guàrdia autoritzi la proposta formulada prèviament per la direcció del centre.', true), ('B', 'Que el cap de serveis l''autoritzi per escrit i en doni compte al director.', false), ('C', 'Que el jutge de vigilància penitenciària l''autoritzi a proposta de la junta de tractament.', false), ('D', 'Que el metge del centre l''autoritzi i en doni compte al centre directiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, què passa si una persona autoritzada a comunicar amb un intern es nega a sotmetre''s a l''escorcoll amb nu integral acordat d''acord amb l''article 68 del Reglament penitenciari?', 'L''apartat 2.2 de la Circular 1/2008, d''acord amb l''art. 45.7 RP, disposa que, si el visitant es nega a l''escorcoll, la comunicació no es fa, sens perjudici de les mesures que corresponguin si els fets poden ser constitutius de delicte.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 2.2; art. 45.7 RP', 'En el cas que el visitant es negui a realitzar l’escorcoll, la comunicació no es durà a terme, sense perjudici de les mesures que es puguin adoptar en el cas que els fets puguin ser constitutius de delicte.', null, '709a7c6e0bc1a1a43de9c9f2bb885662a75ab09e3bc200c563554bc864b89f07', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '709a7c6e0bc1a1a43de9c9f2bb885662a75ab09e3bc200c563554bc864b89f07')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La comunicació no es fa, sens perjudici de les mesures que es puguin adoptar si els fets poden ser constitutius de delicte.', true), ('B', 'La comunicació es fa igualment, però en un locutori amb separació física.', false), ('C', 'El cap de serveis l''ha de retenir al centre fins que arribi el jutge de guàrdia.', false), ('D', 'La comunicació es fa, però se suspenen les comunicacions de l''intern durant un mes.', false)) as v(label, body, ok)
)
