insert into public.sources (title, url, kind, publisher, published_on) values ('Circular 1/2022 sobre contencions (mitjans coercitius) als centres penitenciaris de Catalunya', 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular-1-2022-contencions.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament de Justícia', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e14-regim-penitenciari-2-seguretat', 'Tema 14. El règim penitenciari II: seguretat, mitjans coercitius i protocols') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e14-regim-penitenciari-2-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la justificació normativa de la Circular 1/2022, a quines internes NO es poden aplicar mitjans coercitius, llevat dels casos en què se''n pugui derivar un perill imminent per a la integritat de la persona interna o la d''altres persones?', 'La Circular 1/2022 recorda que, segons els arts. 72.2 i 254.3 RP, els mitjans coercitius no s''apliquen als malalts convalescents d''una malaltia greu ni a les dones gestants, a les que van acabar l''embaràs fa menys de sis mesos, a les mares lactants ni a les que tenen fills amb elles. L''excepció és el perill imminent per a la integritat de la persona interna o d''altres persones.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular-1-2022-contencions.pdf'), 'Circular 1/2022, justificació normativa', 'els mitjans coercitius no es poden aplicar als malalts convalescents d’una malaltia greu, a les dones gestants, a les dones l’embaràs de les quals faci menys de sis mesos que hagi acabat, a les mares lactants ni a les que tinguin fills amb elles, llevat dels casos en què pugui derivar un perill imminent per a la integritat de la persona interna o la d’altres persones.', null, '3d73d367ed951edb1f2525ba3d29c1f43f1261d546339e1ea29a26d5aef33b5a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3d73d367ed951edb1f2525ba3d29c1f43f1261d546339e1ea29a26d5aef33b5a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només a les dones gestants i a les que tinguin fills menors de tres anys amb elles.', false), ('B', 'A les dones gestants i a les dones l''embaràs de les quals hagi acabat fa menys d''un any.', false), ('C', 'A totes les internes destinades a unitats de mares, sense cap excepció.', false), ('D', 'A les dones gestants, a les dones l''embaràs de les quals hagi acabat fa menys de sis mesos, a les mares lactants i a les que tinguin fills amb elles.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Circular 1/2022 aprova el protocol d''aplicació dels mitjans coercitius d''aïllament provisional i de contenció mecànica. Quin dels objectius següents s''hi fixa?', 'Els objectius de la Circular 1/2022 són arribar a la contenció zero, preservar els drets i la integritat de la persona interna, protegir la integritat física i jurídica dels professionals i garantir la seguretat i l''ordenada convivència.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular-1-2022-contencions.pdf'), 'Circular 1/2022, objectius', 'Arribar a la contenció zero. - Preservar els drets i la integritat física i psicològica de la persona interna. - Protegir la integritat física i jurídica dels professionals penitenciaris.', null, '9a054da598f45146d75aa2354de40419b889d87a9e563d3d8a894f20d728ff30', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9a054da598f45146d75aa2354de40419b889d87a9e563d3d8a894f20d728ff30')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Substituir l''aïllament provisional per la sanció d''aïllament en cel·la.', false), ('B', 'Generalitzar la contenció mecànica al llit com a primera opció.', false), ('C', 'Arribar a la contenció zero.', true), ('D', 'Traspassar l''aplicació de les contencions al personal sanitari.', false)) as v(label, body, ok)
)
