insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e15-classificacio-regims', 'Tema 15. Classificació en graus i règims ordinari, tancat, obert i de preventius') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e15-classificacio-regims' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 74 del Reglament penitenciari, a qui s''aplica el règim ordinari?', 'L''art. 74.1 RP aplica el règim ordinari als penats de segon grau, als penats sense classificar i als detinguts i presos. El règim obert correspon al tercer grau, i el tancat, al primer grau i als preventius en què concorrin les mateixes circumstàncies.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 74.1 RP', 'El régimen ordinario se aplicará a los penados clasificados en segundo grado, a los penados sin clasificar y a los detenidos y presos.', null, 'c88de6b2c7a194a281f013a0632569fc4351f8f8e3867f5fa57cbe7ed3f86f2b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c88de6b2c7a194a281f013a0632569fc4351f8f8e3867f5fa57cbe7ed3f86f2b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Als penats classificats en segon grau, als penats sense classificar i als detinguts i presos.', true), ('B', 'Només als penats classificats en segon grau.', false), ('C', 'Als penats classificats en segon i tercer grau.', false), ('D', 'Als penats classificats en segon grau i als penats sense classificar, però no als detinguts i presos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 100.2 del Reglament penitenciari (principi de flexibilitat), el model d''execució que combina aspectes característics de diferents graus quina aprovació ulterior necessita?', 'L''equip tècnic pot proposar a la junta de tractament aquest model, fonamentat en un programa específic de tractament. Com a mesura excepcional, necessita l''aprovació ulterior del jutge de vigilància, però s''executa immediatament (art. 100.2 RP).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 100.2 RP', 'Esta medida excepcional necesitará de la ulterior aprobación del Juez de Vigilancia correspondiente, sin perjuicio de su inmediata ejecutividad.', null, '250047fdcf1881144821ee5bb83f7fb9367f1722912a6016acedeb8b7c4e3b5a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '250047fdcf1881144821ee5bb83f7fb9367f1722912a6016acedeb8b7c4e3b5a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La del centre directiu, i no s''executa fins que no l''aprova.', false), ('B', 'La del Ministeri Fiscal, dins dels tres dies hàbils següents.', false), ('C', 'La del consell de direcció, a proposta de la junta de tractament.', false), ('D', 'La del jutge de vigilància, sens perjudici de la seva executivitat immediata.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, dins de quin termini màxim ha de formular la junta de tractament la proposta de classificació inicial d''un penat?', 'La proposta es formula en el model normalitzat del centre directiu en el termini màxim de dos mesos des de la recepció del testimoni de la sentència (art. 103.2 RP). El centre directiu resol en dos mesos més, que pot ampliar dos mesos més (arts. 103.4 i 103.6 RP).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 103.2 RP', 'La propuesta se formulará en el impreso normalizado aprobado por el Centro Directivo en el plazo máximo de dos meses desde la recepción en el Establecimiento del testimonio de la sentencia.', null, 'd6db2e43b7d2b39637bb2caae0e2011670dcba2dfac8c2cabe3f8c07931a9b30', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd6db2e43b7d2b39637bb2caae0e2011670dcba2dfac8c2cabe3f8c07931a9b30')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sis mesos des que l''establiment rep el testimoni de la sentència.', false), ('B', 'Dos mesos des que l''establiment rep el testimoni de la sentència.', true), ('C', 'Un mes des de l''ingrés del penat a l''establiment.', false), ('D', 'Dos mesos des de l''ingrés del penat a l''establiment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 103 del Reglament penitenciari, quan es tracta de penats amb condemnes de fins a un any, quan té la proposta de classificació inicial de la junta de tractament la consideració de resolució de classificació inicial a tots els efectes?', 'Si la condemna és de fins a un any, l''acord unànime de la junta té la consideració de resolució de classificació inicial, llevat que proposi el primer grau, cas en què resol el centre directiu (art. 103.7 RP). Si l''acord no és unànime, també es tramet al centre directiu (art. 103.9 RP).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 103.7 RP', 'Cuando se trate de penados con condenas de hasta un año, la propuesta de clasificación inicial formulada por la Junta de Tratamiento, adoptada por acuerdo unánime de sus miembros, tendrá la consideración de resolución de clasificación inicial a todos los efectos, salvo cuando se haya propuesto la clasificación en primer grado de tratamiento, en cuyo caso la resolución corresponderá al Centro Directivo.', null, 'a9931e774da25b81638c1c85aec1919371ed60310c41f8b5cc838d858a848bc3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a9931e774da25b81638c1c85aec1919371ed60310c41f8b5cc838d858a848bc3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan l''acord s''adopta per unanimitat dels membres i no proposa la classificació en primer grau.', true), ('B', 'Sempre, sigui quin sigui el grau proposat i la majoria amb què s''adopta.', false), ('C', 'Quan l''acord s''adopta per majoria absoluta i proposa el tercer grau.', false), ('D', 'Mai: la resolució correspon sempre al centre directiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
