with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, amb quina periodicitat màxima s''han d''estudiar individualment els interns per reconsiderar la seva classificació?', 'L''art. 105.1 RP, en la mateixa línia que l''art. 65.4 LOGP, obliga a estudiar els interns individualment cada sis mesos com a màxim.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 105.1 RP', 'Cada seis meses como máximo, los internos deberán ser estudiados individualmente para evaluar y reconsiderar, en su caso, todos los aspectos establecidos en el modelo individualizado de tratamiento al formular su propuesta de clasificación inicial.', null, 'abcd6dbe5cee65ea886e243bd77f2158299ed011a2d767d49378bcf6886f6e89', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'abcd6dbe5cee65ea886e243bd77f2158299ed011a2d767d49378bcf6886f6e89')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cada tres mesos com a màxim.', false), ('B', 'Cada any com a màxim.', false), ('C', 'Cada sis mesos com a màxim.', true), ('D', 'Cada dos mesos com a màxim.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 105 del Reglament penitenciari, què pot sol·licitar un intern quan una mateixa junta reitera per segona vegada la seva classificació en primer grau?', 'L''art. 105.3 RP, igual que l''art. 65.4 LOGP, permet a l''intern demanar que la propera proposta la faci la Central Penitenciària d''Observació. El mateix dret correspon a l''intern de segon grau en la mateixa circumstància que ha complert la meitat de la condemna.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 105.3 RP', 'Cuando una misma Junta reitere por segunda vez la clasificación de primer grado, el interno podrá solicitar que su próxima propuesta de clasificación se haga por la Central Penitenciaria de Observación.', null, '768c7600f3b7e4ea5f7c68a48741dcaf512f24f20a266685a94c6f676667903e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '768c7600f3b7e4ea5f7c68a48741dcaf512f24f20a266685a94c6f676667903e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el jutge de vigilància el classifiqui directament en segon grau.', false), ('B', 'Que la seva propera proposta de classificació la faci la Central Penitenciària d''Observació.', true), ('C', 'Que la seva propera proposta de classificació la faci la junta de tractament d''un altre centre de la seva elecció.', false), ('D', 'Que el Ministeri Fiscal revisi la classificació en el termini de tres dies.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
