with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, dins de quin termini s''han de notificar al Ministeri Fiscal les resolucions de classificació o progressió a tercer grau?', 'L''art. 107 RP obliga a notificar al Ministeri Fiscal totes les resolucions de classificació o progressió a tercer grau, amb l''informe de la junta de tractament, dins dels tres dies hàbils següents a la data d''adopció.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 107 RP', 'se notificarán, junto con el informe de la Junta de Tratamiento, al Ministerio Fiscal dentro de los tres días hábiles siguientes a la fecha de su adopción.', null, '36f5e7849a83bd7048f67fb6dfeaaa391f31be95c431cf669b096f47c2bc6485', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '36f5e7849a83bd7048f67fb6dfeaaa391f31be95c431cf669b096f47c2bc6485')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins de les setanta-dues hores següents a l''adopció, sense cap informe.', false), ('B', 'Dins dels deu dies hàbils següents a la data d''adopció.', false), ('C', 'Dins del mes següent a la data d''adopció, juntament amb l''informe del director.', false), ('D', 'Dins dels tres dies hàbils següents a la data d''adopció, juntament amb l''informe de la junta de tractament.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 102.5 del Reglament penitenciari, quin dels factors següents NO s''esmenta entre els que s''han de ponderar per classificar un intern en primer grau?', 'L''art. 102.5 RP enumera la naturalesa dels delictes, els actes especialment violents, la pertinença a organitzacions delictives o bandes armades, la participació en motins, plants, agressions, amenaces o coaccions, les infraccions molt greus o greus reiterades i la introducció o tinença d''armes de foc o de drogues en quantitat important. La durada de la condemna no hi figura.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 102.5 RP', 'c) Pertenencia a organizaciones delictivas o a bandas armadas, mientras no muestren, en ambos casos, signos inequívocos de haberse sustraído a la disciplina interna de dichas organizaciones o bandas. d) Participación activa en motines, plantes, agresiones físicas, amenazas o coacciones. e) Comisión de infracciones disciplinarias calificadas de muy graves o graves, de manera reiterada y sostenida en el tiempo.', null, '14660215aa8afadaecd2a6212087e0efde7361c2acbf2d7659264756fd6ae8b0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '14660215aa8afadaecd2a6212087e0efde7361c2acbf2d7659264756fd6ae8b0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La participació activa en motins, plants, agressions físiques, amenaces o coaccions.', false), ('B', 'La pertinença a organitzacions delictives o a bandes armades, mentre no mostri signes inequívocs d''haver-se sostret a la seva disciplina interna.', false), ('C', 'La comissió d''infraccions disciplinàries qualificades de molt greus o greus, de manera reiterada i sostinguda en el temps.', false), ('D', 'El fet de complir una condemna superior a deu anys de presó.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 93 del Reglament penitenciari, de quantes hores diàries de sortida al pati han de gaudir, com a mínim, els interns destinats a departaments especials?', 'Als departaments especials el mínim és de tres hores diàries de pati, ampliables fins a tres hores més per a activitats programades (art. 93.1.1a RP). Les quatre hores de vida en comú corresponen als mòduls o centres tancats (art. 94 RP).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 93.1 RP, norma 1a', 'Los internos disfrutarán, como mínimo, de tres horas diarias de salida al patio. Este número podrá ampliarse hasta tres horas más para la realización de actividades programadas.', null, '4a4b2bd6c723281dd0bbf113d217ce735b141e91292165d2116c6bbb86a8b93b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4a4b2bd6c723281dd0bbf113d217ce735b141e91292165d2116c6bbb86a8b93b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres hores, ampliables fins a tres hores més per a activitats programades.', true), ('B', 'Quatre hores, ampliables fins a tres hores més per a activitats programades.', false), ('C', 'Dues hores, ampliables fins a dues hores més per a activitats programades.', false), ('D', 'Sis hores, sense possibilitat d''ampliació.', false)) as v(label, body, ok)
)
