with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 93 del Reglament penitenciari, en les sortides al pati dels departaments especials, quants interns hi poden estar junts?', 'Segons la norma 3a de l''art. 93.1 RP, al pati no hi pot haver mai més de dos interns junts, i el nombre es pot augmentar fins a cinc per fer activitats programades.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 93.1 RP, norma 3a', 'En las salidas al patio no podrán permanecer, en ningún caso, más de dos internos juntos. Este número podrá aumentarse hasta un máximo de cinco para la ejecución de actividades programadas.', null, 'fc1e509a4c443e203265254f531b4ca80aca37335d93382d6a47177439f146ed', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fc1e509a4c443e203265254f531b4ca80aca37335d93382d6a47177439f146ed')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No més de cinc, nombre que es pot augmentar fins a un màxim de deu per fer activitats programades.', false), ('B', 'No més de dos, nombre que es pot augmentar fins a un màxim de cinc per fer activitats programades.', true), ('C', 'No més de tres, sense possibilitat d''augmentar-lo.', false), ('D', 'Un de sol, sense cap excepció.', false)) as v(label, body, ok)
)
