with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 94 del Reglament penitenciari, sobre la modalitat de vida en mòduls o centres tancats, assenyaleu la resposta correcta.', 'L''art. 94 RP fixa un mínim de quatre hores diàries de vida en comú, ampliables fins a tres hores més per a activitats programades. El nombre d''interns per a les activitats en grup el fixa el consell de direcció, amb l''informe previ de la junta de tractament, i n''ha de ser com a mínim de cinc.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 94 RP, normes 1a i 2a', 'Los internos disfrutarán, como mínimo, de cuatro horas diarias de vida en común. Este horario podrá aumentarse hasta tres horas más para la realización de actividades previamente programadas.', null, '6af7e9bc3c4957048581a98dbb9a1e4fd3506ce4c50c4bc44fe54da6127c8847', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6af7e9bc3c4957048581a98dbb9a1e4fd3506ce4c50c4bc44fe54da6127c8847')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els interns gaudeixen, com a mínim, de tres hores diàries de vida en comú, ampliables fins a dues hores més.', false), ('B', 'El nombre d''interns que poden fer activitats en grup el fixa el centre directiu, amb un màxim de cinc.', false), ('C', 'Els interns gaudeixen, com a mínim, de quatre hores diàries de vida en comú, ampliables fins a tres hores més per a activitats programades.', true), ('D', 'El nombre d''interns que poden fer activitats en grup el fixa el director, amb un mínim de dos.', false)) as v(label, body, ok)
)
