with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 95 del Reglament penitenciari, dins de quin termini s''ha d''informar el jutge de vigilància penitenciària del trasllat d''un penat a un establiment de règim tancat o a un departament especial?', 'El trasllat l''acorda el centre directiu en resolució motivada, amb la proposta raonada prèvia de la junta de tractament, i se n''informa el jutge de vigilància dins de les 72 hores següents (art. 95.1 RP). Els catorze dies són el termini per resoldre la classificació en primer grau en els trasllats per motí, agressió amb arma, presa d''ostatges o intent violent d''evasió (art. 95.3 RP).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 95.1 RP', 'De este acuerdo se dará conocimiento al Juez de Vigilancia Penitenciaria dentro de las setenta y dos horas siguientes a su adopción.', null, 'c0aff37cd83df611bd52b72efdffb21096384311e2de7b2127e67e04056be5b1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c0aff37cd83df611bd52b72efdffb21096384311e2de7b2127e67e04056be5b1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins de les vint-i-quatre hores següents a l''adopció de l''acord.', false), ('B', 'Dins de les setanta-dues hores següents a l''adopció de l''acord.', true), ('C', 'Dins dels catorze dies següents a l''adopció de l''acord.', false), ('D', 'Dins dels tres dies hàbils següents a l''adopció de l''acord.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
