with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 80 del Reglament penitenciari, quin dels següents NO és un tipus d''establiment de règim obert?', 'L''art. 80.1 RP enumera tres tipus d''establiments de règim obert: els centres oberts o d''inserció social, les seccions obertes i les unitats dependents. Els departaments especials són una modalitat del règim tancat (art. 91 RP).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 80.1 RP', 'a) Centros Abiertos o de Inserción Social. b) Secciones Abiertas. c) Unidades Dependientes.', null, '881dda000a129eb075f0ba7ce4e8f331566864d55cd5bf40ca9659bb8d18c625', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '881dda000a129eb075f0ba7ce4e8f331566864d55cd5bf40ca9659bb8d18c625')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els centres oberts o d''inserció social.', false), ('B', 'Les seccions obertes.', false), ('C', 'Els departaments especials.', true), ('D', 'Les unitats dependents.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 86 del Reglament penitenciari, quin és en general el temps mínim de permanència al centre dels interns en règim obert i quina excepció hi ha?', 'L''art. 86.4 RP fixa, en general, vuit hores diàries de permanència i la pernoctació al centre. Si l''intern accepta voluntàriament el control telemàtic o un altre de suficient, només hi ha d''estar el temps que fixi el seu programa de tractament.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 86.4 RP', 'En general, el tiempo mínimo de permanencia en el Centro será de ocho horas diarias, debiendo pernoctarse en el Establecimiento, salvo cuando, de modo voluntario, el interno acepte el control de su presencia fuera del Centro mediante dispositivos telemáticos adecuados proporcionados por la Administración Penitenciaria u otros mecanismos de control suficiente', null, '388f1d9f0a9215f37aaa6d06fc82a9f3fb56aa851e40fd5dd5bc37a97a7b2b7d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '388f1d9f0a9215f37aaa6d06fc82a9f3fb56aa851e40fd5dd5bc37a97a7b2b7d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sis hores diàries, sense pernoctació, llevat que la junta de tractament imposi el control telemàtic.', false), ('B', 'Vuit hores diàries, amb pernoctació al centre, sense cap excepció.', false), ('C', 'Vuit hores diàries, amb pernoctació al centre, llevat que l''intern accepti voluntàriament el control de la seva presència fora del centre mitjançant dispositius telemàtics o altres mecanismes de control suficient.', true), ('D', 'Dotze hores diàries, amb pernoctació, llevat que el jutge de vigilància autoritzi el control telemàtic.', false)) as v(label, body, ok)
)
