with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre les normes de funcionament de les unitats de mares de l''article 178 del Reglament penitenciari, quina de les afirmacions següents NO és correcta?', 'Segons la norma 1a de l''art. 178 RP, qui programa les activitats formatives i lúdiques i les sortides programades dels menors a l''exterior és la junta de tractament, no el consell de direcció. Les altres afirmacions reprodueixen les normes 2a, 3a i 5a.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 178 RP', 'La Junta de Tratamiento programará las actividades formativas y lúdicas, así como las salidas programadas al exterior de los menores', null, '83fe0cc5b4acb4d70403bfdfcc7ff70f44cddee424724a98705c9f1152692a1b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '83fe0cc5b4acb4d70403bfdfcc7ff70f44cddee424724a98705c9f1152692a1b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Hi ha d''haver un especialista d''educació infantil que orienti la programació educativa i lúdica de les activitats dels menors.', false), ('B', 'Un especialista en pediatria ha de cobrir l''assistència mèdica dels menors a l''establiment.', false), ('C', 'El règim de visites del menor només es pot restringir de manera transitòria per raons d''ordre i de seguretat de l''establiment.', false), ('D', 'El consell de direcció programa les activitats formatives i lúdiques i les sortides programades dels menors a l''exterior.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
