  select 'D''acord amb el Decret 329/2006, els equips multidisciplinaris són:', 'L''art. 36 del Decret 329/2006 defineix els equips multidisciplinaris com les unitats d''estudi, proposta i execució de la junta de tractament, encarregades de proposar i executar els programes de tractament o els models individualitzats d''intervenció.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 36 D329', 'Els equips multidisciplinaris seran les unitats d''estudi, proposta i execució amb que comptarà la Junta de Tractament.', null, '48cfe5cca878783dfd4e6fb4a3fbdbbda9ab9c172c6cef8b34eb0820b167b261', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '48cfe5cca878783dfd4e6fb4a3fbdbbda9ab9c172c6cef8b34eb0820b167b261')
