with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, sota la direcció de quin òrgan actua l''equip multidisciplinari dels centres penitenciaris?', 'L''art. 37.1 del Decret 329/2006 estableix que a cada centre hi ha, almenys, un equip multidisciplinari, que actua sota la direcció del/de la subdirector/a de Tractament.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 37.1 D329', 'En els centres penitenciaris hi haurà, almenys, un equip multidisciplinari. L''equip multidisciplinari actuarà sota la direcció del/de la subdirector/a de Tractament.', null, '3cc4a865202ca4a019ed9c93af538a712fa757e92c6cc4328cecd2db51d6beae', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3cc4a865202ca4a019ed9c93af538a712fa757e92c6cc4328cecd2db51d6beae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del/de la director/a del centre penitenciari.', false), ('B', 'Del/de la gerent del centre penitenciari.', false), ('C', 'Del/de la subdirector/a de Tractament.', true), ('D', 'Del/de la cap de serveis.', false)) as v(label, body, ok)
)
