with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 37.2 del Decret 329/2006, quin dels professionals següents NO figura entre els que formen part de l''equip multidisciplinari?', 'L''art. 37.2 enumera el coordinador o cap de programes, psicòleg, jurista, educador, docent, metge, treballador social, monitor ocupacional o insertor laboral, monitor esportiu i cap d''unitat o coordinador d''unitat especialitzada. El director no en forma part.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 37.2 D329', '2. Formaran part de l''equip multidisciplinari: a) El/La coordinador/a dels equips multidisciplinaris, si n''hi ha, o el/la cap de programes d''atenció especialitzada. b) El/La psicòleg/oga adscrit/a a l''equip. c) El/La jurista adscrit/a a l''equip. d) L''educador/a adscrit/a a l''equip. e) Un/a docent. f) Un/a metge/essa. g) Un/a treballador/a social. h) Un/a monitor/a ocupacional i/o insertor/a laboral. i) Un/a monitor/a esportiu/iva. j) El/La cap d''unitat o el/la coordinador/a d''unitat especialitzada.', null, '2e76eecbcc39412b61c8964718218d96536b99ea454281d8626219c535b07a4a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2e76eecbcc39412b61c8964718218d96536b99ea454281d8626219c535b07a4a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El/La jurista adscrit/a a l''equip.', false), ('B', 'Un/a monitor/a esportiu/iva.', false), ('C', 'El/La cap d''unitat o el/la coordinador/a d''unitat especialitzada.', false), ('D', 'El/La director/a del centre penitenciari.', true)) as v(label, body, ok)
)
