  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, els professionals de les entitats col·laboradores i els membres de les associacions de voluntariat que fan directament programes de tractament amb els interns:', 'L''art. 37.4 del Decret 329/2006 permet l''assistència d''aquests professionals i voluntaris amb veu però sense vot, amb la sol·licitud i l''aprovació prèvia del Consell de Direcció.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 37.4 D329', 'A les reunions de l''equip multidisciplinari hi podran assistir, amb la sol·licitud i aprovació prèvia del Consell de Direcció, amb veu però sense vot, els professionals de les entitats col·laboradores i els membres de les associacions de voluntariat', null, '4c325dfa887d86d30cc860dd4bd00946f894ec9f97339ef37127718dc8da63e0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4c325dfa887d86d30cc860dd4bd00946f894ec9f97339ef37127718dc8da63e0')
  returning id
), o as (
