  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Poden assistir a les reunions de l''equip multidisciplinari, amb veu i vot, amb l''autorització del/de la director/a.', false), ('B', 'Poden assistir a les reunions de l''equip multidisciplinari, amb veu però sense vot, amb la sol·licitud i l''aprovació prèvia del Consell de Direcció.', true), ('C', 'Formen part de l''equip multidisciplinari com a membres de ple dret.', false), ('D', 'No poden assistir en cap cas a les reunions de l''equip multidisciplinari.', false)) as v(label, body, ok)
)
