)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, qui proposa les sortides programades?', 'Segons l''art. 114.4 RP, les sortides programades les proposa la junta de tractament, que demana l''aprovació del centre directiu i l''autorització posterior del jutge de vigilància quan, per la durada i el grau, sigui competent.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 114.4 RP', 'Las salidas programadas serán propuestas por la Junta de Tratamiento, que solicitará la aprobación del Centro Directivo y la posterior autorización del Juez de Vigilancia', null, 'ef7c478759324c2e9a7db59312445e2d5ec16851935cb5a6072e8eed16a8de3c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ef7c478759324c2e9a7db59312445e2d5ec16851935cb5a6072e8eed16a8de3c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El/La director/a del centre, que les aprova directament sense cap altra autorització.', false), ('B', 'La junta de tractament, que sol·licita l''aprovació del centre directiu i, si escau, l''autorització posterior del jutge de vigilància penitenciària.', true), ('C', 'L''equip tècnic, que en sol·licita l''autorització directament al jutge de vigilància penitenciària.', false), ('D', 'El Consell de Direcció, que en sol·licita l''aprovació a la Comissió Disciplinària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, els permisos de sortida ordinaris es poden concedir als penats classificats en segon o tercer grau amb una durada de fins a:', 'L''art. 154.1 RP (i l''art. 47.2 LOGP) preveu permisos ordinaris de fins a set dies, amb un total de 36 dies l''any (segon grau) o 48 (tercer grau), si s''ha extingit la quarta part de la condemna i no s''observa mala conducta.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 154.1 RP', 'permisos de salida ordinarios de hasta siete días de duración como preparación para la vida en libertad, hasta un total de treinta y seis o cuarenta y ocho días por año a los condenados clasificados en segundo o tercer grado respectivamente, siempre que hayan extinguido la cuarta parte de la condena o condenas y no observen mala conducta.', null, 'c27b9349a2a1e42a012cf6b5a2c91f8b03a4ee18db1038ad24f0b95384155f32', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c27b9349a2a1e42a012cf6b5a2c91f8b03a4ee18db1038ad24f0b95384155f32')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinc dies cadascun, amb un màxim de trenta o quaranta dies l''any, respectivament.', false), ('B', 'Set dies cadascun, amb un màxim de quaranta-vuit dies l''any en tots dos graus.', false), ('C', 'Deu dies cadascun, amb un màxim de trenta-sis o quaranta-vuit dies l''any, respectivament.', false), ('D', 'Set dies cadascun, amb un màxim de trenta-sis o quaranta-vuit dies l''any, respectivament.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, com es distribueixen, com a regla general, els límits màxims anuals de permisos ordinaris?', 'L''art. 154.2 RP distribueix els límits de 36 i 48 dies en els dos semestres naturals, amb fins a 18 i 24 dies per semestre, respectivament.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 154.2 RP', 'Los límites máximos anuales de treinta y seis y cuarenta y ocho días de permisos antes señalados, se distribuirán, como regla general, en los dos semestres naturales de cada año, concediendo en cada uno de ellos hasta dieciocho y veinticuatro días, respectivamente.', null, '595d1ab1b00635aa95bb8e0b957ffe4eadbe9928ea14f6d95b4f982e751cb545', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '595d1ab1b00635aa95bb8e0b957ffe4eadbe9928ea14f6d95b4f982e751cb545')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En els quatre trimestres naturals de cada any, fins a nou dies per trimestre en segon grau i fins a dotze en tercer grau.', false), ('B', 'En els dos semestres naturals de cada any, fins a vint-i-quatre dies per semestre en segon grau i fins a trenta-sis en tercer grau.', false), ('C', 'En els dos semestres naturals de cada any, fins a divuit dies per semestre en segon grau i fins a vint-i-quatre en tercer grau.', true), ('D', 'Lliurement al llarg de l''any, sense cap distribució per períodes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, quina és la durada màxima dels permisos extraordinaris de sortida per a consulta ambulatòria extrapenitenciària dels penats classificats en segon o tercer grau?', 'L''art. 155.4 RP permet permisos extraordinaris de fins a dotze hores per a consulta ambulatòria extrapenitenciària i de fins a dos dies quan s''hagi d''ingressar en un hospital extrapenitenciari.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 155.4 RP', 'permisos extraordinarios de salida de hasta doce horas de duración para consulta ambulatoria extrapenitenciaria de los penados clasificados en segundo o tercer grado', null, 'e74d1893e1ee746ff8778d9dc6579d336616301e2073f1011c6dfa88e107d3b9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e74d1893e1ee746ff8778d9dc6579d336616301e2073f1011c6dfa88e107d3b9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dotze hores.', true), ('B', 'Vint-i-quatre hores.', false), ('C', 'Dos dies.', false), ('D', 'Sis hores.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, si la junta de tractament acorda concedir un permís de sortida, a qui ha d''elevar l''acord per a l''autorització corresponent?', 'L''art. 161.1 RP diu que l''acord s''eleva, amb l''informe de l''equip tècnic, al jutge de vigilància (segon grau) o al centre directiu (tercer grau). Els permisos ordinaris de fins a dos dies els autoritza el centre directiu (art. 161.2).', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 161.1 RP', 'elevará dicho acuerdo, junto con el informe del Equipo Técnico, al Juez de Vigilancia o al Centro Directivo, según se trate de internos clasificados en segundo o tercer grado de tratamiento, respectivamente, para la autorización correspondiente.', null, '2e49572e13eec00ae30deac372867dd425d5f5397a00db9d10b78262b2a7c3eb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2e49572e13eec00ae30deac372867dd425d5f5397a00db9d10b78262b2a7c3eb')
  returning id
), o as (
