with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, quin òrgan del centre penitenciari imposa les sancions per les infraccions lleus comeses pels interns?', 'L''art. 12.2.h del Decret 329/2006 atribueix al director la imposició de sancions per infraccions lleus, amb instrucció prèvia d''un procediment abreujat. Les infraccions greus i molt greus les resol la Comissió Disciplinària (art. 35.2.a).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 12.2.h D329', 'imposar les sancions per les infraccions lleus comeses pels/per les interns/es, amb la instrucció prèvia d''un procediment abreujat.', null, '674b7dddd8bbe4d9954810bf53d81f3c8ef26a86da42d9358e9824ca5ba007aa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '674b7dddd8bbe4d9954810bf53d81f3c8ef26a86da42d9358e9824ca5ba007aa')
  returning id
), o as (
