insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e17-regim-disciplinari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 41 de la Llei orgànica 1/1979, general penitenciària (LOGP), el règim disciplinari dels establiments s''adreça a:', 'L''art. 41.1 LOGP fixa com a fonament del règim disciplinari garantir la seguretat i aconseguir una convivència ordenada; la reeducació i la reinserció són la finalitat del tractament (art. 59 LOGP).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 41.1 LOGP', 'El régimen disciplinario de los establecimientos se dirigirá a garantizar la seguridad y conseguir una convivencia ordenada.', null, '76bf59107610ff6c97a8e9c93741df3b4859f0d8f644bc567abb07bd9d0491b3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '76bf59107610ff6c97a8e9c93741df3b4859f0d8f644bc567abb07bd9d0491b3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Aconseguir la reeducació i la reinserció social dels penats.', false), ('B', 'Estimular la participació de l''intern en el seu tractament.', false), ('C', 'Assegurar la custòdia dels interns a disposició de l''autoritat judicial.', false), ('D', 'Garantir la seguretat i aconseguir una convivència ordenada.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la LOGP, com es classifiquen les infraccions disciplinàries dels interns?', 'L''art. 42.1 LOGP classifica les infraccions disciplinàries en faltes molt greus, greus i lleus, tipificades als arts. 108, 109 i 110 del Reglament penitenciari de 1981.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 42.1 LOGP', 'Las infracciones disciplinarias se clasificarán en faltas muy graves, graves y leves.', null, 'dee6ce2db71a3361fa1848989c9bc093763809e9c15c444c142f45f5d443826b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dee6ce2db71a3361fa1848989c9bc093763809e9c15c444c142f45f5d443826b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En faltes greus i lleus.', false), ('B', 'En faltes molt greus, greus, lleus i molt lleus.', false), ('C', 'En faltes molt greus, greus i lleus.', true), ('D', 'En faltes d''indisciplina greu i faltes de règim ordinari.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
