insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e17-regim-disciplinari', 'Tema 17. El règim disciplinari dels interns') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e17-regim-disciplinari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari (RP), el règim disciplinari s''aplica als interns:', 'L''art. 231.2 RP aplica el règim disciplinari a tots els interns (amb l''excepció de l''art. 188.4), sigui quina sigui la seva situació processal i penitenciària, dins dels centres i durant trasllats, conduccions o sortides autoritzades.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 231.2 RP', 'El régimen disciplinario se aplicará a todos los internos, con la excepción establecida en el artículo 188.4 de este Reglamento, con independencia de su situación procesal y penitenciaria, tanto dentro de los Centros penitenciarios como durante los traslados, conducciones o salidas autorizadas que se realicen.', null, 'd65d394a3417b8bd23c7fbca47cc48fcae1e0f38588ff42a66a157819b2af670', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd65d394a3417b8bd23c7fbca47cc48fcae1e0f38588ff42a66a157819b2af670')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només als penats, i únicament dins del recinte del centre penitenciari.', false), ('B', 'Amb independència de la seva situació processal i penitenciària, tant dins dels centres com durant els trasllats, les conduccions o les sortides autoritzades.', true), ('C', 'Només als interns classificats en primer i segon grau.', false), ('D', 'Dins dels centres penitenciaris, però no durant les sortides autoritzades, en què s''aplica la legislació penal comuna.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, per la comissió de faltes molt greus es pot imposar la sanció d''aïllament en cel·la amb una durada de:', 'L''art. 233.1.a RP preveu per a les faltes molt greus l''aïllament en cel·la de sis a catorze dies (si hi ha evident agressivitat o violència o alteració reiterada i greu de la convivència) o l''aïllament de fins a set caps de setmana.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 233.1.a RP', 'a) Sanción de aislamiento en celda de seis a catorce días de duración', null, 'bcef40cde699738370e07e1a2657bc893082cd9162a8e65663ffae7aa2123130', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bcef40cde699738370e07e1a2657bc893082cd9162a8e65663ffae7aa2123130')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un a cinc dies.', false), ('B', 'Tres a set dies.', false), ('C', 'Catorze a quaranta-dos dies.', false), ('D', 'Sis a catorze dies.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, amb quines sancions es poden corregir les faltes lleus?', 'L''art. 233.3 RP limita la correcció de les faltes lleus a la privació de passeigs i actes recreatius comuns de fins a tres dies i a l''amonestació.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 233.3 RP', 'Las faltas leves tipificadas en el artículo 110 del Reglamento Penitenciario aprobado por el Real Decreto 1201/1981, de 8 de mayo, sólo podrán corregirse con privación de paseos y actos recreativos comunes de hasta tres días de duración y con amonestación.', null, 'f2b82aac3196045e159dd6152c4ed5707834f545eba06b6a3e3d0d9cec1ec7a8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f2b82aac3196045e159dd6152c4ed5707834f545eba06b6a3e3d0d9cec1ec7a8')
  returning id
), o as (
