select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
-- Lote pcat-e17-regim-disciplinari-rp81-v1 (2 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 1201/1981, de 8 de mayo, Reglamento Penitenciario (artículos vigentes) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e17-regim-disciplinari', 'Tema 17. El règim disciplinari dels interns') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e17-regim-disciplinari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari de 1981 (RP 1981), quina de les conductes següents NO està tipificada com a falta molt greu?', 'L''evasió (108.e), l''agressió o coacció greu a altres interns (108.c) i la participació en motins (108.a) són faltes molt greus. La desobediència o la resistència passiva a les ordres és falta greu (art. 109.b RP 1981).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 108 RP 1981', 'Son faltas muy graves: a) Participar en motines, plantes o desórdenes colectivos, o instigar a los mismos si éstos se hubieran producido. […] c) Agredir o hacer objeto de coacción grave a otros internos. […] e) Intentar, facilitar o consumar la evasión.', null, '452945fe282216ca8f057b2f691bae2907ee13df16fac06c4e9b665531c714f5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '452945fe282216ca8f057b2f691bae2907ee13df16fac06c4e9b665531c714f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Intentar, facilitar o consumar l''evasió.', false), ('B', 'Agredir o fer objecte de coacció greu altres interns.', false), ('C', 'Desobeir les ordres rebudes d''autoritats o funcionaris en l''exercici legítim de les seves atribucions o resistir-s''hi passivament.', true), ('D', 'Participar en motins, plantades o desordres col·lectius, o instigar-hi si s''han produït.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el RP 1981, introduir, fer sortir o posseir en l''establiment objectes prohibits per les normes de règim interior constitueix:', 'L''art. 109.f RP 1981 tipifica com a falta greu introduir, fer sortir o posseir objectes prohibits per les normes de règim interior.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 109.f RP 1981', 'Son faltas graves: […] f) Introducir, hacer salir o poseer en el establecimiento objetos que se hallaren prohibidos por las normas de régimen interior.', null, '3973f60ae876fb123413b207f8c25a6503d066824e9429e30a435057bf70cf62', false
