  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, el personal de l''àmbit administratiu adscrit a les unitats de gestió administrativa actua sota la dependència directa i immediata:', 'L''art. 54.1 del Decret 329/2006 diu que el personal de l''àmbit administratiu actua sota la dependència directa i immediata del responsable de la unitat i, en tot cas, del gerent.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 54.1 D329', 'actuarà sota la dependència directa i immediata de la persona responsable de la unitat i, en tot cas, del/de la gerent.', null, 'ef760f7a4686340298573efb782b25a18c0c011bb3336a995a10bf1a7b903443', false
