with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 53 del Decret 329/2006, quina de les tasques següents NO correspon al personal de l''àmbit administratiu dels centres penitenciaris?', 'L''art. 53 atribueix a l''àmbit administratiu la gestió i tramitació dels expedients d''ingrés, conducció, trasllat i llibertat (a), de permisos, classificacions i llibertat condicional (b) i de peticions, queixes i recursos (c). Elaborar el programa de tractament correspon als equips multidisciplinaris (art. 38.1.a).', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 53 D329', 'a) Gestionar i tramitar els expedients d''ingrés, de conducció, de trasllat i de llibertat dels/de les interns/es en centres penitenciaris […] b) Gestionar i tramitar els expedients relatius als permisos, a les classificacions en graus de tractament penitenciari, a la llibertat condicional […] c) Gestionar i tramitar els expedients relatius a les peticions, les queixes i els recursos que formulin els/les interns/es.', null, '50318eb8540895e2452a7aae44ac2d03a4869bb4cdc797f10d23c2210a37ae4a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '50318eb8540895e2452a7aae44ac2d03a4869bb4cdc797f10d23c2210a37ae4a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Gestionar i tramitar els expedients d''ingrés, de conducció, de trasllat i de llibertat dels interns.', false), ('B', 'Gestionar i tramitar els expedients relatius a les peticions, les queixes i els recursos que formulin els interns.', false), ('C', 'Elaborar el programa de tractament o el model d''intervenció individual dels interns.', true), ('D', 'Gestionar i tramitar els expedients relatius als permisos, a les classificacions en graus i a la llibertat condicional.', false)) as v(label, body, ok)
)
