with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, quin càrrec ha d''establir els procediments i organitzar la recollida, la custòdia i el dipòsit dels diners i dels efectes personals que els interns no poden conservar durant la seva estada a l''establiment?', 'L''art. 57.2.j del Decret 329/2006 atribueix aquesta funció al cap de la unitat de gestió econòmica, que també fa les transferències de saldos del peculi (57.2.h).', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 57.2.j D329', 'j) Establir els procediments i organitzar la recollida, custòdia i dipòsit dels diners i dels efectes personals dels/de les interns/es que, d''acord amb la normativa, no puguin conservar amb ells/elles durant la seva estada a l''establiment.', null, '1c321db4b687f0ad896914e395b2d86f24f73412d58ff6725b570f6b3901699d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1c321db4b687f0ad896914e395b2d86f24f73412d58ff6725b570f6b3901699d')
