with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, quina de les funcions següents NO correspon al/a la cap de la unitat de recursos humans?', 'L''art. 56.2 atribueix al cap de recursos humans, entre d''altres, la formació del personal (f), la prevenció de riscos laborals (h) i les sol·licituds i queixes dels empleats (e). Les transferències de saldos del peculi corresponen al cap de gestió econòmica (art. 57.2.h).', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 56.2 i 57.2.h D329', 'e) Atendre i resoldre, en el seu cas, les sol·licituds i les queixes que formulin els/les empleats/ades de l''establiment en relació amb matèries pròpies de la seva àrea de gestió. f) Promoure i coordinar les activitats formatives del personal de l''establiment […] h) Promoure i coordinar l''aplicació de les mesures de prevenció de riscos laborals […] h) Fer les transferències de saldos del peculi en els supòsits establerts.', null, 'a4039f95cb55eb0d0296ebdb9f43366bf53c041b38f628c131c10a9ace076487', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a4039f95cb55eb0d0296ebdb9f43366bf53c041b38f628c131c10a9ace076487')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Promoure i coordinar les activitats formatives del personal de l''establiment.', false), ('B', 'Fer les transferències de saldos del peculi en els supòsits establerts.', true), ('C', 'Promoure i coordinar l''aplicació de les mesures de prevenció de riscos laborals.', false), ('D', 'Atendre i resoldre, si escau, les sol·licituds i les queixes que formulin els empleats de l''establiment en matèries pròpies de la seva àrea.', false)) as v(label, body, ok)
)
