insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 1/1979, de 26 de septiembre, General Penitenciaria (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e18-gestio-administrativa', 'Tema 18. Gestió administrativa i documental dels establiments penitenciaris') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e18-gestio-administrativa' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei orgànica 1/1979, general penitenciària (LOGP), un cop admès un intern en l''establiment, s''ha d''obrir:', 'L''art. 15 bis.1 LOGP preveu la ressenya alfabètica, dactilar i fotogràfica, la inscripció al llibre d''ingressos i l''obertura d''un expedient personal relatiu a la situació processal i penitenciària, amb dret d''accés de l''intern.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 15 bis.1 LOGP', 'así como a la inscripción en el libro de ingresos y a la apertura de un expediente personal relativo a su situación procesal y penitenciaria, respecto del que se reconoce el derecho de acceso.', null, 'cb102f57e04d8a917037c1c43e6017e920e1d33f02a36c90ebc43d5bd1864f50', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cb102f57e04d8a917037c1c43e6017e920e1d33f02a36c90ebc43d5bd1864f50')
  returning id
