with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei orgànica 3/2018, de protecció de dades personals i garantia dels drets digitals, els tractaments de dades realitzats en l''àmbit de les institucions penitenciàries:', 'L''art. 2.3 de la LO 3/2018 inclou expressament els tractaments en l''àmbit d''institucions penitenciàries entre els que es regeixen per la legislació específica i, supletòriament, pel RGPD i per la LO 3/2018.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'Art. 2.3 LO 3/2018', 'se regirán por lo dispuesto en su legislación específica si la hubiere y supletoriamente por lo establecido en el citado reglamento y en la presente ley orgánica. Se encuentran en esta situación, entre otros, los tratamientos realizados al amparo de la legislación orgánica del régimen electoral general, los tratamientos realizados en el ámbito de instituciones penitenciarias', null, 'b9e5567be856da37d1039e63408ad6ca5adfb21015c0d8723f0bc52975541b5d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b9e5567be856da37d1039e63408ad6ca5adfb21015c0d8723f0bc52975541b5d')
