with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, de règim jurídic i de procediment de les administracions públiques de Catalunya, l''òrgan superior jeràrquic pot emetre instruccions i circulars o ordres de servei per fixar, respectivament:', 'L''art. 7.1 de la Llei 26/2010 distingeix: les instruccions fixen criteris per aplicar les normes jurídiques i les circulars o ordres de servei regulen el funcionament dels serveis. No són disposicions reglamentàries (art. 60.2).', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 7.1 Llei 26/2010', 'que puede emitir instrucciones y circulares u órdenes de servicios para fijar, respectivamente, los criterios para la aplicación de las normas jurídicas en el ejercicio de sus funciones y para el funcionamiento de los servicios.', null, '2aad55aeb7977075fc3b6f3af96ab58e901e3d7205c8113abd8bff9362370b65', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2aad55aeb7977075fc3b6f3af96ab58e901e3d7205c8113abd8bff9362370b65')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El funcionament dels serveis i els criteris per a l''aplicació de les normes jurídiques.', false), ('B', 'Normes que innoven l''ordenament jurídic i el règim disciplinari del personal.', false), ('C', 'Els criteris per a l''aplicació de les normes jurídiques en l''exercici de les funcions i el funcionament dels serveis.', true), ('D', 'La delegació de competències i l''avocació d''assumptes.', false)) as v(label, body, ok)
)
