with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, què s''entén per organització criminal?', 'L''art. 570 bis.1 CP defineix l''organització criminal per tres notes: més de dues persones, estabilitat o durada indefinida, i repartiment concertat i coordinat de tasques per cometre delictes. Si hi falta alguna d''aquestes característiques, es tracta d''un grup criminal (art. 570 ter).', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 bis.1 CP', 'A los efectos de este Código se entiende por organización criminal la agrupación formada por más de dos personas con carácter estable o por tiempo indefinido, que de manera concertada y coordinada se repartan diversas tareas o funciones con el fin de cometer delitos.', null, '6163c44b3188438d0accb3ba2fa64388df1e0077c8bc007d09a0a667789284c2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6163c44b3188438d0accb3ba2fa64388df1e0077c8bc007d09a0a667789284c2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La unió de més de dues persones que, sense caràcter estable ni repartiment de tasques, té per finalitat la perpetració concertada de delictes.', false), ('B', 'L''agrupació formada per dues o més persones que cometen conjuntament un delicte greu, encara que sigui de manera ocasional.', false), ('C', 'L''agrupació formada per més de dues persones amb caràcter estable o per temps indefinit que, de manera concertada i coordinada, es reparteixen diverses tasques o funcions amb la finalitat de cometre delictes.', true), ('D', 'L''agrupació formada per més de cinc persones, amb una estructura jerarquitzada, dedicada a obtenir beneficis econòmics il·lícits.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 570 bis del Codi penal, qui promogui, constitueixi, organitzi, coordini o dirigeixi una organització criminal que tingui per finalitat la comissió de delictes greus serà castigat amb la pena de presó de:', 'Per als promotors i dirigents, l''art. 570 bis.1 CP preveu presó de quatre a vuit anys si l''organització té per finalitat cometre delictes greus i de tres a sis anys en els altres casos.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 bis.1 CP', 'Quienes promovieren, constituyeren, organizaren, coordinaren o dirigieren una organización criminal serán castigados con la pena de prisión de cuatro a ocho años si aquélla tuviere por finalidad u objeto la comisión de delitos graves', null, '179294d8cc142c9dadf51679eed59724888fa62ed5a96cda833a2b4ea3886fb4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '179294d8cc142c9dadf51679eed59724888fa62ed5a96cda833a2b4ea3886fb4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quatre a vuit anys.', true), ('B', 'Tres a sis anys.', false), ('C', 'Dos a cinc anys.', false), ('D', 'Vuit a quinze anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 570 bis del Codi penal, qui participi activament en una organització criminal, en formi part o hi cooperi econòmicament, si l''organització té com a fi la comissió de delictes greus, serà castigat amb la pena de presó de:', 'Per als membres i col·laboradors, l''art. 570 bis.1 CP fixa presó de dos a cinc anys si l''organització té com a fi cometre delictes greus i d''un a tres anys en els altres casos.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 bis.1 CP', 'y quienes participaren activamente en la organización, formaren parte de ella o cooperaren económicamente o de cualquier otro modo con la misma serán castigados con las penas de prisión de dos a cinco años si tuviere como fin la comisión de delitos graves, y con la pena de prisión de uno a tres años en los demás casos.', null, 'e1e7226f8dc70636c0c476bd7d59ca1179a98cf15c0d1ff47c818b09aaef7add', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e1e7226f8dc70636c0c476bd7d59ca1179a98cf15c0d1ff47c818b09aaef7add')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un a tres anys.', false), ('B', 'Quatre a vuit anys.', false), ('C', 'Sis mesos a dos anys.', false), ('D', 'Dos a cinc anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, s''entén per grup criminal:', 'L''art. 570 ter.1 CP defineix el grup criminal per exclusió: més de dues persones que, sense reunir alguna o algunes de les característiques de l''organització criminal, tenen per finalitat la perpetració concertada de delictes.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 ter.1 CP', 'A los efectos de este Código se entiende por grupo criminal la unión de más de dos personas que, sin reunir alguna o algunas de las características de la organización criminal definida en el artículo anterior, tenga por finalidad o por objeto la perpetración concertada de delitos.', null, '59b5386b8a352b37602844513b5e38e0afcadf25b4babe4862b14f0566397a83', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '59b5386b8a352b37602844513b5e38e0afcadf25b4babe4862b14f0566397a83')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''agrupació de més de dues persones amb caràcter estable que es reparteixen tasques per cometre delictes.', false), ('B', 'La unió de més de dues persones que, sense reunir alguna o algunes de les característiques de l''organització criminal, té per finalitat o objecte la perpetració concertada de delictes.', true), ('C', 'Qualsevol unió de dues persones que cometin un delicte en coautoria.', false), ('D', 'L''agrupació que té per finalitat la comissió de delictes de terrorisme.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 570 bis.2 del Codi penal, quina de les circumstàncies següents NO determina que les penes de l''organització criminal s''imposin en la meitat superior?', 'L''art. 570 bis.2 CP preveu tres circumstàncies agreujants (nombre elevat de persones, armes o instruments perillosos i mitjans tecnològics avançats); si en concorren dues o més, s''imposen les penes superiors en grau. Que l''organització actuï des de l''estranger no és cap agreujant (l''art. 570 quater.3 només n''estableix l''aplicabilitat si actua a Espanya).', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 bis.2 CP', 'a) esté formada por un elevado número de personas. b) disponga de armas o instrumentos peligrosos. c) disponga de medios tecnológicos avanzados de comunicación o transporte que por sus características resulten especialmente aptos para facilitar la ejecución de los delitos o la impunidad de los culpables.', null, '16c8f7b79e4bd884fdf97882087639202eaced4f9aedfeda9ea1a79f1b57dc0e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '16c8f7b79e4bd884fdf97882087639202eaced4f9aedfeda9ea1a79f1b57dc0e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que l''organització estigui formada per un nombre elevat de persones.', false), ('B', 'Que tingui la seu o desenvolupi la seva activitat a l''estranger.', true), ('C', 'Que disposi d''armes o instruments perillosos.', false), ('D', 'Que disposi de mitjans tecnològics avançats de comunicació o transport especialment aptes per facilitar l''execució dels delictes o la impunitat dels culpables.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 579 bis del Codi penal, al condemnat a pena greu privativa de llibertat per un o més delictes de terrorisme se li imposarà, a més, la mesura de llibertat vigilada de:', 'L''art. 579 bis.2 CP imposa la llibertat vigilada de cinc a deu anys si la pena privativa de llibertat és greu, i d''un a cinc anys si és menys greu.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 579 bis.2 CP', 'Al condenado a pena grave privativa de libertad por uno o más delitos comprendidos en este Capítulo se le impondrá además la medida de libertad vigilada de cinco a diez años, y de uno a cinco años si la pena privativa de libertad fuera menos grave.', null, '5c6176fbc2d0e68d425dc77ae674a78bcb0cf5efd6634858c0b2408c0f336ccc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5c6176fbc2d0e68d425dc77ae674a78bcb0cf5efd6634858c0b2408c0f336ccc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinc a deu anys.', true), ('B', 'Un a cinc anys.', false), ('C', 'Deu a vint anys.', false), ('D', 'Sis a vint anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 301.1 del Codi penal, qui adquireixi, posseeixi, utilitzi, converteixi o transmeti béns sabent que tenen l''origen en una activitat delictiva serà castigat amb la pena de:', 'El tipus bàsic de blanqueig de capitals (art. 301.1 CP) es castiga amb presó de sis mesos a sis anys i multa del tant al triple del valor dels béns.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 301.1 CP', 'El que adquiera, posea, utilice, convierta, o transmita bienes, sabiendo que éstos tienen su origen en una actividad delictiva, cometida por él o por cualquiera tercera persona, o realice cualquier otro acto para ocultar o encubrir su origen ilícito, o para ayudar a la persona que haya participado en la infracción o infracciones a eludir las consecuencias legales de sus actos, será castigado con la pena de prisión de seis meses a seis años y multa del tanto al triplo del valor de los bienes.', null, 'dbec24b3633593d95fa9fbe5a8284f525a40e52a84cb4be5aa6e204a426cb10d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dbec24b3633593d95fa9fbe5a8284f525a40e52a84cb4be5aa6e204a426cb10d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a dos anys i multa del tant al triple.', false), ('B', 'Presó de dos a cinc anys i multa del tant al dècuple del valor dels béns.', false), ('C', 'Presó de tres a deu anys i inhabilitació absoluta.', false), ('D', 'Presó de sis mesos a sis anys i multa del tant al triple del valor dels béns.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, quan els béns objecte de blanqueig tenen l''origen en algun dels delictes de tràfic de drogues tòxiques, estupefaents o substàncies psicotròpiques dels articles 368 a 372:', 'L''art. 301.1, paràgraf segon, CP agreuja el blanqueig de béns procedents del tràfic de drogues: la pena s''imposa en la meitat superior.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 301.1 CP', 'La pena se impondrá en su mitad superior cuando los bienes tengan su origen en alguno de los delitos relacionados con el tráfico de drogas tóxicas, estupefacientes o sustancias psicotrópicas descritos en los artículos 368 a 372 de este Código.', null, 'a668e197db0ae74687da8b5a77b1b749b74cdd49ba97c42985a9cc0feb0b90d6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a668e197db0ae74687da8b5a77b1b749b74cdd49ba97c42985a9cc0feb0b90d6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''imposa la pena superior en dos graus.', false), ('B', 'La pena s''imposa en la meitat inferior.', false), ('C', 'La pena s''imposa en la meitat superior.', true), ('D', 'S''aplica la mateixa pena del tipus bàsic, sense cap agreujament.', false)) as v(label, body, ok)
)
