with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 301 del Codi penal, si els fets de blanqueig de capitals es duen a terme per imprudència greu, la pena és de:', 'L''art. 301.3 CP castiga el blanqueig per imprudència greu amb presó de sis mesos a dos anys i multa del tant al triple.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 301.3 CP', 'Si los hechos se realizasen por imprudencia grave, la pena será de prisión de seis meses a dos años y multa del tanto al triplo.', null, '590794c1c66878e63783e8cab9ddeef67dfe82849909d8dcabdcee4d51625e0e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '590794c1c66878e63783e8cab9ddeef67dfe82849909d8dcabdcee4d51625e0e')
  returning id
), o as (
