with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 248 del Codi penal, cometen estafa els qui, amb ànim de lucre:', 'L''art. 248 CP defineix l''estafa per l''ànim de lucre, l''engany suficient (bastant), l''error i l''acte de disposició en perjudici propi o d''altri; el tipus bàsic es castiga amb presó de sis mesos a tres anys.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 248 CP', 'Cometen estafa los que, con ánimo de lucro, utilizaren engaño bastante para producir error en otro, induciéndolo a realizar un acto de disposición en perjuicio propio o ajeno.', null, 'cc091cee9cbab784116b9a03f7f18d1122fcdb2e333d2f6a3cd640636665f4b0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cc091cee9cbab784116b9a03f7f18d1122fcdb2e333d2f6a3cd640636665f4b0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Utilitzen un engany suficient per produir error en una altra persona, i la indueixen a fer un acte de disposició en perjudici propi o d''altri.', true), ('B', 'S''apoderen de coses mobles alienes sense la voluntat del seu propietari.', false), ('C', 'S''apropien de diners o béns que han rebut en dipòsit o administració.', false), ('D', 'Utilitzen violència o intimidació per obligar una altra persona a fer un acte en perjudici propi.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal vigent, també es consideren reus d''estafa, castigats amb presó de sis mesos a tres anys, els qui, amb ànim de lucre i mitjançant una manipulació informàtica o un artifici semblant:', 'L''estafa informàtica es regula actualment a l''art. 249.1.a) CP: transferència no consentida d''un actiu patrimonial aconseguida amb ànim de lucre mitjançant manipulació informàtica o artifici semblant. L''accés il·legal (art. 197 bis.1), els danys informàtics (art. 264) i la interceptació de dades (art. 197 bis.2) són delictes diferents.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 249.1.a) CP', 'Los que, con ánimo de lucro, obstaculizando o interfiriendo indebidamente en el funcionamiento de un sistema de información o introduciendo, alterando, borrando, transmitiendo o suprimiendo indebidamente datos informáticos o valiéndose de cualquier otra manipulación informática o artificio semejante, consigan una transferencia no consentida de cualquier activo patrimonial en perjuicio de otro.', null, '197754006f9d27cb0d5a09a12bd336eafc717781039e0029a8352de5ffaa1ca6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '197754006f9d27cb0d5a09a12bd336eafc717781039e0029a8352de5ffaa1ca6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Accedeixen sense autorització a un sistema d''informació, encara que no causin cap perjudici patrimonial.', false), ('B', 'Esborren dades informàtiques alienes de manera greu, encara que no obtinguin cap benefici.', false), ('C', 'Intercepten transmissions no públiques de dades informàtiques.', false), ('D', 'Aconsegueixen una transferència no consentida de qualsevol actiu patrimonial en perjudici d''un altre.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les afirmacions següents sobre els delictes de terrorisme NO és correcta, segons el Codi penal?', 'L''art. 580 CP equipara, en tots els delictes de terrorisme, la condemna d''un jutge o tribunal estranger a les sentències espanyoles a l''efecte de la reincidència. Les altres tres afirmacions recullen els arts. 571, 572.2 i 579.1 CP.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Arts. 571, 572.2, 579.1 i 580 CP', 'En todos los delitos de terrorismo, la condena de un juez o tribunal extranjero será equiparada a las sentencias de los jueces o tribunales españoles a los efectos de aplicación de la agravante de reincidencia.', null, '91f11610fda26b0abcdffe61e479a9041241fe79ee2722ee62fa9c3e1ec514f6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '91f11610fda26b0abcdffe61e479a9041241fe79ee2722ee62fa9c3e1ec514f6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es consideren organitzacions o grups terroristes les agrupacions que, reunint les característiques de l''organització o del grup criminal, tenen per finalitat la comissió de delictes de terrorisme.', false), ('B', 'La condemna d''un jutge o tribunal estranger per delictes de terrorisme no es té en compte a l''efecte de l''agreujant de reincidència.', true), ('C', 'Qui participi activament en una organització o grup terrorista o en formi part és castigat amb presó de sis a dotze anys i inhabilitació absoluta durant el temps de la condemna.', false), ('D', 'Qui difongui públicament missatges o consignes idonis per incitar altres persones a cometre delictes de terrorisme és castigat amb la pena inferior en un o dos graus a la del delicte de què es tracti.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 572 del Codi penal, qui promogui, constitueixi, organitzi o dirigeixi una organització o grup terrorista serà castigat amb les penes de:', 'L''art. 572.1 CP castiga els promotors i dirigents d''una organització o grup terrorista amb presó de vuit a quinze anys i inhabilitació absoluta durant el temps de la condemna; els membres i participants actius, amb presó de sis a dotze anys (art. 572.2).', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 572.1 CP', 'Quienes promovieran, constituyeran, organizaran o dirigieran una organización o grupo terrorista serán castigados con las penas de prisión de ocho a quince años e inhabilitación absoluta durante el tiempo de la condena.', null, '1825cdfca84815b7bb4d105f281cd7bb3ccd99222e60739869e57db34ff601fc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1825cdfca84815b7bb4d105f281cd7bb3ccd99222e60739869e57db34ff601fc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de vuit a quinze anys i inhabilitació absoluta durant el temps de la condemna.', true), ('B', 'Presó de sis a dotze anys i inhabilitació absoluta durant el temps de la condemna.', false), ('C', 'Presó de quatre a vuit anys i inhabilitació especial de sis a vint anys.', false), ('D', 'Presó de deu a vint anys i inhabilitació absoluta de deu a vint anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 573.1 del Codi penal, quina de les finalitats següents NO és una de les que converteixen un delicte greu en delicte de terrorisme?', 'L''art. 573.1 CP exigeix alguna d''aquestes finalitats: subvertir l''ordre constitucional o desestabilitzar greument les institucions o estructures de l''Estat, alterar greument la pau pública, desestabilitzar greument una organització internacional o provocar un estat de terror. L''ànim de lucre no hi és.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 573.1 CP', '1.ª Subvertir el orden constitucional, o suprimir o desestabilizar gravemente el funcionamiento de las instituciones políticas o de las estructuras económicas o sociales del Estado, u obligar a los poderes públicos a realizar un acto o a abstenerse de hacerlo. 2.ª Alterar gravemente la paz pública. 3.ª Desestabilizar gravemente el funcionamiento de una organización internacional. 4.ª Provocar un estado de terror en la población o en una parte de ella.', null, '869b40faf8ee4b8098e256ac6eb9ebd81e921539a7e4f28863bc5e1d6efce2c7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '869b40faf8ee4b8098e256ac6eb9ebd81e921539a7e4f28863bc5e1d6efce2c7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Subvertir l''ordre constitucional o desestabilitzar greument el funcionament de les institucions polítiques.', false), ('B', 'Alterar greument la pau pública.', false), ('C', 'Provocar un estat de terror en la població o en una part d''aquesta.', false), ('D', 'Obtenir un benefici econòmic per a l''organització, encara que no hi hagi cap altra finalitat.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 573 bis del Codi penal, les penes dels delictes de terrorisme s''imposen en la meitat superior si els fets es cometen, entre d''altres, contra:', 'L''art. 573 bis.2 CP agreuja les penes de terrorisme quan els fets es cometen contra les persones de l''art. 550.3, membres de les Forces i Cossos de Seguretat o de les Forces Armades, o empleats públics que presten servei en institucions penitenciàries.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 573 bis.2 CP', 'Las penas se impondrán en su mitad superior si los hechos se cometieran contra las personas mencionadas en el apartado 3 del artículo 550 o contra miembros de las Fuerzas y Cuerpos de Seguridad o de las Fuerzas Armadas o contra empleados públicos que presten servicio en instituciones penitenciarias.', null, 'b872bbae299cfe69fbff4dacf0c7de4277c0d622fca3ac3f19c2354e7a7c38c2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b872bbae299cfe69fbff4dacf0c7de4277c0d622fca3ac3f19c2354e7a7c38c2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol persona menor d''edat.', false), ('B', 'Els familiars dels condemnats per terrorisme.', false), ('C', 'Empleats públics que prestin servei en institucions penitenciàries.', true), ('D', 'Persones estrangeres residents a Espanya.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, els delictes informàtics dels articles 197 bis, 197 ter i 264 a 264 quater es consideren delictes de terrorisme:', 'L''art. 573.2 CP qualifica de terrorisme els delictes informàtics dels arts. 197 bis, 197 ter i 264 a 264 quater quan es cometen amb alguna de les finalitats de l''art. 573.1.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 573.2 CP', 'Se considerarán igualmente delitos de terrorismo los delitos informáticos tipificados en los artículos 197 bis y 197 ter y 264 a 264 quater cuando los hechos se cometan con alguna de las finalidades a las que se refiere el apartado anterior.', null, '952fbc358aad74205bc9d827d85583f6cb1df20d31b06d6405ae3394ba262688', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '952fbc358aad74205bc9d827d85583f6cb1df20d31b06d6405ae3394ba262688')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En cap cas, perquè només ho són els delictes contra la vida i la integritat física.', false), ('B', 'Quan els fets es cometen amb alguna de les finalitats terroristes previstes a l''article 573.1.', true), ('C', 'Sempre que es cometin dins d''una organització criminal, sigui quina sigui la finalitat.', false), ('D', 'Només si afecten sistemes informàtics d''un altre Estat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 578 del Codi penal, l''enaltiment o la justificació públics dels delictes de terrorisme o de qui hi hagi participat es castiga amb la pena de:', 'L''art. 578.1 CP castiga l''enaltiment o la justificació públics del terrorisme i els actes de descrèdit o humiliació de les víctimes amb presó d''un a tres anys i multa de dotze a divuit mesos; la pena s''agreuja si es fa per internet o mitjans de comunicació (art. 578.2).', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 578.1 CP', 'El enaltecimiento o la justificación públicos de los delitos comprendidos en los artículos 572 a 577 o de quienes hayan participado en su ejecución, o la realización de actos que entrañen descrédito, menosprecio o humillación de las víctimas de los delitos terroristas o de sus familiares, se castigará con la pena de prisión de uno a tres años y multa de doce a dieciocho meses.', null, 'c9e8438a77e59a82713d1c1b26312332a1f629c0b1f44606d8abb61b74b88860', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c9e8438a77e59a82713d1c1b26312332a1f629c0b1f44606d8abb61b74b88860')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a tres anys i multa de dotze a divuit mesos.', true), ('B', 'Presó de cinc a deu anys i multa de divuit a vint-i-quatre mesos.', false), ('C', 'Presó de sis mesos a dos anys o multa de sis a dotze mesos.', false), ('D', 'Presó de dos a cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 197 bis del Codi penal, qui, vulnerant les mesures de seguretat establertes per impedir-ho i sense estar degudament autoritzat, accedeixi a un sistema d''informació o s''hi mantingui contra la voluntat de qui té el dret legítim d''excloure''l serà castigat amb la pena de:', 'L''accés il·legal a sistemes d''informació (art. 197 bis.1 CP) es castiga amb presó de sis mesos a dos anys; la interceptació de transmissions no públiques de dades (art. 197 bis.2) té presó de tres mesos a dos anys o multa de tres a dotze mesos.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 197 bis.1 CP', 'El que por cualquier medio o procedimiento, vulnerando las medidas de seguridad establecidas para impedirlo, y sin estar debidamente autorizado, acceda o facilite a otro el acceso al conjunto o una parte de un sistema de información o se mantenga en él en contra de la voluntad de quien tenga el legítimo derecho a excluirlo, será castigado con pena de prisión de seis meses a dos años.', null, '4d87495bd6625f0686c514bc8c511cd59188c6a916bb331cf6ef25eaf90b96fe', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4d87495bd6625f0686c514bc8c511cd59188c6a916bb331cf6ef25eaf90b96fe')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de tres mesos a dos anys o multa de tres a dotze mesos.', false), ('B', 'Presó de sis mesos a tres anys.', false), ('C', 'Presó de sis mesos a dos anys.', true), ('D', 'Multa de tres a divuit mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 264.1 del Codi penal, qui per qualsevol mitjà, sense autorització i de manera greu, esborri, danyi, deteriori, alteri, suprimeixi o faci inaccessibles dades informàtiques, programes informàtics o documents electrònics aliens, quan el resultat produït sigui greu, serà castigat amb la pena de:', 'Els danys informàtics del tipus bàsic (art. 264.1 CP) es castiguen amb presó de sis mesos a tres anys; si concorre alguna circumstància de l''art. 264.2 (organització criminal, danys d''especial gravetat, serveis públics essencials, infraestructura crítica…), la pena és de dos a cinc anys i multa del tant al dècuple.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 264.1 CP', 'El que por cualquier medio, sin autorización y de manera grave borrase, dañase, deteriorase, alterase, suprimiese o hiciese inaccesibles datos informáticos, programas informáticos o documentos electrónicos ajenos, cuando el resultado producido fuera grave, será castigado con la pena de prisión de seis meses a tres años.', null, '6ba68c8a52aa3292df095d0d1611d0aa3b56f856c8b242a43d67b5c093b4c764', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6ba68c8a52aa3292df095d0d1611d0aa3b56f856c8b242a43d67b5c093b4c764')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a dos anys.', false), ('B', 'Presó de dos a cinc anys i multa del tant al dècuple del perjudici.', false), ('C', 'Presó de tres a vuit anys.', false), ('D', 'Presó de sis mesos a tres anys.', true)) as v(label, body, ok)
)
