with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, com es configura el Centre d''Iniciatives per a la Reinserció en cada centre penitenciari?', 'L''art. 107.1 del Decret 329/2006 atribueix al CIRE la planificació, organització, gestió i direcció del treball penitenciari, de la formació ocupacional i de la inserció sociolaboral, i el configura en cada centre com una unitat de servei amb entitat pròpia i representació al Consell de Direcció i a la junta de tractament.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 107.1 D329', 'el qual es configurarà en cada centre penitenciari com una unitat de servei, amb entitat pròpia i representació al Consell de Direcció i a la Junta de Tractament.', null, '3dafa4660e9a93f4b13c0a198d46b906e8d3eb73b762643fc635a64a2518917a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3dafa4660e9a93f4b13c0a198d46b906e8d3eb73b762643fc635a64a2518917a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Com una subdirecció del centre, sota la dependència directa del/de la director/a.', false), ('B', 'Com una unitat de servei, amb entitat pròpia i representació al Consell de Direcció i a la junta de tractament.', true), ('C', 'Com un òrgan col·legiat del centre, presidit pel/per la gerent.', false), ('D', 'Com una secció de la unitat de gestió econòmica.', false)) as v(label, body, ok)
)
