with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el resum oficial del RisCanvi, quina particularitat presenta el RisCanvi-C respecte del RisCanvi-S?', 'El RisCanvi-C, a diferència del RisCanvi-S, permet corregir el resultat actuarial per decisió motivada de l''equip; el risc finalment validat és el que decideix l''equip.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 3, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 4', 'RisCanvi C presenta la particularitat, a diferència de RisCanvi S, que permet fer una correcció del resultat actuarial, mitjançant una decisió d''equip degudament motivada', null, '980409b0fc9909cee96c42092e7226c447abd2f933f902b30c4cda079cbcb7ee', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '980409b0fc9909cee96c42092e7226c447abd2f933f902b30c4cda079cbcb7ee')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Permet corregir el resultat actuarial mitjançant una decisió d''equip degudament motivada.', true), ('B', 'No fa servir cap procediment actuarial, només la valoració clínica de l''equip.', false), ('C', 'L''administra el jutge de vigilància penitenciària.', false), ('D', 'Només s''aplica als interns en règim obert i als alliberats condicionals.', false)) as v(label, body, ok)
)
