with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el resum oficial del RisCanvi, quin termini màxim hi ha per validar l''escala RisCanvi-S des que s''obre per primera vegada?', 'El resum fixa un termini màxim de 30 dies des de l''obertura per validar el RisCanvi-S (i també 30 dies per validar el RisCanvi-C). Els sis mesos són el termini de vigència.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 5', 'Des de l''obertura del primer cop de l''escala RisCanvi S hi ha un termini màxim establert de 30 dies per que aquest sigui validat.', null, 'ad5d506f834e647f921e7caaaf2ff45e47c95eccf63809dba96da4dbd72b7a43', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ad5d506f834e647f921e7caaaf2ff45e47c95eccf63809dba96da4dbd72b7a43')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '10 dies.', false), ('B', '30 dies.', true), ('C', '15 dies.', false), ('D', 'Sis mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el resum oficial del RisCanvi, el protocol perd la vigència si durant els sis mesos es produeix un esdeveniment crític. Quin dels fets següents NO s''hi considera esdeveniment crític?', 'Entre els esdeveniments crítics hi ha les conductes agressives, l''intent d''autolesió o suïcidi, la vaga de fam, la recaiguda en el consum, l''incompliment de mesures de supervisió o la nova informació rellevant. Gaudir d''un permís sense incidències no n''és cap.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 3, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 5', 'si hi ha algun intent (consumat o no) d''autolesió o suïcidi, si l''intern/a es declara en vaga de fam, en cas que l''intern/a es trobi en fase de recaiguda respecte al consum de substàncies', null, '8a46c0eef17d59050a8f1298ed500c3af674965bdc924438dadea5ffc3b49467', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8a46c0eef17d59050a8f1298ed500c3af674965bdc924438dadea5ffc3b49467')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que l''intern faci un intent, consumat o no, d''autolesió o suïcidi.', false), ('B', 'Que l''intern es declari en vaga de fam.', false), ('C', 'Que l''intern es trobi en fase de recaiguda respecte al consum de substàncies.', false), ('D', 'Que l''intern gaudeixi d''un permís ordinari de sortida sense cap incidència.', true)) as v(label, body, ok)
)
