-- Lote pcat-e20-model-intervencio-riscanvi-riscanvi_web-v1 (2 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Protocol de valoració del risc (RisCanvi) · web del Departament de Justícia', 'https://justicia.gencat.cat/ca/ambits/reinsercio_i_serveis_penitenciaris/serveis_penitenciaris/RisCanvi/', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament de Justícia', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e20-model-intervencio-riscanvi', 'Tema 20. El model d''intervenció, el RisCanvi i el CIRE') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e20-model-intervencio-riscanvi' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Departament de Justícia, el model d''intervenció amb què treballen els serveis penitenciaris catalans està fonamentat en:', 'La pàgina oficial del RisCanvi indica que l''avaluació i la gestió del risc amb instruments basats en l''evidència científica és un component fonamental del model d''intervenció, i que els serveis penitenciaris catalans treballen sobre aquest model.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/ca/ambits/reinsercio_i_serveis_penitenciaris/serveis_penitenciaris/RisCanvi/'), 'RisCanvi (web del Departament de Justícia)', 'L''avaluació i la gestió del risc mitjançant instruments basats en l''evidència científica és un dels components fonamentals del model d''intervenció que més aval té avui en dia de la comunitat científica i les institucions. Els serveis penitenciaris catalans treballen sobre aquest model fonamentat en l''avaluació i gestió del risc', null, '39e0244fa35861242780dccdd02fcdbd389109235a4727c3202121f27ca5a861', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '39e0244fa35861242780dccdd02fcdbd389109235a4727c3202121f27ca5a861')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La classificació dels interns exclusivament segons el delicte comès i la durada de la condemna.', false), ('B', 'L''avaluació i la gestió del risc mitjançant instruments basats en l''evidència científica.', true), ('C', 'L''aplicació uniforme del mateix programa de tractament a tota la població penitenciària.', false), ('D', 'L''ús de mitjans coercitius i de mesures de seguretat com a eix principal de la intervenció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la informació oficial del Departament de Justícia, el RisCanvi ofereix suport als processos de presa de decisions principalment en relació amb:', 'Segons la web oficial, el RisCanvi dona suport a les decisions sobre la planificació de la intervenció (necessitats de cada intern i disseny del programa individual de tractament), la classificació i la concessió de permisos.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/ca/ambits/reinsercio_i_serveis_penitenciaris/serveis_penitenciaris/RisCanvi/'), 'RisCanvi (web del Departament de Justícia)', 'Ofereix suport als processos de presa de decisions, principalment en allò que té a veure amb la planificació de la intervenció (avalua les necessitats de cada intern i permet orientar el disseny del seu programa individual de tractament per complir amb l''itinerari de reinserció), la classificació i la concessió de permisos', null, '50a85f11bdb92df62db28b4c9b6cbee4681d72dae81edf4127197cb4aa522faa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '50a85f11bdb92df62db28b4c9b6cbee4681d72dae81edf4127197cb4aa522faa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La imposició de sancions disciplinàries i l''execució de les sancions d''aïllament.', false), ('B', 'Els trasllats entre centres i les conduccions a l''exterior.', false), ('C', 'La selecció i la provisió de llocs de treball del personal penitenciari.', false), ('D', 'La planificació de la intervenció, la classificació i la concessió de permisos.', true)) as v(label, body, ok)
)
