insert into public.topics (slug, title) values ('pcat-e20-model-intervencio-riscanvi', 'Tema 20. El model d''intervenció, el RisCanvi i el CIRE') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e20-model-intervencio-riscanvi' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari (RP), si un intern rebutja o no col·labora en la realització d''una tècnica d''estudi de la seva personalitat:', 'L''art. 112.3 RP reconeix que l''intern pot rebutjar lliurement o no col·laborar en les tècniques d''estudi de la personalitat sense conseqüències disciplinàries, regimentals ni de regressió de grau.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 112.3 RP', 'El interno podrá rechazar libremente o no colaborar en la realización de cualquier técnica de estudio de su personalidad, sin que ello tenga consecuencias disciplinarias, regimentales ni de regresión de grado.', null, '9fccab09a2f5f21c8cef70cc20b5093bd5a955a69e955dd69df4ddc016e06f0a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9fccab09a2f5f21c8cef70cc20b5093bd5a955a69e955dd69df4ddc016e06f0a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No té conseqüències disciplinàries, regimentals ni de regressió de grau.', true), ('B', 'Comet una falta lleu per incompliment dels deures de l''intern.', false), ('C', 'Ha de ser regressat de grau de manera automàtica.', false), ('D', 'Perd el dret a gaudir de permisos ordinaris de sortida.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, quan l''intern rebutja col·laborar en l''estudi de la seva personalitat, com es fan la classificació inicial i les revisions posteriors?', 'L''art. 112.4 RP preveu que, en cas de rebuig, la classificació i les revisions es facin per observació directa del comportament, informes del personal dels equips tècnics i dades documentals.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 112.4 RP', 'la clasificación inicial y las posteriores revisiones de la misma se realizarán mediante la observación directa del comportamiento y los informes pertinentes del personal penitenciario de los Equipos Técnicos que tenga relación con el interno, así como utilizando los datos documentales existentes.', null, 'd950a73b57bbf9bc6bb9fe773181304b1dc33a3c07c2c8c8ec909e7ab6e66726', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd950a73b57bbf9bc6bb9fe773181304b1dc33a3c07c2c8c8ec909e7ab6e66726')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No es poden fer fins que l''intern accepti col·laborar.', false), ('B', 'Mitjançant l''observació directa del comportament, els informes del personal dels equips tècnics que hi tingui relació i les dades documentals existents.', true), ('C', 'Les fa directament el jutge de vigilància penitenciària.', false), ('D', 'Es classifica automàticament l''intern en primer grau.', false)) as v(label, body, ok)
)
