with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 56.1 de l''Estatut d''autonomia de Catalunya, de quants diputats es compon el Parlament?', 'L''art. 56.1 EAC fixa un mínim de 100 i un màxim de 150 diputats, elegits per quatre anys per sufragi universal, lliure, igual, directe i secret.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 56.1 EAC', 'El Parlamento se compone de un mínimo de cien Diputados y un máximo de ciento cincuenta, elegidos para un plazo de cuatro años', null, 'e9a0354aa26968847aacfbf81bd304e892a4e73e66826c25067978631c127e44', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e9a0354aa26968847aacfbf81bd304e892a4e73e66826c25067978631c127e44')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'D''un mínim de noranta diputats i un màxim de cent trenta-cinc.', false), ('B', 'D''un nombre fix de cent trenta-cinc diputats.', false), ('C', 'D''un mínim de cent diputats i un màxim de cent cinquanta.', true), ('D', 'D''un mínim de cent vint diputats i un màxim de cent cinquanta.', false)) as v(label, body, ok)
)
