with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 110 de l''Estatut d''autonomia de Catalunya, en l''àmbit de les competències exclusives corresponen a la Generalitat:', 'En les competències exclusives, la Generalitat té de manera íntegra la potestat legislativa, la reglamentària i la funció executiva, i hi pot establir polítiques pròpies (art. 110.1 EAC). El marc de les bases estatals és propi de les compartides (art. 111) i la limitació a la funció executiva, de les executives (art. 112).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 110.1 EAC', 'Corresponden a la Generalitat, en el ámbito de sus competencias exclusivas, de forma íntegra la potestad legislativa, la potestad reglamentaria y la función ejecutiva.', null, '3dfd89d1ef6a5f1ff5b4021bf237bb1cb087a3887d22d37de3c6167ce1b91480', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3dfd89d1ef6a5f1ff5b4021bf237bb1cb087a3887d22d37de3c6167ce1b91480')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només la potestat reglamentària i la funció executiva.', false), ('B', 'La potestat legislativa i reglamentària, en el marc de les bases que fixi l''Estat.', false), ('C', 'Només la funció executiva, incloent-hi la potestat d''organització de la seva pròpia administració.', false), ('D', 'De forma íntegra, la potestat legislativa, la potestat reglamentària i la funció executiva.', true)) as v(label, body, ok)
)
