with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 111 de l''Estatut d''autonomia de Catalunya, en les matèries que l''Estatut atribueix a la Generalitat de forma compartida amb l''Estat:', 'En les competències compartides, la Generalitat té la potestat legislativa, la reglamentària i la funció executiva en el marc de les bases estatals, i el Parlament ha de desplegar i concretar per llei aquestes previsions bàsiques (art. 111 EAC).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 111 EAC', 'En las materias que el Estatuto atribuye a la Generalitat de forma compartida con el Estado, corresponden a la Generalitat la potestad legislativa, la potestad reglamentaria y la función ejecutiva, en el marco de las bases que fije el Estado', null, 'cf606b04c4b4cad1f649f9bf1318fb14738269b594c329ca9ffa009a329a41a5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cf606b04c4b4cad1f649f9bf1318fb14738269b594c329ca9ffa009a329a41a5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Correspon a la Generalitat únicament la funció executiva, i a l''Estat la potestat legislativa i la reglamentària.', false), ('B', 'Corresponen a la Generalitat, de forma íntegra i sense cap límit, la potestat legislativa, la reglamentària i la funció executiva.', false), ('C', 'Correspon a la Generalitat només la potestat reglamentària per a l''execució de la normativa de l''Estat.', false), ('D', 'Corresponen a la Generalitat la potestat legislativa, la reglamentària i la funció executiva, en el marc de les bases que fixi l''Estat.', true)) as v(label, body, ok)
)
