insert into public.topics (slug, title) values ('pcat-g1-marc-constitucional-estatut', 'Part general. Tema 1. Marc constitucional, Estatut d''autonomia, Govern i president de la Generalitat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g1-marc-constitucional-estatut' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, de la presidència de la Generalitat i del Govern, el president o presidenta de la Generalitat, un cop investit pel Parlament, és nomenat per:', 'El president o presidenta de la Generalitat és elegit pel Parlament d''entre els seus membres i, un cop investit, és nomenat pel rei o la reina a proposta del president o presidenta del Parlament (art. 5.1 Llei 13/2008; art. 67.4 EAC).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 5.1 Llei 13/2008', 'El presidente o presidenta de la Generalidad, tras ser investido por el Parlamento, es nombrado por el rey o reina a propuesta del presidente o presidenta del Parlamento.', null, '0ce64204475baed5d5c56a698726a408a9b489f335dd892cf5756f617356b7bc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0ce64204475baed5d5c56a698726a408a9b489f335dd892cf5756f617356b7bc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Ple del Parlament, per majoria absoluta.', false), ('B', 'El rei o la reina, a proposta del president del Govern de l''Estat.', false), ('C', 'El rei o la reina, a proposta del president o presidenta del Parlament.', true), ('D', 'El president o presidenta del Parlament, en nom del rei o la reina.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, si el candidat o candidata a la presidència de la Generalitat no obté la majoria absoluta en la primera votació d''investidura:', 'En la primera votació cal la majoria absoluta; si no s''obté, el candidat es pot sotmetre dos dies després a un segon debat i una segona votació, en què n''hi ha prou amb la majoria simple (art. 4.4 i 4.5 Llei 13/2008).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 4.4 i 4.5 Llei 13/2008', 'Si el candidato o candidata no consigue la mayoría absoluta, puede someterse, dos días después, a un segundo debate y a una segunda votación, en la que bastará la mayoría simple.', null, '56030cbf1a0881bd7f4d5631d099dd659d600009618c7c71128850139ee20b4e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '56030cbf1a0881bd7f4d5631d099dd659d600009618c7c71128850139ee20b4e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es pot sotmetre, deu dies després, a una segona votació, en què també cal la majoria absoluta.', false), ('B', 'Es pot sotmetre, dos dies després, a una segona votació, en què n''hi ha prou amb la majoria simple.', true), ('C', 'El president o presidenta del Parlament ha de proposar immediatament un altre candidat.', false), ('D', 'La legislatura queda dissolta automàticament.', false)) as v(label, body, ok)
)
