with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 6.3 de la Llei 13/2008, quina de les atribucions següents NO pot exercir la persona que supleix o substitueix el president o presidenta de la Generalitat?', 'Ni la suplència ni la substitució permeten exercir les atribucions relatives al plantejament d''una qüestió de confiança, a la designació i el cessament dels consellers ni a la dissolució anticipada de la legislatura (art. 6.3 Llei 13/2008; art. 67.8 EAC).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 6.3 Llei 13/2008', 'Ni la suplencia ni la sustitución del presidente o presidenta de la Generalidad permiten ejercer las atribuciones del cargo relativas al planteamiento de una cuestión de confianza, a la designación y el cese de los consejeros o a la disolución anticipada de la legislatura.', null, '11d720103e7433b326ec80ce94feccd74659a58f4486f84950ede3eb356c5756', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '11d720103e7433b326ec80ce94feccd74659a58f4486f84950ede3eb356c5756')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Plantejar una qüestió de confiança.', true), ('B', 'Convocar i presidir les reunions del Govern.', false), ('C', 'Representar el Govern.', false), ('D', 'Resoldre els conflictes d''atribucions entre consellers.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, qui pot proposar una moció de censura contra el president o presidenta de la Generalitat?', 'La moció de censura l''ha de proposar com a mínim una cinquena part dels diputats o dos grups parlamentaris, i ha d''incloure un candidat a la presidència que hagi acceptat la candidatura. S''aprova si la voten afirmativament la majoria absoluta dels diputats (art. 43.1 i 43.5 Llei 13/2008).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 43.1 i 43.5 Llei 13/2008', 'La moción de censura debe ser propuesta como mínimo por una quinta parte de los diputados o por dos grupos parlamentarios y debe incluir un candidato o candidata a la presidencia de la Generalidad, que debe haber aceptado la candidatura.', null, 'b7b1180126c52a548f91d5533ef1072c6e51ad41744341996fee6bfa6ab6e422', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b7b1180126c52a548f91d5533ef1072c6e51ad41744341996fee6bfa6ab6e422')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Com a mínim una desena part dels diputats o un grup parlamentari.', false), ('B', 'Com a mínim una cinquena part dels diputats o dos grups parlamentaris.', true), ('C', 'Com a mínim una tercera part dels diputats o tres grups parlamentaris.', false), ('D', 'La majoria absoluta dels diputats.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, quan el Govern es troba en funcions:', 'El Govern en funcions limita la seva actuació al despatx ordinari dels assumptes públics, incloent-hi la potestat reglamentària (art. 27.1); no pot aprovar el projecte de pressupostos, presentar projectes de llei ni dictar decrets legislatius (art. 27.2), però sí decrets llei (art. 27.3). A més, la delegació legislativa caduca quan el Govern és en funcions (art. 37.6).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 27.2 Llei 13/2008', 'El Gobierno, cuando se halla en funciones, no puede aprobar el proyecto de ley de presupuestos de la Generalidad, ni presentar proyectos de ley al Parlamento, ni dictar decretos legislativos.', null, '235b1b046194ec625be8473d1909f6a75fc3164f2c4ff7e0991ccfe798641b3c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '235b1b046194ec625be8473d1909f6a75fc3164f2c4ff7e0991ccfe798641b3c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No pot dictar decrets llei en cap cas.', false), ('B', 'No pot exercir la potestat reglamentària, ni tan sols per al despatx ordinari dels assumptes públics.', false), ('C', 'No pot aprovar el projecte de llei de pressupostos, ni presentar projectes de llei al Parlament, ni dictar decrets legislatius.', true), ('D', 'Pot dictar decrets legislatius si la delegació legislativa s''havia fet abans que entrés en funcions.', false)) as v(label, body, ok)
)
