-- Lote pcat-g2-organitzacio-generalitat-eac-v1 (2 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/2006, de 19 de julio, de reforma del Estatuto de Autonomía de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g2-organitzacio-generalitat', 'Part general. Tema 2. Organització de l''Administració de la Generalitat i departaments') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g2-organitzacio-generalitat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 71.2 de l''Estatut d''autonomia de Catalunya, l''Administració de la Generalitat:', 'L''art. 71.2 EAC disposa que l''Administració de la Generalitat serveix amb objectivitat els interessos generals i actua amb submissió plena a les lleis i al dret.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 71.2 EAC', 'La Administración de la Generalitat sirve con objetividad los intereses generales y actúa con sumisión plena a las leyes y al derecho.', null, 'a20c3dcd20c6e3506359d8f5d8607cdd857592e59da3041c5d3608a832ab970a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a20c3dcd20c6e3506359d8f5d8607cdd857592e59da3041c5d3608a832ab970a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Serveix els interessos generals d''acord amb les directrius del partit que dona suport al Govern.', false), ('B', 'Actua amb submissió plena a les instruccions del president o presidenta de la Generalitat.', false), ('C', 'Serveix amb objectivitat els interessos de les persones interessades en cada procediment.', false), ('D', 'Serveix amb objectivitat els interessos generals i actua amb submissió plena a les lleis i al dret.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
