with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 71.5 de l''Estatut d''autonomia de Catalunya, l''Administració de la Generalitat exerceix les seves funcions en el territori d''acord amb els principis de:', 'Al territori, l''Administració de la Generalitat actua d''acord amb els principis de desconcentració i descentralització (art. 71.5 EAC). Els principis de coordinació i transversalitat també hi apareixen, però a l''art. 71.3, per garantir la integració de les polítiques públiques.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 71.5 EAC', 'La Administración de la Generalitat ejerce sus funciones en el territorio de acuerdo con los principios de desconcentración y descentralización.', null, '57d628273c63d1d14099e5ee33f8220c5211c2af5b17bdd4cb610c160520c08f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '57d628273c63d1d14099e5ee33f8220c5211c2af5b17bdd4cb610c160520c08f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Jerarquia i competència.', false), ('B', 'Coordinació i transversalitat.', false), ('C', 'Desconcentració i descentralització.', true), ('D', 'Subsidiarietat i proporcionalitat.', false)) as v(label, body, ok)
)
