with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 16 de la Llei 13/2008, quina atribució correspon als consellers en relació amb els càrrecs del seu departament?', 'Els consellers proposen al Govern el nomenament i el cessament dels alts càrrecs del departament i acorden el nomenament i el cessament dels altres càrrecs del departament (art. 16.d Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 16.d Llei 13/2008', 'Proponer al Gobierno el nombramiento y el cese de los altos cargos del departamento, y acordar el nombramiento y el cese de los demás cargos del departamento.', null, '18a7fbb674a856c9f2c769f9a916f9d5cf27e436514e34d882f7207dbc591d33', false
