with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, de règim jurídic i de procediment de les administracions públiques de Catalunya, la competència:', 'La competència és irrenunciable i l''han d''exercir de forma precisa els òrgans que la tenen atribuïda com a pròpia, llevat dels casos de delegació o d''avocació fets en els termes legals (art. 6.1 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 6.1 Llei 26/2010', 'La competencia es irrenunciable y debe ser ejercida de forma precisa por los órganos administrativos que la tienen atribuida como propia, salvo en los casos de delegación o de avocación, cuando se efectúen en los términos establecidos por esta u otras leyes.', null, '47dc58dfe9d5e0b82d6216b635786867329ca2b4a5a76a9f743057ed9b9a2115', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '47dc58dfe9d5e0b82d6216b635786867329ca2b4a5a76a9f743057ed9b9a2115')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'És renunciable si l''òrgan no disposa de mitjans per exercir-la.', false), ('B', 'Es pot transferir lliurement a qualsevol altre òrgan de la mateixa administració.', false), ('C', 'És irrenunciable i l''han d''exercir de forma precisa els òrgans que la tenen atribuïda com a pròpia, llevat dels casos de delegació o avocació.', true), ('D', 'És irrenunciable, i per això no es pot delegar ni avocar en cap cas.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 8 de la Llei 26/2010, quina de les competències següents NO es pot delegar?', 'No es poden delegar les competències relatives a l''adopció de disposicions reglamentàries, a la resolució de recursos en els òrgans que han dictat els actes recorreguts, a les que s''exerceixen per delegació (llevat que una llei ho autoritzi) i a les matèries que determini una norma amb rang de llei (art. 8.3). La delegació pot ser general o per a un procediment concret (art. 8.2) i la d''òrgans col·legiats requereix el mateix quòrum especial (art. 8.9).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 8 Llei 26/2010', 'No pueden delegarse las competencias relativas a: a) La adopción de disposiciones reglamentarias.', null, '5f2b7c081b2edd4f54db26597a6bb5aa1886e4e4e2c3f8a78befba9760557cfd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5f2b7c081b2edd4f54db26597a6bb5aa1886e4e4e2c3f8a78befba9760557cfd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La competència atribuïda a un òrgan col·legiat que requereixi un quòrum especial, si la delegació s''adopta amb aquest quòrum.', false), ('B', 'La competència per resoldre un procediment administratiu concret, si encara no s''hi ha emès cap dictamen o informe preceptiu.', false), ('C', 'Una competència de caràcter general, no limitada a un procediment concret.', false), ('D', 'L''adopció de disposicions reglamentàries.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, contra la resolució d''avocació:', 'La resolució d''avocació ha de ser motivada i s''ha de notificar als interessats abans de la resolució o publicar-se; contra aquesta resolució no es pot interposar recurs, però es pot impugnar en el recurs que s''interposi contra la resolució del procediment (art. 9.2 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 9.2 Llei 26/2010', 'Contra dicha resolución no puede interponerse recurso, aunque puede impugnarse en el recurso que, en su caso, se interponga contra la resolución del procedimiento.', null, '2216360e3999dc8a7b647d997dc50b39a1ea89fc18f8e608292591e320b6aa13', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2216360e3999dc8a7b647d997dc50b39a1ea89fc18f8e608292591e320b6aa13')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No es pot interposar recurs, tot i que es pot impugnar en el recurs que, si escau, s''interposi contra la resolució del procediment.', true), ('B', 'Es pot interposar recurs d''alçada davant l''òrgan superior jeràrquic.', false), ('C', 'Es pot interposar recurs potestatiu de reposició en el termini d''un mes.', false), ('D', 'Es pot interposar directament recurs contenciós administratiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, per a quin tipus de resolucions NO és procedent l''autorització de signatura?', 'Els titulars dels òrgans poden autoritzar la signatura dels seus actes als titulars d''òrgans o unitats dependents, de manera general o per a un procediment concret, però l''autorització de signatura no és procedent per a les resolucions de caràcter sancionador (art. 11 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 11.3 Llei 26/2010', 'La autorización de firma no es procedente para las resoluciones de carácter sancionador.', null, '8bca1082317144e78f2df5d7648a5765d351e9660ef291be5263795396d27d05', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8bca1082317144e78f2df5d7648a5765d351e9660ef291be5263795396d27d05')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per a les resolucions dictades en un procediment administratiu concret.', false), ('B', 'Per a les resolucions de caràcter sancionador.', true), ('C', 'Per a les resolucions de concessió de subvencions.', false), ('D', 'Per a les resolucions que posen fi a un procediment iniciat a sol·licitud de l''interessat.', false)) as v(label, body, ok)
)
