with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, amb quina antelació mínima s''ha de notificar als membres d''un òrgan col·legiat la convocatòria de la sessió, llevat d''urgència apreciada pel president?', 'La convocatòria, amb l''ordre del dia, s''ha de notificar amb una antelació mínima de 48 hores, llevat d''urgència apreciada pel president o presidenta, que s''ha de fer constar a la convocatòria (art. 17.1 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 17.1 Llei 26/2010', 'La convocatoria de la sesión del órgano colegiado, con el correspondiente orden del día, debe ser notificada a los miembros con una antelación mínima de cuarenta y ocho horas', null, 'ca5a4c6f86222e6d5de95e50c8aad99426b8082d7dab16656b38d2b52fcec124', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ca5a4c6f86222e6d5de95e50c8aad99426b8082d7dab16656b38d2b52fcec124')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Vint-i-quatre hores.', false), ('B', 'Setanta-dues hores.', false), ('C', 'Quaranta-vuit hores.', true), ('D', 'Cinc dies hàbils.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, si les normes pròpies d''un òrgan col·legiat no especifiquen el nombre de membres necessari, amb quina assistència s''assoleix el quòrum en segona convocatòria?', 'En primera convocatòria cal la presència del president i del secretari (o substituts) i de la meitat, com a mínim, dels membres (art. 17.4); en segona convocatòria, si les normes de l''òrgan no ho especifiquen, n''hi ha prou amb una tercera part dels membres, amb un mínim de tres (art. 17.6 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 17.6 Llei 26/2010', 'En segunda convocatoria, si las normas propias del órgano no han especificado el número de miembros necesarios para constituir válidamente el órgano, el quórum se alcanza con la asistencia de una tercera parte de los miembros, con un mínimo de tres.', null, '4348a1e8626318aec1623b61e0e0dbe25d1736037e116c93a8775c1e69de5952', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4348a1e8626318aec1623b61e0e0dbe25d1736037e116c93a8775c1e69de5952')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb la meitat dels membres, amb un mínim de tres.', false), ('B', 'Amb una tercera part dels membres, amb un mínim de tres.', true), ('C', 'Amb una tercera part dels membres, sense mínim.', false), ('D', 'Amb una quarta part dels membres, amb un mínim de dos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, en quin termini poden formular un vot particular per escrit els membres d''un òrgan col·legiat que discrepen de l''acord majoritari?', 'Els membres que discrepen de l''acord majoritari poden formular un vot particular per escrit en el termini de 72 hores, que s''ha d''incorporar al text de l''acord (art. 20.2 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 20.2 Llei 26/2010', 'Los miembros que discrepan del acuerdo mayoritario pueden formular un voto particular por escrito en el plazo de setenta y dos horas, el cual debe incorporarse al texto del acuerdo.', null, 'f9c33de33d6647f079b6df0b0676f578922a763fad7d0c1b987082d78a6e07aa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f9c33de33d6647f079b6df0b0676f578922a763fad7d0c1b987082d78a6e07aa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el termini de setanta-dues hores.', true), ('B', 'En el termini de quaranta-vuit hores.', false), ('C', 'En el termini de deu dies.', false), ('D', 'Abans que s''aixequi la sessió.', false)) as v(label, body, ok)
)
