  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cada any.', false), ('B', 'Cada dos anys.', false), ('C', 'Cada quatre anys.', true), ('D', 'Cada cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
