-- Lote pcat-g3-bon-govern-transparencia-igualtat-loi-v1 (2 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g3-bon-govern-transparencia-igualtat', 'Part general. Tema 3. Bon govern, transparència, accés a la informació i igualtat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g3-bon-govern-transparencia-igualtat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei orgànica 3/2007, per a la igualtat efectiva de dones i homes, com es qualifica la situació en què una disposició, un criteri o una pràctica aparentment neutres posen persones d''un sexe en desavantatge particular respecte de persones de l''altre?', 'L''art. 6.2 de la LO 3/2007 defineix la discriminació indirecta per raó de sexe, que no hi ha si la disposició, el criteri o la pràctica es poden justificar objectivament per una finalitat legítima i amb mitjans necessaris i adequats. La directa és el tracte menys favorable en atenció al sexe (art. 6.1).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 6.2 LO 3/2007', 'Se considera discriminación indirecta por razón de sexo la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro, salvo que dicha disposición, criterio o práctica puedan justificarse objetivamente en atención a una finalidad legítima y que los medios para alcanzar dicha finalidad sean necesarios y adecuados.', null, '25614b001d79474b436013ecb7264c3887fdb307393f9889e0432cce11dcace2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '25614b001d79474b436013ecb7264c3887fdb307393f9889e0432cce11dcace2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Discriminació directa per raó de sexe, en tots els casos.', false), ('B', 'Assetjament per raó de sexe.', false), ('C', 'Discriminació indirecta per raó de sexe, llevat que es pugui justificar objectivament en atenció a una finalitat legítima amb mitjans necessaris i adequats.', true), ('D', 'Acció positiva, sempre que sigui temporal.', false)) as v(label, body, ok)
)
