with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 51 de la Llei orgànica 3/2007, en aplicació del principi d''igualtat entre dones i homes, les administracions públiques han de promoure:', 'Entre els criteris d''actuació de l''art. 51 de la LO 3/2007 (de caràcter bàsic) hi ha promoure la presència equilibrada de dones i homes en els òrgans de selecció i valoració (lletra d), i també facilitar la conciliació, fomentar la formació en igualtat i establir mesures contra l''assetjament sexual i per raó de sexe.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 51.d LO 3/2007', 'd) Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración.', null, '0ebf5c0b9322368896165599a3db68d273b21c9bf90637a80c439a9358513172', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0ebf5c0b9322368896165599a3db68d273b21c9bf90637a80c439a9358513172')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que els òrgans de selecció estiguin formats exclusivament per dones.', false), ('B', 'Que els òrgans de selecció estiguin formats exclusivament per personal funcionari del subgrup A1.', false), ('C', 'Una reserva del 50% de les places de cada convocatòria per a cada sexe.', false), ('D', 'La presència equilibrada de dones i homes en els òrgans de selecció i valoració.', true)) as v(label, body, ok)
)
