select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
-- Lote pcat-g4-procediment-pressupost-dlfin-v1 (4 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Decreto Legislativo 3/2002, de 24 de diciembre, texto refundido de la Ley de finanzas públicas de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=DOGC-f-2002-90024', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g4-procediment-pressupost', 'Part general. Tema 4. Procediment administratiu i pressupost de la Generalitat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g4-procediment-pressupost' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret legislatiu 3/2002, text refós de la Llei de finances públiques de Catalunya, el pressupost de la Generalitat constitueix:', 'L''art. 27.1 DL 3/2002 defineix el pressupost com l''expressió quantificada, conjunta i sistemàtica de les obligacions que, com a màxim, es poden reconèixer i dels drets que es poden liquidar en l''exercici. A més, s''ha d''aprovar equilibrat (art. 27.2).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-2002-90024'), 'Art. 27.1 DLFIN', 'El presupuesto de la Generalidad de Cataluña constituye la expresión cuantificada, conjunta y sistemática de las obligaciones que, como máximo, podrán reconocer la Generalidad y las entidades autónomas, y de los derechos que podrán liquidarse durante el ejercicio correspondiente.', null, '81270431343c973c71aae0007a6cedb562f159f6d045cf16fbe27214b740d8fc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '81270431343c973c71aae0007a6cedb562f159f6d045cf16fbe27214b740d8fc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''expressió quantificada, conjunta i sistemàtica de les obligacions que, com a màxim, poden reconèixer la Generalitat i les entitats autònomes, i dels drets que es poden liquidar durant l''exercici.', true), ('B', 'L''expressió quantificada de les obligacions que, com a mínim, ha de reconèixer la Generalitat durant l''exercici.', false), ('C', 'La previsió orientativa dels ingressos i les despeses de la Generalitat, sense caràcter limitatiu.', false), ('D', 'L''expressió quantificada dels drets que es poden liquidar durant un període de quatre exercicis.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el text refós de la Llei de finances públiques de Catalunya, si l''1 de gener el pressupost de la Generalitat no ha estat aprovat:', 'L''art. 33 DL 3/2002 preveu la pròrroga automàtica del pressupost de l''any anterior en els crèdits inicials fins a l''aprovació i publicació del nou al DOGC. La pròrroga no afecta els crèdits de serveis o programes que acabin durant l''exercici prorrogat.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-2002-90024'), 'Art. 33 DLFIN', 'En el supuesto que el 1 de enero, por cualquier motivo, no resultase aprobado el presupuesto, se considerará prorrogado automáticamente el del año anterior en sus créditos iniciales hasta la aprobación y la publicación de los nuevos en el «Diari Oficial de la Generalitat de Catalunya».', null, 'e7498d7579d5ce1acb1d090c7bca1dbbc46a7659368f8fde3ff3dd23564acf0d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e7498d7579d5ce1acb1d090c7bca1dbbc46a7659368f8fde3ff3dd23564acf0d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Govern ha d''aprovar per decret llei un pressupost provisional per a tot l''exercici.', false), ('B', 'Es considera prorrogat el de l''any anterior en els seus crèdits definitius, incloses les modificacions de crèdit.', false), ('C', 'Es considera prorrogat automàticament el de l''any anterior en els seus crèdits inicials fins a l''aprovació i la publicació del nou al DOGC.', true), ('D', 'Només es poden atendre les despeses de personal fins que el Parlament aprovi el nou pressupost.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret legislatiu 3/2002, l''exercici pressupostari coincideix amb l''any natural i s''hi imputen les obligacions reconegudes per despeses fetes abans d''acabar l''exercici:', 'L''art. 28.b) DL 3/2002 imputa a l''exercici les obligacions reconegudes fins al 31 de gener de l''any següent corresponents a despeses fetes abans d''acabar l''exercici amb càrrec als crèdits respectius; els drets s''imputen si es liquiden durant l''any, encara que procedeixin d''exercicis anteriors.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-2002-90024'), 'Art. 28 DLFIN', 'b) Las obligaciones que sean reconocidas hasta el 31 de enero del año siguiente, correspondientes a cualquier tipo de gastos efectuados antes de acabar el ejercicio presupuestario con cargo a los créditos respectivos.', null, '89535b035fa49e2c4e8a359004b78e07340c3bcb464f054e7a4abf3a041b4139', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '89535b035fa49e2c4e8a359004b78e07340c3bcb464f054e7a4abf3a041b4139')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fins al 31 de desembre del mateix any, sense excepcions.', false), ('B', 'Fins al 31 de gener de l''any següent.', true), ('C', 'Fins al 31 de març de l''any següent.', false), ('D', 'Fins al 30 de juny de l''any següent.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
