  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quant a l''estructura del pressupost de la Generalitat, el Decret legislatiu 3/2002 estableix que l''estat de despeses ha de reunir:', 'L''art. 30.2 DL 3/2002 exigeix que l''estat de despeses reuneixi les classificacions orgànica, funcional, econòmica i per programes, i, quan escaigui, la territorial per àmbits comarcals i supracomarcals de les despeses d''inversió.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-2002-90024'), 'Art. 30.2 DLFIN', 'El estado de gastos reunirá la clasificación orgánica, funcional y económica y por programas.', null, 'eab1c00b1f836acf8f8a7125d0482b68f25afe81917008b15410269d87f1f7ff', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'eab1c00b1f836acf8f8a7125d0482b68f25afe81917008b15410269d87f1f7ff')
  returning id
), o as (
