insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g4-procediment-pressupost', 'Part general. Tema 4. Procediment administratiu i pressupost de la Generalitat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g4-procediment-pressupost' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 4 de la Llei 39/2015, del procediment administratiu comú de les administracions públiques (LPAC), les persones que, sense haver iniciat el procediment, tenen interessos legítims que poden resultar afectats per la resolució:', 'L''art. 4.1.c) LPAC considera interessats aquells els interessos legítims dels quals puguin resultar afectats per la resolució i que es personin en el procediment mentre no hagi recaigut resolució definitiva. Els qui tenen drets que poden resultar afectats (lletra b) ho són encara que no hagin iniciat el procediment.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 4.1 LPAC', 'c) Aquellos cuyos intereses legítimos, individuales o colectivos, puedan resultar afectados por la resolución y se personen en el procedimiento en tanto no haya recaído resolución definitiva.', null, '0f2b0e66c290903776aa7fd2bd5585b9bd1956b7e1bb1cc893e69611d4bf3cf1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0f2b0e66c290903776aa7fd2bd5585b9bd1956b7e1bb1cc893e69611d4bf3cf1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Són interessades des de l''inici del procediment, encara que no s''hi personin.', false), ('B', 'Només poden ser interessades si l''Administració les cita expressament abans del tràmit d''audiència.', false), ('C', 'Són interessades si es personen en el procediment mentre no hagi recaigut resolució definitiva.', true), ('D', 'No tenen la condició d''interessades; només ho són els qui promouen el procediment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la LPAC, si una persona interposa un recurs en nom d''una altra sense acreditar suficientment la representació, l''òrgan administratiu ha de concedir un termini per esmenar el defecte de:', 'Segons l''art. 5.6 LPAC, la manca o insuficient acreditació de la representació no impedeix tenir per fet l''acte si s''aporta o s''esmena el defecte dins el termini de deu dies que ha de concedir l''òrgan, o un de superior si les circumstàncies ho requereixen.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 5.6 LPAC', 'La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto de que se trate, siempre que se aporte aquélla o se subsane el defecto dentro del plazo de diez días que deberá conceder al efecto el órgano administrativo, o de un plazo superior cuando las circunstancias del caso así lo requieran.', null, '7cd76548e85975aed7b694d18e191c887351ba61848e0a0977f3935293aa38b2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7cd76548e85975aed7b694d18e191c887351ba61848e0a0977f3935293aa38b2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deu dies, o un termini superior quan les circumstàncies del cas ho requereixin.', true), ('B', 'Cinc dies, improrrogables.', false), ('C', 'Quinze dies hàbils, comptadors des de la presentació del recurs.', false), ('D', 'Un mes, transcorregut el qual s''entén que el recurs no s''ha interposat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 30 de la LPAC, llevat que una llei o el dret de la Unió Europea disposin un altre còmput, quan els terminis s''assenyalen per dies:', 'L''art. 30.2 LPAC estableix que els terminis per dies s''entenen hàbils i n''exclou els dissabtes, els diumenges i els festius. Si una llei fixa dies naturals, s''ha de fer constar a la notificació.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 30.2 LPAC', 'Siempre que por Ley o en el Derecho de la Unión Europea no se exprese otro cómputo, cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos.', null, 'd28093310c8500f80e0f23b53b8901f82b543f9e0125d6579372c49d9dabdad2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd28093310c8500f80e0f23b53b8901f82b543f9e0125d6579372c49d9dabdad2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''entén que són naturals, i només s''exclouen els declarats festius.', false), ('B', 'S''entén que són hàbils, i s''exclouen del còmput els dissabtes, els diumenges i els declarats festius.', true), ('C', 'S''entén que són hàbils, i només s''exclouen del còmput els diumenges i els declarats festius.', false), ('D', 'S''entén que són naturals, llevat que la notificació indiqui expressament que són hàbils.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quant als terminis expressats per hores, la LPAC disposa que:', 'L''art. 30.1 LPAC: les hores són hàbils (totes les d''un dia hàbil), es compten d''hora en hora i de minut en minut des de la notificació o publicació i el termini no pot superar les 24 hores; si les supera, s''ha d''expressar en dies.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 30.1 LPAC', 'Los plazos expresados por horas se contarán de hora en hora y de minuto en minuto desde la hora y minuto en que tenga lugar la notificación o publicación del acto de que se trate y no podrán tener una duración superior a veinticuatro horas, en cuyo caso se expresarán en días.', null, 'f05bcf5427f2a7ef895d5d4016fcae907a0cbe7d4ce990bda9786c10859ce2c6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f05bcf5427f2a7ef895d5d4016fcae907a0cbe7d4ce990bda9786c10859ce2c6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es compten des de la primera hora del dia següent al de la notificació i no poden superar les quaranta-vuit hores.', false), ('B', 'Es compten d''hora en hora i totes les hores del dia són hàbils, encara que el dia sigui inhàbil.', false), ('C', 'No poden tenir una durada superior a setanta-dues hores, cas en què s''expressen en dies naturals.', false), ('D', 'Es compten d''hora en hora i de minut en minut i no poden tenir una durada superior a vint-i-quatre hores, cas en què s''expressen en dies.', true)) as v(label, body, ok)
)
