with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la LPAC, els terminis expressats en dies es comencen a comptar:', 'L''art. 30.3 LPAC fixa l''inici del còmput dels terminis en dies a partir de l''endemà de la notificació o publicació, o de l''endemà de l''estimació o desestimació per silenci administratiu.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 30.3 LPAC', 'Los plazos expresados en días se contarán a partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto de que se trate', null, '238f86748687d95ab7723e1d288861e49828853cd78898bdc058ad818b71c631', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '238f86748687d95ab7723e1d288861e49828853cd78898bdc058ad818b71c631')
  returning id
), o as (
