select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una resolució es notifica a una persona interessada el 31 de gener i li atorga un termini d''un mes per formular al·legacions. Segons la LPAC, i suposant que tots els dies afectats són hàbils, el termini venç:', 'L''art. 30.4 LPAC disposa que el termini en mesos conclou el mateix dia en què es va produir la notificació en el mes de venciment; si en aquest mes no hi ha dia equivalent (31 de febrer), el termini expira l''últim dia del mes.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 30.4 LPAC', 'El plazo concluirá el mismo día en que se produjo la notificación, publicación o silencio administrativo en el mes o el año de vencimiento. Si en el mes de vencimiento no hubiera día equivalente a aquel en que comienza el cómputo, se entenderá que el plazo expira el último día del mes.', null, '126c2cddb93f874883ef04ee38962547b646dd59cfef8b007b8164bb2df19808', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '126c2cddb93f874883ef04ee38962547b646dd59cfef8b007b8164bb2df19808')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''últim dia del mes de febrer.', true), ('B', 'El 2 de març.', false), ('C', 'El 3 de març, en comptar trenta dies naturals.', false), ('D', 'El primer dia hàbil del mes de març.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, quan l''últim dia d''un termini és inhàbil:', 'L''art. 30.5 LPAC preveu que, si l''últim dia del termini és inhàbil, s''entén prorrogat al primer dia hàbil següent.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 30.5 LPAC', 'Cuando el último día del plazo sea inhábil, se entenderá prorrogado al primer día hábil siguiente.', null, '86535a44842b38b0f36590813230690fc4800f16dd33803249f131735360381a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '86535a44842b38b0f36590813230690fc4800f16dd33803249f131735360381a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El termini venç igualment aquell dia.', false), ('B', 'El termini venç el darrer dia hàbil anterior.', false), ('C', 'S''entén prorrogat tres dies hàbils més.', false), ('D', 'S''entén prorrogat al primer dia hàbil següent.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un dia és festiu al municipi on resideix la persona interessada, però és hàbil a la seu de l''òrgan administratiu que tramita el procediment. Segons l''article 30 de la LPAC, a efectes del còmput de terminis aquest dia:', 'L''art. 30.6 LPAC estableix que, quan un dia és hàbil al municipi o comunitat autònoma de residència de l''interessat i inhàbil a la seu de l''òrgan, o a la inversa, es considera inhàbil en tot cas.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 30.6 LPAC', 'Cuando un día fuese hábil en el municipio o Comunidad Autónoma en que residiese el interesado, e inhábil en la sede del órgano administrativo, o a la inversa, se considerará inhábil en todo caso.', null, '3eccaeba085ce3b1c0d0d0e539686566b9b601638e9536fbb3c2c0d8a2a7a3c2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3eccaeba085ce3b1c0d0d0e539686566b9b601638e9536fbb3c2c0d8a2a7a3c2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es considera hàbil, perquè preval el calendari de la seu de l''òrgan.', false), ('B', 'Es considera inhàbil en tot cas.', true), ('C', 'Es considera hàbil si el procediment s''ha iniciat d''ofici i inhàbil si s''ha iniciat a sol·licitud de la persona interessada.', false), ('D', 'Es considera hàbil, llevat que la persona interessada acrediti que no ha pogut presentar la documentació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Pel que fa a l''ampliació dels terminis prevista a l''article 32 de la LPAC, quina de les afirmacions següents NO és correcta?', 'L''art. 32 LPAC permet ampliar els terminis, d''ofici o a petició, fins a la meitat, i l''acord s''ha de notificar (32.1). La petició i la decisió s''han de produir abans del venciment: en cap cas es pot ampliar un termini ja vençut, i els acords d''ampliació o denegació no són recurribles (32.3).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 32 LPAC', 'una ampliación de los plazos establecidos, que no exceda de la mitad de los mismos, si las circunstancias lo aconsejan y con ello no se perjudican derechos de tercero. El acuerdo de ampliación deberá ser notificado a los interesados. […] En ningún caso podrá ser objeto de ampliación un plazo ya vencido. Los acuerdos sobre ampliación de plazos o sobre su denegación no serán susceptibles de recurso', null, '9e942c682203b5cccfa6d83776e15ad38a59d9b314947a7dac519b3afc307150', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9e942c682203b5cccfa6d83776e15ad38a59d9b314947a7dac519b3afc307150')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''ampliació no pot excedir la meitat del termini establert.', false), ('B', 'L''acord d''ampliació s''ha de notificar a les persones interessades.', false), ('C', 'Es pot ampliar un termini ja vençut si la persona interessada ho sol·licita de manera motivada.', true), ('D', 'Els acords sobre ampliació de terminis o sobre la seva denegació no són susceptibles de recurs.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quan s''acorda la tramitació d''urgència d''un procediment per raons d''interès públic, segons la LPAC, quins terminis NO es redueixen a la meitat?', 'L''art. 33.1 LPAC redueix a la meitat els terminis del procediment ordinari en la tramitació d''urgència, llevat dels relatius a la presentació de sol·licituds i recursos. L''acord d''urgència no és recurrible (art. 33.2).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 33 LPAC', 'por la cual se reducirán a la mitad los plazos establecidos para el procedimiento ordinario, salvo los relativos a la presentación de solicitudes y recursos.', null, 'e44ef508ce74037306db5afcadbb923838d4aeb6adcbbde3ebc4db973dc96505', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e44ef508ce74037306db5afcadbb923838d4aeb6adcbbde3ebc4db973dc96505')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els del tràmit d''audiència a les persones interessades.', false), ('B', 'Els relatius a la presentació de sol·licituds i recursos.', true), ('C', 'Els de la pràctica de la prova.', false), ('D', 'Els de l''emissió d''informes preceptius.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, quan les normes reguladores d''un procediment no fixen el termini màxim per notificar la resolució expressa, aquest termini és de:', 'L''art. 21.3 LPAC fixa en tres mesos el termini màxim supletori. Amb caràcter general, el que fixi la norma reguladora no pot superar els sis mesos, llevat que una norma amb rang de llei o el dret de la UE en prevegi un de més llarg (art. 21.2).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 21.2-3 LPAC', 'Cuando las normas reguladoras de los procedimientos no fijen el plazo máximo, éste será de tres meses.', null, '17b4e7093e8fb9f4d68703ea500f71104195da75bd3bc2e7d52b81a800d1bed0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '17b4e7093e8fb9f4d68703ea500f71104195da75bd3bc2e7d52b81a800d1bed0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres mesos.', true), ('B', 'Sis mesos.', false), ('C', 'Un mes.', false), ('D', 'Dos mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 40 de la LPAC, tota notificació s''ha de cursar dins el termini de:', 'L''art. 40.2 LPAC exigeix cursar la notificació en deu dies des que es dicta l''acte, amb el text íntegre, la indicació de si posa fi a la via administrativa i els recursos procedents, l''òrgan i el termini.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 40.2 LPAC', 'Toda notificación deberá ser cursada dentro del plazo de diez días a partir de la fecha en que el acto haya sido dictado', null, '2a30e45b4f2975ea102cb32b3641614eea8749692f506cf31c055a02bc503c8e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2a30e45b4f2975ea102cb32b3641614eea8749692f506cf31c055a02bc503c8e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinc dies a partir de la data en què l''acte s''hagi dictat.', false), ('B', 'Quinze dies a partir de la data en què l''acte s''hagi dictat.', false), ('C', 'Un mes a partir de la data en què l''acte s''hagi dictat.', false), ('D', 'Deu dies a partir de la data en què l''acte s''hagi dictat.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 47 de la LPAC, quin dels actes següents NO és nul de ple dret?', 'El contingut impossible, la incompetència manifesta per raó de la matèria o del territori i la infracció penal són causes de nul·litat de ple dret (art. 47.1.b, c i d LPAC). La desviació de poder és causa d''anul·labilitat (art. 48.1 LPAC).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Arts. 47.1 i 48.1 LPAC', 'Son anulables los actos de la Administración que incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder.', null, '41ded34a20c510a46a15ead56cf6fdf116819efe07c46e1c1799a02bb7b75651', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '41ded34a20c510a46a15ead56cf6fdf116819efe07c46e1c1799a02bb7b75651')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''acte que té un contingut impossible.', false), ('B', 'L''acte dictat amb desviació de poder.', true), ('C', 'L''acte dictat per un òrgan manifestament incompetent per raó de la matèria o del territori.', false), ('D', 'L''acte constitutiu d''infracció penal o dictat com a conseqüència d''aquesta.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la LPAC, un defecte de forma només determina l''anul·labilitat de l''acte quan:', 'L''art. 48.2 LPAC limita l''anul·labilitat per defecte de forma als casos en què falten requisits formals indispensables per assolir la finalitat o es causa indefensió. Prescindir totalment del procediment és causa de nul·litat (art. 47.1.e) i l''actuació fora de termini només comporta anul·labilitat quan ho imposa la naturalesa del termini (art. 48.3).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 48.2 LPAC', 'No obstante, el defecto de forma sólo determinará la anulabilidad cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados.', null, 'b3c63cd589647b859ddd52adf4d2096dfea146addb86a3fee86d7b8e477225d2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b3c63cd589647b859ddd52adf4d2096dfea146addb86a3fee86d7b8e477225d2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''acte no té els requisits formals indispensables per assolir la seva finalitat o dona lloc a la indefensió de les persones interessades.', true), ('B', 'L''acte s''ha dictat prescindint totalment i absolutament del procediment legalment establert.', false), ('C', 'La persona interessada ho al·lega en el termini de deu dies des de la notificació.', false), ('D', 'L''acte s''ha dictat fora del termini establert, sigui quina sigui la naturalesa d''aquest termini.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, la declaració de lesivitat d''un acte favorable anul·lable no es pot adoptar un cop transcorreguts:', 'L''art. 107.2 LPAC fixa el límit de quatre anys des que es va dictar l''acte i exigeix l''audiència prèvia dels interessats. Els sis mesos es refereixen a la caducitat del procediment de lesivitat (art. 107.3).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 107.2 LPAC', 'La declaración de lesividad no podrá adoptarse una vez transcurridos cuatro años desde que se dictó el acto administrativo', null, 'b89ad85102b08c6cc41b215d21a71fa53e65d8013692f47693b346846b8c91b6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b89ad85102b08c6cc41b215d21a71fa53e65d8013692f47693b346846b8c91b6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sis mesos des que es va dictar l''acte administratiu.', false), ('B', 'Quatre anys des que es va dictar l''acte administratiu.', true), ('C', 'Dos anys des que es va notificar l''acte administratiu.', false), ('D', 'Cinc anys des que l''acte va esdevenir ferm.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la LPAC, si l''acte és exprés, el termini per interposar el recurs d''alçada és de:', 'L''art. 122.1 LPAC fixa el termini d''un mes per a l''alçada contra actes expressos; transcorregut, la resolució és ferma. El termini màxim per resoldre-la i notificar-la és de tres mesos (art. 122.2).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 122 LPAC', 'El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso.', null, '8e64c54fe8f15c80f2ed64003c53a25c2156d96bad6d4e07acce5619513eda6e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8e64c54fe8f15c80f2ed64003c53a25c2156d96bad6d4e07acce5619513eda6e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quinze dies hàbils.', false), ('B', 'Dos mesos.', false), ('C', 'Un mes.', true), ('D', 'Tres mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, el recurs potestatiu de reposició:', 'Els actes que posen fi a la via administrativa es poden recórrer potestativament en reposició davant el mateix òrgan que els va dictar o impugnar directament davant la jurisdicció contenciosa (art. 123.1 LPAC). El termini màxim per resoldre i notificar és d''un mes (art. 124.2).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 123-124 LPAC', 'Los actos administrativos que pongan fin a la vía administrativa podrán ser recurridos potestativamente en reposición ante el mismo órgano que los hubiera dictado […] El plazo máximo para dictar y notificar la resolución del recurso será de un mes.', null, '6e26d85d7e935a5991a34a5ffeaf433b2b9edb0f9dc3f8f01eca2f68931fa0a7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6e26d85d7e935a5991a34a5ffeaf433b2b9edb0f9dc3f8f01eca2f68931fa0a7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''interposa davant l''òrgan superior jeràrquic del que va dictar l''acte, i s''ha de resoldre en tres mesos.', false), ('B', 'S''interposa davant el mateix òrgan que va dictar l''acte, i s''ha de resoldre en tres mesos.', false), ('C', 'És obligatori abans d''acudir a la jurisdicció contenciosa administrativa i s''ha de resoldre en un mes.', false), ('D', 'S''interposa davant el mateix òrgan que va dictar l''acte, i el termini màxim per dictar-ne i notificar-ne la resolució és d''un mes.', true)) as v(label, body, ok)
)
