  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Direcció General de Funció Pública.', false), ('B', 'Els secretaris generals.', true), ('C', 'Els directors dels centres de treball.', false), ('D', 'El Govern de la Generalitat.', false)) as v(label, body, ok)
)
