insert into public.topics (slug, title) values ('pcat-g5-funcio-publica', 'Part general. Tema 5. La funció pública: drets i deures, situacions, provisió, incompatibilitats i règim disciplinari') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g5-funcio-publica' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 243/1995, pel qual s''aprova el Reglament de règim disciplinari de la funció pública de l''Administració de la Generalitat, quina de les conductes següents NO és una falta molt greu?', 'L''art. 3 del Decret 243/1995 qualifica de molt greus, entre d''altres, l''abandonament del servei (c), l''incompliment de les normes sobre incompatibilitats (h) i haver estat sancionat per tres faltes greus en un any (o). L''abús d''autoritat és una falta greu (art. 4.b).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Arts. 3 i 4 D243', 'c) L''abandonament del servei. […] h) L''incompliment de les normes sobre incompatibilitats. […] o) El fet d''haver estat sancionat per la comissió de tres faltes greus en el període d''un any. […] b) L''abús d''autoritat en l''exercici del càrrec.', null, 'a0c99789d0b5a2d21f552251ab27708baa0a8189ece767ebfa8c38416a909eb1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a0c99789d0b5a2d21f552251ab27708baa0a8189ece767ebfa8c38416a909eb1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''abús d''autoritat en l''exercici del càrrec.', true), ('B', 'L''incompliment de les normes sobre incompatibilitats.', false), ('C', 'L''abandonament del servei.', false), ('D', 'El fet d''haver estat sancionat per la comissió de tres faltes greus en el període d''un any.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 243/1995, quin òrgan imposa les sancions per faltes molt greus?', 'L''art. 52.1 del Decret 243/1995 atribueix les sancions per faltes lleus als secretaris generals, directors generals o assimilats; per faltes greus, al secretari general del departament; i per faltes molt greus, al titular del departament.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Art. 52.1 D243', 'c) Les sancions per faltes molt greus seran imposades pel titular del departament o del qual depèn l''organisme o entitat on presta serveis el funcionari responsable', null, 'a1ff2ca280caf273563f32ee52260ce1f490ef11bb1b7fa8877ed718f49ec376', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a1ff2ca280caf273563f32ee52260ce1f490ef11bb1b7fa8877ed718f49ec376')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
