with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el procediment disciplinari ordinari regulat pel Decret 243/1995, un cop notificat el plec de càrrecs, el funcionari inculpat disposa d''un termini per presentar al·legacions i aportar documents de:', 'L''art. 46.3 del Decret 243/1995 dona deu dies a l''inculpat per al·legar i aportar documents contra el plec de càrrecs, i hi pot proposar proves. Els cinc dies corresponen a les al·legacions en el procediment sumari per faltes lleus (art. 34).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Art. 46.3 D243', 'El plec de càrrecs es notificarà a l''inculpat, el qual disposarà d''un termini de deu dies per a presentar les al·legacions i aportar els documents que cregui convenients en la seva defensa.', null, '154b166bff965f9ab718a65d638f44130cde9f0d235361e4d2fa1a266239b527', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '154b166bff965f9ab718a65d638f44130cde9f0d235361e4d2fa1a266239b527')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deu dies.', true), ('B', 'Cinc dies.', false), ('C', 'Quinze dies.', false), ('D', 'Un mes.', false)) as v(label, body, ok)
)
