with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 54 del TREBEP, pel que fa a la llengua, els empleats públics:', 'L''art. 54.11 TREBEP inclou entre els principis de conducta garantir l''atenció al ciutadà en la llengua que sol·liciti sempre que sigui oficial en el territori.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 54.11 TREBEP', 'Garantizarán la atención al ciudadano en la lengua que lo solicite siempre que sea oficial en el territorio.', null, '6f2e62b1b67df944885bc953237e3ef365669ea5090f25e4a06e801e0d4e7c61', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6f2e62b1b67df944885bc953237e3ef365669ea5090f25e4a06e801e0d4e7c61')
  returning id
), o as (
