insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s1-ingres-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El funcionari del departament d''ingressos rep l''intern P.N., que ingressa al centre amb un manament de presó. Segons la Circular 1/2008, sobre escorcolls, l''escorcoll amb despullament en aquest moment s''ha de fer…', 'L''apartat 1.2.1 de la Circular 1/2008 estableix que l''escorcoll amb despullament s''ha de fer sistemàticament quan l''intern ingressa al centre, d''acord amb l''art. 18.1 RP; en canvi, en els retorns de permís i en les comunicacions especials cal una motivació específica.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.2.1', 'Sistemàticament, quan l’intern ingressa al centre d’acord amb l’article 18.1 del Reglament Penitenciari.', null, '5bee6a82c4a7e5f6a5e0ef54cf4a7b11777e6c1081ec9a537b6d094159da3b93', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5bee6a82c4a7e5f6a5e0ef54cf4a7b11777e6c1081ec9a537b6d094159da3b93')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'només si hi ha sospites fonamentades que porta substàncies o objectes prohibits.', false), ('B', 'només amb l''autorització prèvia del jutjat de guàrdia.', false), ('C', 'de manera aleatòria, segons el pla de seguretat del centre.', false), ('D', 'sistemàticament, d''acord amb l''article 18.1 del Reglament penitenciari.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cal practicar un escorcoll amb nu integral a l''intern G.L. i el cap de serveis de torn no hi pot ser present per causes objectives. Segons la Circular 1/2008, què s''ha de fer?', 'Segons l''apartat 1.2.3 de la Circular 1/2008, l''escorcoll amb nu integral es fa sota la supervisió i presència d''un cap de serveis del mateix gènere que la persona interna; si no hi pot ser present, ho delega en el cap d''unitat del departament o en un altre que designi (o, si no n''hi ha, en el funcionari que consideri convenient), però el cap de serveis en continua essent el responsable.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.2.3', 'Si un cap de serveis no pogués objectivament estar present ho delegarà en el cap d’unitat del departament corresponent o en un altre que designi, i en el cas que no n’hi hagués, ho delegarà al funcionari que estimi convenient, essent el cap de serveis responsable de la supervisió o tutela de l’escorcoll efectuat.', null, '7aa62463e1c7566d4f86263b143d0dffa244763d712b00ccf2b2494f2818ef71', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7aa62463e1c7566d4f86263b143d0dffa244763d712b00ccf2b2494f2818ef71')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El cap de serveis ho delega en el cap d''unitat del departament o en un altre que designi, i continua essent responsable de la supervisió de l''escorcoll.', true), ('B', 'El cap de serveis ho delega en el subdirector d''interior, que n''assumeix tota la responsabilitat.', false), ('C', 'L''escorcoll s''ha d''ajornar fins que hi hagi un cap de serveis que hi pugui ser present.', false), ('D', 'L''escorcoll el fa el funcionari més antic del departament, que n''assumeix la responsabilitat exclusiva.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Durant l''escorcoll amb nu integral de l''intern O.R., practicat d''acord amb la Circular 1/2008, quina de les actuacions següents NO és correcta?', 'L''apartat 1.2.2 de la Circular 1/2008 estableix que aquests escorcolls no han d''anar acompanyats de flexions i s''han de fer de manera individual, fora de la mirada de terceres persones; l''apartat 1.2.4 preveu que l''intern es tregui ell mateix la roba i que, feta la inspecció visual, se li lliuri una bata.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartats 1.2.2 i 1.2.4', 'Aquests escorcolls, que no han d’anar acompanyats de flexions, han de ser duts a terme per personal del mateix sexe que el de la persona que s’ha d’escorcollar, en la màxima intimitat i de manera individual, fora de l’abast de la mirada de terceres persones […] L’intern/interna es traurà ell mateix a les ordres dels/de les funcionaris/àries les peces de roba i les lliurarà per al seu control. […] un cop s’hagi fet una inspecció visual del cos de l’intern s’haurà de lliurar a l’intern una bata per tal que es vesteixi mentre dura l’escorcoll', null, '69187262d7758a019a00317301b4eaa03d43b5a8d537fad9e636cb174e7fa572', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '69187262d7758a019a00317301b4eaa03d43b5a8d537fad9e636cb174e7fa572')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que l''intern es tregui ell mateix la roba a les ordres dels funcionaris i la lliuri per al control.', false), ('B', 'Ordenar-li que faci flexions per comprovar que no amaga res a les cavitats corporals.', true), ('C', 'Lliurar-li una bata un cop feta la inspecció visual del cos, perquè es vesteixi mentre dura l''escorcoll.', false), ('D', 'Fer l''escorcoll de manera individual, fora de l''abast de la mirada de terceres persones.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Acabat l''escorcoll amb nu integral de l''intern H.S., els funcionaris n''han de deixar constància per escrit. Segons la Circular 1/2008, qui signa els comunicats i a qui s''adrecen?', 'Segons l''apartat 1.3 de la Circular 1/2008 (i l''art. 68.5 RP), dels escorcolls s''han de fer comunicats signats pels funcionaris que els han fet i adreçats al cap de serveis, amb el nom de l''intern, el lloc i la data, el cap de serveis present o la persona delegada, la motivació i el resultat.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.3', 'Dels escorcolls que es facin, s’han de fer comunicats, que han de signar els funcionaris que els hagin portat a terme i que s’han d’adreçar al cap de serveis.', null, 'b0b2f800ecaf9d429704767ad30ecb1cb64a131884c3145c8005e3157fd6b298', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b0b2f800ecaf9d429704767ad30ecb1cb64a131884c3145c8005e3157fd6b298')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els signa el cap de serveis i s''adrecen al director.', false), ('B', 'Els signa el director i s''adrecen al jutge de vigilància penitenciària.', false), ('C', 'Els signen els funcionaris que han fet l''escorcoll i s''adrecen al cap de serveis.', true), ('D', 'Els signa el cap d''unitat i s''adrecen al subdirector d''interior.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''escorcoll amb nu integral de l''intern W.F. ha estat infructuós, però persisteix la sospita fonamentada que porta droga a l''interior del cos. L''intern no accepta voluntàriament una prova radiològica. Segons la Circular 1/2008, què cal per poder-la practicar?', 'L''apartat 1.4 de la Circular 1/2008 disposa que, llevat que l''intern ho accepti voluntàriament, per a les proves radiològiques sempre cal que el jutjat de guàrdia autoritzi la proposta formulada prèviament per la direcció del centre, que ha d''expressar motivadament l''excepcionalitat, la necessitat i la proporcionalitat.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.4', 'Pel que fa a les proves radiològiques, excepte en els casos que l’intern ho accepti voluntàriament, sempre és necessari que el jutjat de guàrdia autoritzi la proposta formulada prèviament per la direcció del centre', null, '4e947be7e56e31161c0baf73c2e4e0ca386f4f5dde49c8e2dcf92937957aaa8b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4e947be7e56e31161c0baf73c2e4e0ca386f4f5dde49c8e2dcf92937957aaa8b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que l''autoritzi el cap de serveis mitjançant una ordre motivada.', false), ('B', 'Que l''acordi el metge del centre segons el seu criteri clínic.', false), ('C', 'Que l''autoritzi el subdirector d''interior, donant-ne compte al jutge de vigilància.', false), ('D', 'Que el jutjat de guàrdia autoritzi la proposta formulada prèviament i de manera motivada per la direcció del centre.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern Z.P. torna d''un permís ordinari de sortida. No consta cap informació específica sobre ell. Segons la Circular 1/2008, l''escorcoll amb nu integral en el retorn de permís…', 'Segons l''apartat 1.2.1 de la Circular 1/2008, en els ingressos de permís cal tenir en compte la situació concreta del centre i el comportament anterior de l''intern; la mesura ha d''estar justificada i motivada, i aquests escorcolls en cap cas no s''han de fer de manera aleatòria.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.2.1', 'En els supòsits d’ingrés de permís cal tenir en compte la situació concreta del centre i el comportament anterior de l’intern. […] Cal que la mesura sigui justificada racionalment i fonamentada; aquests escorcolls han d’estar motivats i en cap cas no s’han de fer de manera aleatòria.', null, 'dc5d0048829466126c60490bab00d95dee3663c8abc41e4b9e3ef5d3baa714b4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dc5d0048829466126c60490bab00d95dee3663c8abc41e4b9e3ef5d3baa714b4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 's''ha de practicar sempre, de manera sistemàtica, a tots els interns que tornen de permís.', false), ('B', 'ha de tenir en compte la situació del centre i el comportament anterior de l''intern, ha d''estar motivat i en cap cas no es pot fer de manera aleatòria.', true), ('C', 'es pot fer per sorteig entre els interns que tornen de permís el mateix dia.', false), ('D', 'està prohibit en tots els casos de retorn de permís.', false)) as v(label, body, ok)
)
