-- Lote pcatsup-s1-ingres-seguretat-circ_1_2022-v1 (1 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Circular 1/2022 sobre contencions (mitjans coercitius) als centres penitenciaris de Catalunya', 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular-1-2022-contencions.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament de Justícia', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcatsup-s1-ingres-seguretat', 'Supòsit pràctic I. Ingressos, seguretat, escorcolls i mitjans coercitius') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s1-ingres-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La interna R.A., embarassada de cinc mesos, crida i dona cops a la porta de la cel·la, però la seva conducta no posa en perill imminent la integritat de ningú. Segons la Circular 1/2022, que recull els articles 72.2 i 254.3 del RP, se li poden aplicar mitjans coercitius?', 'La Circular 1/2022, en aplicació dels arts. 72.2 i 254.3 RP, recorda que els mitjans coercitius no es poden aplicar als malalts convalescents de malaltia greu, a les dones gestants, a les que fa menys de sis mesos que han acabat l''embaràs, a les mares lactants ni a les que tenen fills amb elles, llevat que pugui derivar-se''n un perill imminent per a la integritat de la persona interna o d''altres.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular-1-2022-contencions.pdf'), 'Circular 1/2022, justificació normativa (arts. 72.2 i 254.3 RP)', 'els mitjans coercitius no es poden aplicar als malalts convalescents d’una malaltia greu, a les dones gestants, a les dones l’embaràs de les quals faci menys de sis mesos que hagi acabat, a les mares lactants ni a les que tinguin fills amb elles, llevat dels casos en què pugui derivar un perill imminent per a la integritat de la persona interna o la d’altres persones.', null, '28a647494f934cca40acb2a792eea094c374e68fca091db46991e6c0a09522a4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '28a647494f934cca40acb2a792eea094c374e68fca091db46991e6c0a09522a4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, sempre que ho autoritzi el director.', false), ('B', 'Sí, però només l''aïllament provisional i no la contenció mecànica.', false), ('C', 'Sí, si ho autoritza prèviament el jutge de vigilància penitenciària.', false), ('D', 'No, llevat dels casos en què pugui derivar-se un perill imminent per a la seva integritat o la d''altres persones.', true)) as v(label, body, ok)
)
