select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
-- Lote pcatsup-s1-ingres-seguretat-d329-v1 (1 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Decret 329/2006, de 5 de setembre, pel qual s''aprova el Reglament d''organització i funcionament dels serveis d''execució penal a Catalunya (DOGC núm. 4714, 07/09/2006)', 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252', 'diario_autonomico'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcatsup-s1-ingres-seguretat', 'Supòsit pràctic I. Ingressos, seguretat, escorcolls i mitjans coercitius') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s1-ingres-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un diumenge a la nit cal decidir sobre l''aplicació d''un mitjà coercitiu a l''intern U.M. El director no és al centre i el subdirector de tractament fa el torn d''incidències. Segons el Decret 329/2006, quines atribucions té aquest subdirector durant el torn?', 'L''art. 19.2 del Decret 329/2006 disposa que, quan fan el torn d''incidències, els subdirectors i càrrecs assimilats assumeixen totes les atribucions del director, a qui han de donar compte de les actuacions fetes tan aviat com sigui possible.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 19.2 Decret 329/2006', 'Quan facin el torn d''incidències, els/les subdirectors/es i els càrrecs assimilats assumiran totes les atribucions del/de la director/a, a qui hauran de donar compte de les actuacions fetes en l''exercici d''aquestes atribucions, tan aviat com sigui possible.', null, 'e995242ce81d956a62bf984104d738cdd30f7c07bd1efb15c97293cb7921555b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e995242ce81d956a62bf984104d738cdd30f7c07bd1efb15c97293cb7921555b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cap en aquesta matèria, perquè només el director pot autoritzar mitjans coercitius.', false), ('B', 'Només les pròpies de la subdirecció de tractament.', false), ('C', 'Assumeix totes les atribucions del director, a qui n''ha de donar compte tan aviat com sigui possible.', true), ('D', 'Les del director, però cada actuació l''ha de ratificar el centre directiu en vint-i-quatre hores.', false)) as v(label, body, ok)
)
