select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
-- Lote pcatsup-s1-ingres-seguretat-logp-v1 (1 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 1/1979, de 26 de septiembre, General Penitenciaria (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcatsup-s1-ingres-seguretat', 'Supòsit pràctic I. Ingressos, seguretat, escorcolls i mitjans coercitius') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s1-ingres-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una nit, l''intern V.Q. intenta agredir un company de cel·la i els funcionaris l''han de reduir amb força física i manilles sense temps per demanar autorització. Segons la Llei orgànica general penitenciària (LOGP), què s''ha de fer?', 'L''art. 45.2 LOGP disposa que, quan per urgència s''hagin d''utilitzar els mitjans coercitius sense autorització prèvia, s''ha de comunicar immediatament al director, el qual ho ha de posar en coneixement del jutge de vigilància.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 45.2 LOGP', 'Cuando, ante la urgencia de la situación, se tuviere que hacer uso de tales medios se comunicará inmediatamente al director, el cual lo pondrá en conocimiento del Juez de Vigilancia.', null, '3bcd7de3cfe4fb3a586fe2334dea1577563317c37d8600b646a11b7672d11728', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3bcd7de3cfe4fb3a586fe2334dea1577563317c37d8600b646a11b7672d11728')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Comunicar-ho al cap de serveis, que ho ha de notificar al jutge de guàrdia en vint-i-quatre hores.', false), ('B', 'Res més, perquè en els casos d''urgència no cal cap comunicació.', false), ('C', 'Comunicar-ho immediatament al director, que ho ha de posar en coneixement del jutge de vigilància.', true), ('D', 'Comunicar-ho al centre directiu, que ho ha de convalidar en setanta-dues hores.', false)) as v(label, body, ok)
)
