insert into public.sources (title, url, kind, publisher, published_on) values ('Circular 2/2017, del règim tancat en els centres penitenciaris de Catalunya', 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament de Justícia', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcatsup-s2-classificacio-comunicacions', 'Supòsit pràctic II. Classificació, règim tancat, comunicacions, trasllats i permisos') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s2-classificacio-comunicacions' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern I.K. ha estat destinat al DERT en la modalitat de vida de l''article 93 del RP per un estat d''agressivitat extrema que fa preveure que no es podrà adaptar immediatament a les activitats de grup. Segons la Circular 2/2017, quina durada màxima pot tenir el període inicial d''adaptació i quin mínim de pati se li ha de garantir?', 'La Circular 2/2017 (apartat V.2.1.a) fixa per a la modalitat de l''art. 93 un mínim de 6 hores diàries fora de la cel·la, però permet un període inicial d''adaptació de 15 dies com a màxim, durant el qual es garanteixen 3 hores diàries de pati i 2 hores setmanals d''atenció individualitzada.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat V.2.1.a)', 'es podrà establir un període inicial d’adaptació al règim tancat d’una durada màxima de 15 dies durant el qual es garantirà el mínim diari de 3 hores de pati i 2 hores setmanals d’atenció individualitzada.', null, '24de2025321df98280d88eb376e7eadcdfe44c2be239bd36db135d5b0d1832fd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '24de2025321df98280d88eb376e7eadcdfe44c2be239bd36db135d5b0d1832fd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quinze dies, amb un mínim de tres hores diàries de pati i dues hores setmanals d''atenció individualitzada.', true), ('B', 'Quaranta-cinc dies, amb un mínim de dues hores diàries de pati.', false), ('C', 'Un mes, amb un mínim de quatre hores diàries de pati.', false), ('D', 'Quinze dies, amb un mínim de sis hores diàries de pati.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern J.L. compleix el règim tancat en la modalitat de vida de l''article 93 del RP. Segons la Circular 2/2017, quin és el període màxim de revisió d''aquesta modalitat de vida?', 'L''apartat V.2.2 de la Circular 2/2017 fixa un període de revisió màxim de 45 dies per a la modalitat de vida de l''art. 93 RP, moment en què s''estudia si es manté o es reassigna l''intern a la modalitat de l''art. 94.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat V.2.2', 'El període de revisió màxim és de 45 dies, moment en què s’estudiarà la conveniència de mantenir aquesta modalitat de vida o fer una reassignació a la prevista a l’article 94 del RP.', null, '2ddbf8f37d58f044c691a0cc2b23ccac186709139dda4dbfb56962deafb47e01', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2ddbf8f37d58f044c691a0cc2b23ccac186709139dda4dbfb56962deafb47e01')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quinze dies.', false), ('B', 'Un mes.', false), ('C', 'Sis mesos.', false), ('D', 'Quaranta-cinc dies.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Junta de Tractament acorda proposar la regressió a primer grau de l''intern K.M. després d''una agressió greu a un company. Segons la Circular 2/2017, en quin termini màxim s''han d''elevar la proposta i els informes, i quan s''ha de revisar la regressió?', 'Segons l''apartat IV.2 de la Circular 2/2017, la proposta de regressió i els informes s''han d''elevar en un termini màxim de 10 dies i per via telemàtica (art. 32.3 del Decret 329/2006), i la Junta de Tractament ha de revisar la regressió, com a màxim, al cap de 3 mesos de la resolució.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat IV.2', 'En tot cas, la proposta i els informes s’han d’elevar en el termini màxim de 10 dies i per via telemàtica d’acord amb l’article 32.3 del ROFSEPC. La regressió l’haurà de revisar la Junta de Tractament, com a màxim, al cap de 3 mesos de la data de la resolució.', null, '8a6e9e25ac89a47720a4d630d0a6cc1e05cc15ad4ea650568452d1251b8ce2f0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8a6e9e25ac89a47720a4d630d0a6cc1e05cc15ad4ea650568452d1251b8ce2f0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En setanta-dues hores; la regressió s''ha de revisar cada sis mesos.', false), ('B', 'En deu dies i per via telemàtica; la Junta de Tractament ha de revisar la regressió com a màxim al cap de tres mesos de la data de la resolució.', true), ('C', 'En catorze dies; la regressió s''ha de revisar al cap de quaranta-cinc dies.', false), ('D', 'En dos mesos; la regressió s''ha de revisar cada any.', false)) as v(label, body, ok)
)
