insert into public.sources (title, url, kind, publisher, published_on) values ('Decret 329/2006, de 5 de setembre, pel qual s''aprova el Reglament d''organització i funcionament dels serveis d''execució penal a Catalunya (DOGC núm. 4714, 07/09/2006)', 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252', 'diario_autonomico'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcatsup-s2-classificacio-comunicacions', 'Supòsit pràctic II. Classificació, règim tancat, comunicacions, trasllats i permisos') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s2-classificacio-comunicacions' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Després de diversos incidents greus protagonitzats pel penat L.N., l''equip multidisciplinari considera que concorren els supòsits de l''article 10 de la LOGP. Segons el Decret 329/2006, quin òrgan proposa al centre directiu l''aplicació del règim tancat i amb quins informes previs?', 'L''art. 32.1.c) del Decret 329/2006 atribueix a la Junta de Tractament la funció de proposar al centre directiu l''aplicació del règim tancat als penats i preventius, amb els informes preceptius previs del cap de serveis i de l''equip multidisciplinari de la unitat residencial.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 32.1.c) Decret 329/2006', 'Proposar al centre directiu l''aplicació del règim tancat als/a les penats/ades i preventius/ives en els/les quals concorrin les circumstàncies previstes per la legislació penitenciària, amb els informes preceptius previs del/de la cap de serveis i de l''equip multidisciplinari de la unitat residencial que correspongui.', null, '169b1a4b3878f6c87eeffbe0905cd47072ec75a437aa230c25b3ab0d1a2d9862', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '169b1a4b3878f6c87eeffbe0905cd47072ec75a437aa230c25b3ab0d1a2d9862')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Junta de Tractament, amb els informes preceptius previs del cap de serveis i de l''equip multidisciplinari de la unitat residencial.', true), ('B', 'La Comissió Disciplinària, amb l''informe previ del subdirector d''interior.', false), ('C', 'El Consell de Direcció, amb l''informe previ dels serveis mèdics.', false), ('D', 'El director, amb l''informe previ del jutge de vigilància penitenciària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Les famílies dels interns del mòdul 5 es queixen dels horaris de comunicacions i de lliurament de paquets. Segons el Decret 329/2006, quin òrgan del centre fixa els dies en què poden comunicar els interns i els horaris de les comunicacions i de la recepció i recollida de paquets?', 'L''art. 29.1.f) del Decret 329/2006 atribueix al Consell de Direcció la funció de fixar els dies de comunicació dels interns i establir els horaris de les comunicacions i de la recepció i recollida de paquets i encàrrecs.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 29.1.f) Decret 329/2006', 'Fixar els dies que poden comunicar els/les interns/es i establir els horaris de les comunicacions, i de la recepció i recollida de paquets i encàrrecs.', null, '3d72805ff807f4ca46a6aad6a021b4bb42bd2b0bb1fd12b02e1bebfa41b6c057', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3d72805ff807f4ca46a6aad6a021b4bb42bd2b0bb1fd12b02e1bebfa41b6c057')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director.', false), ('B', 'La Junta de Tractament.', false), ('C', 'El Consell de Direcció.', true), ('D', 'El subdirector d''interior.', false)) as v(label, body, ok)
)
