with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionari fa un comunicat de fets perquè l''intern I.O. ha comès uns fets qualificables com a falta lleu. Segons el Decret 329/2006, quin òrgan imposa la sanció per aquesta falta i amb quin procediment?', 'L''art. 12.2.h) del Decret 329/2006 atribueix al director la imposició de sancions per les infraccions lleus dels interns, amb la instrucció prèvia d''un procediment abreujat.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 12.2.h) Decret 329/2006', 'imposar les sancions per les infraccions lleus comeses pels/per les interns/es, amb la instrucció prèvia d''un procediment abreujat.', null, '0a6bc0b0bafccb8130d26785c296d39e80965fa5637ff94e124ed6568bf3ddfb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0a6bc0b0bafccb8130d26785c296d39e80965fa5637ff94e124ed6568bf3ddfb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Comissió Disciplinària, amb el procediment general.', false), ('B', 'El cap de serveis, sense necessitat de procediment.', false), ('C', 'El director, amb la instrucció prèvia d''un procediment abreujat.', true), ('D', 'La Junta de Tractament, amb un procediment abreujat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Ha acabat la instrucció de l''expedient disciplinari obert a l''intern J.P. per una falta greu en un centre penitenciari de règim ordinari. Segons el Decret 329/2006, quin òrgan l''ha de resoldre?', 'L''art. 35.2.a) del Decret 329/2006 atribueix a la Comissió Disciplinària la resolució dels expedients disciplinaris instruïts als interns per infraccions molt greus o greus.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 35.2.a) Decret 329/2006', 'Resoldre els expedients disciplinaris instruïts als/a les interns/es per la comissió d''infraccions molt greus o greus', null, '242f6e4f91e498606c0d4b1871cd778521bec9c73f0884c6a12b7021a989b415', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '242f6e4f91e498606c0d4b1871cd778521bec9c73f0884c6a12b7021a989b415')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Comissió Disciplinària.', true), ('B', 'El director.', false), ('C', 'La Junta de Tractament.', false), ('D', 'El jutge de vigilància penitenciària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Durant un incendi al mòdul 6, l''intern A.H. ajuda els funcionaris a evacuar diversos companys. El cap d''unitat proposa que se''l recompensi. Segons el Decret 329/2006, quin òrgan d''aquest centre de règim ordinari atorga la recompensa i en determina la quantia?', 'L''art. 35.2.g) del Decret 329/2006 atribueix a la Comissió Disciplinària atorgar les recompenses previstes a la legislació penitenciària, determinant-ne la quantia i ordenant-ne l''anotació a l''expedient personal (vegeu també l''art. 264.1 RP). Només en centres oberts i unitats especials ho fa la Junta de Tractament (art. 35.3).', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 35.2.g) Decret 329/2006', 'Atorgar les recompenses previstes a la legislació penitenciària, determinant en tot cas la quantia, i ordenar l''anotació de la seva concessió a l''expedient personal de la persona interna recompensada.', null, '3675fceec0e8f8d7e028bf55dba2c396c28f43c204c84157452c8a8873bb8856', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3675fceec0e8f8d7e028bf55dba2c396c28f43c204c84157452c8a8873bb8856')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director.', false), ('B', 'La Comissió Disciplinària.', true), ('C', 'La Junta de Tractament.', false), ('D', 'El Consell de Direcció.', false)) as v(label, body, ok)
)
