insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcatsup-s3-procediment-disciplinari', 'Supòsit pràctic III. Procediment disciplinari i recompenses') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s3-procediment-disciplinari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Comissió Disciplinària considera provat que l''intern F.L. va agredir un altre intern manifestant una evident agressivitat, fet constitutiu de falta molt greu. Segons l''article 233 del Reglament penitenciari, quina sanció d''aïllament en cel·la li pot imposar?', 'L''art. 233.1.a) RP preveu per a les faltes molt greus l''aïllament en cel·la de sis a catorze dies, sempre que s''hagi manifestat una evident agressivitat o violència o una alteració reiterada i greu de la convivència. L''aïllament de dilluns a divendres fins a cinc dies és per a les greus (art. 233.2.a).', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 233.1.a) RP', 'Sanción de aislamiento en celda de seis a catorce días de duración, siempre que se haya manifestado una evidente agresividad o violencia por parte del interno', null, 'c7e5eb48453760521d7e2dd1ea3f630e7aa81e9b149fe8f67af9c4ae7698a174', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c7e5eb48453760521d7e2dd1ea3f630e7aa81e9b149fe8f67af9c4ae7698a174')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De sis a catorze dies.', true), ('B', 'De dilluns a divendres, per un temps igual o inferior a cinc dies.', false), ('C', 'Fins a quaranta-dos dies.', false), ('D', 'D''un a sis dies.', false)) as v(label, body, ok)
)
