with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El director ha de resoldre un procediment abreujat obert a l''intern G.M. per una falta lleu. Segons el Reglament penitenciari, quines sancions li pot imposar?', 'L''art. 233.3 RP disposa que les faltes lleus de l''art. 110 del RP de 1981 només es poden corregir amb privació de passeigs i actes recreatius comuns de fins a tres dies i amb amonestació.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 233.3 RP', 'Las faltas leves tipificadas en el artículo 110 del Reglamento Penitenciario aprobado por el Real Decreto 1201/1981, de 8 de mayo, sólo podrán corregirse con privación de paseos y actos recreativos comunes de hasta tres días de duración y con amonestación.', null, '19b2d2733b60469edbe45d252e6b14b029931a0cc81227031fe8a7c763103d63', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '19b2d2733b60469edbe45d252e6b14b029931a0cc81227031fe8a7c763103d63')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Aïllament en cel·la de fins a cinc dies.', false), ('B', 'Privació de permisos de sortida de fins a un mes.', false), ('C', 'Limitació de les comunicacions orals durant un mes.', false), ('D', 'Privació de passeigs i actes recreatius comuns de fins a tres dies, i amonestació.', true)) as v(label, body, ok)
)
