with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El cap de serveis informa el comunicat d''un funcionari segons el qual l''intern K.Q. ha amenaçat un company de mòdul. Segons el Reglament penitenciari, qui acorda la iniciació del procediment sancionador?', 'L''art. 241.1 RP disposa que el director acorda d''ofici i motivadament la iniciació del procediment sancionador, entre altres formes per iniciativa pròpia a partir d''un comunicat de funcionari informat pel cap de serveis.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 241.1 RP', 'el Director del Establecimiento acordará de oficio y motivadamente la iniciación del procedimiento sancionador de alguna de las siguientes formas: a) Por propia iniciativa, cuando tenga conocimiento de la existencia de conductas o hechos susceptibles de constituir infracción disciplinaria a través de parte de funcionario informado por el Jefe de Servicios o por cualquier otro medio.', null, '96e3c148671be2c18b4edfb0a07d623abc4ea3853f4d692f81935da4eaf85c87', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '96e3c148671be2c18b4edfb0a07d623abc4ea3853f4d692f81935da4eaf85c87')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El cap de serveis, en el moment d''informar el comunicat.', false), ('B', 'La Comissió Disciplinària, en la sessió ordinària següent.', false), ('C', 'L''instructor que designi el subdirector d''interior.', false), ('D', 'El director, d''ofici i de manera motivada.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
