with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El director va encarregar al funcionari L.R. una informació prèvia sobre uns fets atribuïts a l''intern M.S. i ara ha de nomenar l''instructor de l''expedient disciplinari. Segons el Reglament penitenciari, quina afirmació és correcta?', 'L''art. 242.1 RP disposa que el director nomena instructor el funcionari que consideri convenient, excloent-ne el que ha practicat la informació prèvia i els que puguin estar implicats en els fets.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 242.1 RP', 'El Director nombrará Instructor al funcionario que estime conveniente, excluyendo al que haya practicado la información previa y a los que puedan estar implicados en los hechos.', null, '835e2343114e087d42a95f7b5a89c1abc1297aded4ef3218f7d682f3a8b1131f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '835e2343114e087d42a95f7b5a89c1abc1297aded4ef3218f7d682f3a8b1131f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ha de nomenar L.R., perquè és qui millor coneix els fets.', false), ('B', 'Pot nomenar el funcionari que consideri convenient, excepte L.R. i els que puguin estar implicats en els fets.', true), ('C', 'Ha de nomenar necessàriament el secretari tècnic jurídic del centre.', false), ('D', 'L''instructor l''elegeix la Comissió Disciplinària per majoria.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
