with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern A.G. dona un cop de puny a un funcionari al menjador del mòdul. Segons el Reglament penitenciari de 1981, com es qualifica aquesta conducta?', 'L''art. 108.b) del RP de 1981 qualifica de falta molt greu agredir, amenaçar o coaccionar qualsevol persona dins de l''establiment o els funcionaris d''institucions penitenciàries.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 108.b) RP 1981', 'b) Agredir, amenazar o coaccionar a cualesquiera personas dentro del establecimiento o a las autoridades o funcionarios judiciales o de instituciones penitenciarias', null, '90dfddad659c4c3bb00f479925a0dcffee78ea3c6a870d4c01de9db862810c51', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '90dfddad659c4c3bb00f479925a0dcffee78ea3c6a870d4c01de9db862810c51')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Falta greu de l''article 109.a).', false), ('B', 'Falta molt greu de l''article 108.b).', true), ('C', 'Falta greu de l''article 109.d).', false), ('D', 'Falta lleu de l''article 110.a).', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A l''hora del tancament, el funcionari ordena a l''intern B.H. que torni a la cel·la. L''intern s''hi nega i es queda assegut al pati sense oposar cap violència, de manera que el tancament del mòdul s''endarrereix i se n''altera el funcionament. Segons el Reglament penitenciari de 1981, quina falta és?', 'L''art. 109.b) del RP de 1981 qualifica de greu desobeir les ordres o resistir-s''hi passivament. La desobediència només és lleu (art. 110.b) si no causa alteració de la vida regimental i de la convivència; en el cas, l''alteració es produeix. No hi ha resistència activa (art. 108.d).', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Arts. 109.b) i 110.b) RP 1981', 'b) Desobedecer las órdenes recibidas de autoridades o funcionarios en el ejercicio legítimo de sus atribuciones o resistirse pasivamente a cumplirlas. […] b) La desobediencia de las órdenes recibidas de los funcionarios de instituciones penitenciarias en ejercicio legítimo de sus atribuciones que no causen alteración de la vida regimental y de la ordenada convivencia.', null, 'cfe360b6567b698b290b92bfe1c6f740f7bf54c0c035a217a12e0de2f5dcfad1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cfe360b6567b698b290b92bfe1c6f740f7bf54c0c035a217a12e0de2f5dcfad1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Falta greu de l''article 109.b): resistir-se passivament a complir les ordres.', true), ('B', 'Falta molt greu de l''article 108.d): resistència activa i greu.', false), ('C', 'Falta lleu de l''article 110.b): desobediència que no causa alteració de la vida regimental.', false), ('D', 'Falta lleu de l''article 110.f): incompliment genèric dels deures.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el registre de la cel·la de l''intern C.I. es troba un telèfon mòbil, objecte prohibit per les normes de règim interior del centre. Segons el Reglament penitenciari de 1981, quina falta ha comès?', 'L''art. 109.f) del RP de 1981 qualifica de falta greu introduir, fer sortir o posseir a l''establiment objectes prohibits per les normes de règim interior. L''art. 110.d) es refereix a l''ús abusiu d''objectes no prohibits.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 109.f) RP 1981', 'f) Introducir, hacer salir o poseer en el establecimiento objetos que se hallaren prohibidos por las normas de régimen interior.', null, '397cb4504245c92b37ad7c87c4e5d80df02b249a43b5789b51500b95a0440dcd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '397cb4504245c92b37ad7c87c4e5d80df02b249a43b5789b51500b95a0440dcd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Falta molt greu de l''article 108.g).', false), ('B', 'Falta lleu de l''article 110.d).', false), ('C', 'Falta molt greu de l''article 108.h).', false), ('D', 'Falta greu de l''article 109.f).', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En lloc d''utilitzar les instàncies i els canals de queixa establerts, l''intern D.J. enganxa reiteradament a les parets del menjador escrits de reclamació adreçats a la direcció. Segons el Reglament penitenciari de 1981, quina falta pot constituir aquesta conducta?', 'L''art. 110.c) del RP de 1981 qualifica de falta lleu formular reclamacions sense fer ús dels canals establerts reglamentàriament.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 110.c) RP 1981', 'c) Formular reclamaciones sin hacer uso de los cauces establecidos reglamentariamente.', null, 'f346e831f9c0fb7363d778e50a2d2b481925b0cf09b17cc13bb1626561f39327', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f346e831f9c0fb7363d778e50a2d2b481925b0cf09b17cc13bb1626561f39327')
  returning id
