with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Durant una conducció a l''hospital, l''intern E.K. intenta fugir corrent, però els agents de l''escorta l''aturen al cap de pocs metres. Segons el Reglament penitenciari de 1981, com es qualifica aquesta conducta?', 'L''art. 108.e) del RP de 1981 qualifica de falta molt greu intentar, facilitar o consumar l''evasió; per tant, també l''intent. El règim disciplinari s''aplica igualment durant els trasllats i les conduccions (art. 231.2 RP).', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 108.e) RP 1981', 'e) Intentar, facilitar o consumar la evasión.', null, '99388e7d2d84454f486632c8a5ae3b9cf016f4158b19de22ab5abefa2cc1e465', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '99388e7d2d84454f486632c8a5ae3b9cf016f4158b19de22ab5abefa2cc1e465')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Falta greu de l''article 109.b).', false), ('B', 'Falta lleu de l''article 110.f).', false), ('C', 'Falta molt greu de l''article 108.e).', true), ('D', 'No és sancionable, perquè la fuga no s''ha consumat.', false)) as v(label, body, ok)
)
