insert into public.sources (title, url, kind, publisher, published_on) values ('Resum sobre RisCanvi, el protocol de valoració del risc (Departament de Justícia, 2017)', 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament de Justícia', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e20-model-intervencio-riscanvi', 'Tema 20. El model d''intervenció, el RisCanvi i el CIRE') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e20-model-intervencio-riscanvi' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"El model d''intervenció basat en l''avaluació i la gestió del risc"},{"n":"2","title":"La necessitat d''intervenir: objectius de l''avaluació del risc"},{"n":"3","title":"Estructura de la intervenció: avaluació i gestió del risc"},{"n":"4","title":"La voluntarietat de participació de l''intern (art. 112 RP)"},{"n":"5","title":"Avaluació del risc de reincidència: criteris (violència autodirigida, intrainstitucional, reincidència violenta i general, trencament de condemna)"},{"n":"6","title":"El RisCanvi: escales Screening i completa, terminis i vigència"},{"n":"7","title":"El treball penitenciari (RD 782/2001)"},{"n":"8","title":"El Centre d''Iniciatives per a la Reinserció (Llei 23/2009 i arts. 107-109 Decret 329/2006)"}]'::jsonb, '["Web RisCanvi web RisCanvi: «L''avaluació i la gestió del risc mitjançant instruments basats en l''evidència científica és un dels components fonamentals del model d''intervenció que més aval té avui en dia de la comunitat científica i les institucions.»","Web RisCanvi web RisCanvi: «Ofereix suport als processos de presa de decisions, principalment en allò que té a veure amb la planificació de la intervenció (avalua les necessitats de cada intern i permet orientar el disseny del seu programa individual de tractament per complir amb l''itinerari de reinserció), la classificació i la concessió de permisos»","Resum RisCanvi, ap. 2 Resum RisCanvi: «El projecte, quant al seu contingut fonamental, s''estructura en dues parts en relació a la seva implementació: una que fa referència a la necessària avaluació i valoració del risc i l''altra que fa referència a la vessant de gestió d''aquest risc avaluat.»","Art. 112.3 RP: «El interno podrá rechazar libremente o no colaborar en la realización de cualquier técnica de estudio de su personalidad, sin que ello tenga consecuencias disciplinarias, regimentales ni de regresión de grado.»","Resum RisCanvi, ap. 4 Resum RisCanvi: «contribuint a desenvolupar un sistema integrat de valoració del risc de violència (en els seus tres formats principals: auto dirigida, intrainstitucional i reincidència delictiva violenta), d''avaluació de la reincidència general i de trencament de condemna.»","Resum RisCanvi, ap. 4 Resum RisCanvi: «Reincidència violenta: reingrés penitenciari per un delicte violent realitzat a la comunitat, que pot haver-lo comés després de complir la condemna, durant un permís de sortida o en qualsevol altra situació de l''intern abans d''obtenir la llibertat definitiva. Exclou les conductes violentes dins del centre penitenciari.»","Resum RisCanvi, ap. 4 Resum RisCanvi: «Trencament de condemna: no retorn d''un permís (ordinari, de cap de setmana o extraordinari) o d''una sortida programada. Evasió o fugida del centre. Trencament de la confiança de les normes o regles de conducta.»","Resum RisCanvi, ap. 4 Resum RisCanvi: «RisCanvi S està composta per 10 factors de risc»","Resum RisCanvi, ap. 4 Resum RisCanvi: «L''escala RisCanvi S, de cribratge, ha de ser administrada a l''inici de l''avaluació de l''intern i repetir-la cada sis mesos (si es el cas), per tal que tingui vigència.»","Resum RisCanvi, ap. 4 Resum RisCanvi: «Aquesta escala està formada per 43 factors que contemplen les següents àrees: criminals, personals i biogràfics, socials i familiars, clínics i de personalitat.»","Resum RisCanvi, ap. 4 Resum RisCanvi: «RisCanvi C presenta la particularitat, a diferència de RisCanvi S, que permet fer una correcció del resultat actuarial, mitjançant una decisió d''equip degudament motivada»","Resum RisCanvi, ap. 5 Resum RisCanvi: «Des de l''obertura del primer cop de l''escala RisCanvi S hi ha un termini màxim establert de 30 dies per que aquest sigui validat.»","Art. 4.1 RD 782/2001: «La finalidad esencial del trabajo es la preparación para la futura inserción laboral del interno»","Art. 2.1 Llei 23/2009: «El objeto del Centro de Iniciativas para la Reinserción es facilitar la reinserción sociolaboral de los internos en centros penitenciarios y educativos de Cataluña»","Art. 107.1 Decret 329/2006: «el qual es configurarà en cada centre penitenciari com una unitat de servei, amb entitat pròpia i representació al Consell de Direcció i a la Junta de Tractament.»","Art. 108.1 Decret 329/2006: «El treball, com a dret i deure dels/de les interns/es, es configurarà com un element fonamental del tractament pel seu caràcter formatiu i creador i conservador d''hàbits laborals»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf', null, null, null, 'Otras normas citadas: web RisCanvi (https://justicia.gencat.cat/ca/ambits/reinsercio_i_serveis_penitenciaris/serveis_penitenciaris/RisCanvi/), RP (https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307), RD 782/2001 (https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171), Llei 23/2009 (https://www.boe.es/buscar/act.php?id=BOE-A-2010-734), Decret 329/2006 (https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252)'
